{"command": "cd /workspace && cat > src/error.rs <<'EOF'
use std::fmt;

/// Error with optional "Help" and "See also" lines, plus a cause chain.
pub struct SgError {
    pub message: String,
    pub help: Option<String>,
    pub url: Option<String>,
    pub cause: Option<String>,
}

impl SgError {
    pub fn new(message: impl Into<String>) -> Self {
        SgError { message: message.into(), help: None, url: None, cause: None }
    }
    pub fn help(mut self, h: impl Into<String>) -> Self { self.help = Some(h.into()); self }
    pub fn url(mut self, u: impl Into<String>) -> Self { self.url = Some(u.into()); self }
    pub fn cause(mut self, c: impl Into<String>) -> Self { self.cause = Some(c.into()); self }
    pub fn render(&self) -> String {
        let mut out = String::new();
        out.push_str(&format!("Error: {}\n", self.message));
        if let Some(h) = &self.help {
            out.push_str(&format!("Help: {}\n", h));
        }
        if let Some(u) = &self.url {
            out.push_str(&format!("See also: {}\n", u));
        }
        if let Some(c) = &self.cause {
            out.push_str("\n\u{2716} Caused by\n\u{2570}\u{25bb} ");
            out.push_str(c);
            out.push('\n');
        }
        out
    }
}

impl fmt::Debug for SgError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

pub type Res<T> = Result<T, SgError>;

pub const PATTERN_URL: &str = "https://ast-grep.github.io/guide/pattern-syntax.html";
pub const RULE_URL: &str = "https://ast-grep.github.io/guide/rule-config.html";
pub const TEST_URL: &str = "https://ast-grep.github.io/guide/test-rule.html";
pub const STDIN_URL: &str =
    "https://ast-grep.github.io/guide/tooling-overview.html#parse-code-from-stdin";
pub const PLAYGROUND_URL: &str = "https://ast-grep.github.io/playground.html";
EOF
echo written"}

