    let mut p = Arg::new("paths").value_name("PATHS").action(ArgAction::Append)
        .help("The paths to search");
    p = match num_args {
        "0.." => p.num_args(..),
        "1.." => p.num_args(1..),
        _ => p.num_args(..),
    };
    if def { p = p.default_value("."); }
    if req_paths { p = p.required(true); }
    Command::new("ast-grep").version("0.1")
        .arg(Arg::new("pattern").short('p').long("pattern").value_name("PATTERN").required(true))
        .arg(Arg::new("lang").short('l').long("lang").value_name("LANG"))
        .arg(Arg::new("debugQuery").long("debug-query").value_name("format").num_args(0..=1).require_equals(true).requires("lang"))
        .arg(p)
        .arg_required_else_help(false)
}
fn show(tag: &str, cmd: Command) {
    let mut c = cmd.clone().bin_name("executable"); c.build();
    println!("=== {} help:", tag);
    let _ = c.print_help();
    println!();
    println!("=== {} err:", tag);
    match c.clone().try_get_matches_from_mut(vec!["executable", "--debug-query", "pattern"]) {
        Ok(_) => println!("ok"),
        Err(e) => println!("{}", e),
    }
    println!("=== {} err2:", tag);
    match c.clone().try_get_matches_from_mut(vec!["executable", "--json"]) {
        Ok(_) => println!("ok"),
        Err(e) => println!("{}", e),
    }
}
fn main() {
    show("notreq+default+0..", build(false, "0..", true));
    show("req+default+0..", build(true, "0..", true));
    show("req+nodefault+0..", build(true, "0..", false));
}
EOF
