//! A light-weight syntax tree, structurally compatible with tree-sitter trees.
#[derive(Clone, Debug)]
pub struct Node {
    pub kind: &'static str,
    pub named: bool,
    pub field: Option<&'static str>,
    pub start: usize,
    pub end: usize,
    pub children: Vec<u32>,
    pub parent: u32,
    pub is_error: bool,
    pub is_extra: bool,
}

pub const NONE: u32 = u32::MAX;

#[derive(Clone)]
pub struct Tree {
    pub nodes: Vec<Node>,
    pub root: u32,
}

impl Tree {
    pub fn node(&self, id: u32) -> &Node { &self.nodes[id as usize] }
    pub fn children(&self, id: u32) -> &[u32] { &self.nodes[id as usize].children }
    pub fn kind(&self, id: u32) -> &'static str { self.nodes[id as usize].kind }
    pub fn named(&self, id: u32) -> bool { self.nodes[id as usize].named }
    pub fn start(&self, id: u32) -> usize { self.nodes[id as usize].start }
    pub fn end(&self, id: u32) -> usize { self.nodes[id as usize].end }
    pub fn text(&self, src: &str, id: u32) -> &str { &src[self.nodes[id as usize].start..self.nodes[id as usize].end] }
    pub fn field(&self, id: u32) -> Option<&'static str> { self.nodes[id as usize].field }

    pub fn named_children(&self, id: u32) -> Vec<u32> {
        self.nodes[id as usize].children.iter().copied().filter(|&c| self.nodes[c as usize].named).collect()
    }

    pub fn child_by_field_name(&self, id: u32, field: &str) -> Option<u32> {
        self.nodes[id as usize]
            .children
            .iter()
            .copied()
            .find(|&c| self.nodes[c as usize].field == Some(field_str(field)))
    }

    pub fn is_ancestor(&self, anc: u32, node: u32) -> bool {
        let mut cur = self.nodes[node as usize].parent;
        while cur != NONE {
            if cur == anc { return true; }
            cur = self.nodes[cur as usize].parent;
        }
        false
    }

    pub fn parent(&self, id: u32) -> Option<u32> {
        let p = self.nodes[id as usize].parent;
        if p == NONE { None } else { Some(p) }
    }

    pub fn next_sibling(&self, id: u32) -> Option<u32> {
        let p = self.nodes[id as usize].parent;
        if p == NONE { return None; }
        let sibs = &self.nodes[p as usize].children;
        let idx = sibs.iter().position(|&c| c == id)?;
        sibs.get(idx + 1).copied()
    }

    pub fn prev_sibling(&self, id: u32) -> Option<u32> {
        let p = self.nodes[id as usize].parent;
        if p == NONE { return None; }
        let sibs = &self.nodes[p as usize].children;
        let idx = sibs.iter().position(|&c| c == id)?;
        if idx == 0 { None } else { Some(sibs[idx - 1]) }
    }

    pub fn set_parents(&mut self) {
        for i in 0..self.nodes.len() {
            let kids = std::mem::take(&mut self.nodes[i].children);
            let me = i as u32;
            for &c in &kids {
                if (c as usize) < self.nodes.len() {
                    self.nodes[c as usize].parent = me;
                }
            }
            self.nodes[i].children = kids;
        }
    }
}

thread_local! {
    static FIELDS: Vec<&'static str> = Vec::new();
}

/// Intern short-lived field names into stable static pointers so that
/// `field == Some("name")` comparisons stay cheap.
pub fn field_str(s: &str) -> &'static str {
    FIELDS.with(|f| {
        if let Some(x) = f.iter().find(|x| **x == s) { return *x; }
        // Fall back: leak the string (rare path, only for dynamic lookups).
        let leaked: &'static str = Box::leak(s.to_string().into_boxed_str());
        // cannot push into a thread-local vec from inside `with` easily; use leak + cache
        leaked
    })
}
