//! Shared parser infrastructure: cursor, token helpers, node construction.

use crate::lang::Lang;
use crate::tree::{Node, Tree, NONE};

pub struct P<'a> {
    pub s: &'a [u8],
    pub i: usize,
    pub nodes: Vec<Node>,
}

impl<'a> P<'a> {
    pub fn new(s: &'a str) -> Self {
        P { s: s.as_bytes(), i: 0, nodes: Vec::new() }
    }

    pub fn len(&self) -> usize { self.s.len() }
    pub fn cur(&self) -> u8 { if self.i < self.s.len() { self.s[self.i] } else { 0 } }
    pub fn cur2(&self) -> u8 { if self.i + 1 < self.s.len() { self.s[self.i + 1] } else { 0 } }
    pub fn cur3(&self) -> u8 { if self.i + 2 < self.s.len() { self.s[self.i + 2] } else { 0 } }
    pub fn eof(&self) -> bool { self.i >= self.s.len() }

    pub fn text_at(&self, t: &str) -> bool {
        let b = t.as_bytes();
        self.s.len() >= self.i + b.len() && &self.s[self.i..self.i + b.len()] == b
    }

    pub fn is_word(&self, c: u8) -> bool {
        c.is_ascii_alphanumeric() || c == b'_' || c == b'$' || c >= 0x80
    }

    /// Does an identifier char immediately follow position `pos`?
    fn word_follows(&self, pos: usize) -> bool {
        pos < self.s.len() && self.is_word(self.s[pos])
    }

    /// Consume a word/keyword; produces an unnamed node whose kind is the text.
    pub fn kw(&mut self, w: &'static str) -> Option<u32> {
        if self.text_at(w) && !self.word_follows(self.i + w.len()) {
            self.i += w.len();
            Some(self.make(w, false))
        } else {
            None
        }
    }

    /// Consume a word/keyword case-insensitively (for keywords with odd casing).
    pub fn kw_ci(&mut self, w: &'static str) -> Option<u32> {
        let b = w.as_bytes();
        if self.i + b.len() <= self.s.len()
            && self.s[self.i..self.i + b.len()].eq_ignore_ascii_case(b)
            && !self.word_follows(self.i + b.len())
        {
            self.i += b.len();
            Some(self.make(w, false))
        } else {
            None
        }
    }

    /// Consume a literal (punctuation/operator) token; unnamed node.
    pub fn lit(&mut self, l: &'static str) -> Option<u32> {
        if self.text_at(l) && !self.word_follows(self.i + l.len()) {
            self.i += l.len();
            Some(self.make(l, false))
        } else {
            None
        }
    }

    /// Build a node spanning [start, current position).
    pub fn make(&mut self, kind: &'static str, named: bool) -> u32 {
        let start = self.nodes.last().map(|n| n.end).unwrap_or(0);
        self.make_span(kind, named, start)
    }

    pub fn make_span(&mut self, kind: &'static str, named: bool, start: usize) -> u32 {
        let id = self.nodes.len() as u32;
        self.nodes.push(Node {
            kind,
            named,
            field: None,
            start,
            end: self.i,
            children: Vec::new(),
            parent: NONE,
            is_error: kind == "ERROR",
        });
        id
    }

    pub fn set_field(&mut self, id: u32, field: &str) {
        if let Some(f) = crate::tree::field_idx(field) {
            self.nodes[id as usize].field = Some(f);
        }
    }

    /// Skip whitespace and comments, pushing comment nodes into `out`.
    pub fn ws(&mut self, out: &mut Vec<u32>, lang: Lang) {
        loop {
            let c = self.cur();
            match c {
                b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c => {
                    self.i += 1;
                    // unicode whitespace
                }
                _ if c >= 0x80 => {
                    // UTF-8 whitespace / BOM
                    if self.s[self.i..].starts_with(&[0xef, 0xbb, 0xbf]) {
                        self.i += 3;
                        continue;
                    }
                    break;
                }
                _ => {
                    if let Some(cm) = self.try_comment(lang) {
                        out.push(cm);
                    } else {
                        break;
                    }
                }
            }
        }
    }

    fn try_comment(&mut self, lang: Lang) -> Option<u32> {
        let kind = comment_kind(lang)?;
        match lang {
            Lang::Python => {
                if self.cur() == b'#' {
                    let start = self.i;
                    while !self.eof() && self.cur() != b'\n' { self.i += 1; }
                    return Some(self.make_span(kind, true, start));
                }
                None
            }
            Lang::Html => {
                if self.text_at("<!--") {
                    let start = self.i;
                    self.i += 4;
                    while !self.eof() && !self.text_at("-->") { self.i += 1; }
                    if self.text_at("-->") { self.i += 3; }
                    return Some(self.make_span("comment", true, start));
                }
                None
            }
            Lang::Json | Lang::Yaml | Lang::Css | Lang::Nix | Lang::Hcl | Lang::Haskell
            | Lang::Lua | Lang::Ruby | Lang::Php | Lang::Elixir | Lang::Kotlin | Lang::Swift
            | Lang::Scala | Lang::Dart | Lang::CSharp | Lang::Rust | Lang::Go | Lang::Java
            | Lang::C | Lang::Cpp | Lang::Solidity | Lang::JavaScript | Lang::TypeScript
            | Lang::Tsx | Lang::Bash => {
                let mut k = kind;
                if lang == Lang::Css {
                    k = "comment";
                }
                if self.cur() == b'#' && matches!(lang, Lang::Yaml | Lang::Bash | Lang::Ruby | Lang::Elixir | Lang::Nix | Lang::Lua | Lang::Php) {
                    let start = self.i;
                    while !self.eof() && self.cur() != b'\n' { self.i += 1; }
                    return Some(self.make_span(k, true, start));
                }
                if self.cur() == b'-' && matches!(lang, Lang::Haskell | Lang::Lua) {
                    let start = self.i;
                    self.i += 2;
                    while !self.eof() && self.cur() != b'\n' { self.i += 1; }
                    return Some(self.make_span(k, true, start));
                }
                if self.text_at("/*") {
                    let start = self.i;
                    self.i += 2;
                    while !self.eof() && !self.text_at("*/") { self.i += 1; }
                    if self.text_at("*/") { self.i += 2; }
                    return Some(self.make_span(k, true, start));
                }
                if self.text_at("//") {
                    let start = self.i;
                    self.i += 2;
                    while !self.eof() && self.cur() != b'\n' { self.i += 1; }
                    return Some(self.make_span(k, true, start));
                }
                None
            }
        }
    }
}

fn comment_kind(lang: Lang) -> Option<&'static str> {
    Some(match lang {
        Lang::JavaScript | Lang::TypeScript | Lang::Tsx => "comment",
        Lang::Python => "comment",
        Lang::Json => "comment",
        Lang::Yaml => "comment",
        Lang::Css => "comment",
        Lang::Html => "comment",
        Lang::Bash => "comment",
        Lang::Rust => "line_comment",
        Lang::Go => "comment",
        Lang::Java => "line_comment",
        Lang::C | Lang::Cpp => "comment",
        Lang::CSharp => "comment",
        Lang::Kotlin => "line_comment",
        Lang::Swift => "comment",
        Lang::Ruby => "comment",
        Lang::Php => "comment",
        Lang::Lua => "comment",
        Lang::Haskell => "comment",
        Lang::Scala => "comment",
        Lang::Dart => "comment",
        Lang::Elixir => "comment",
        Lang::Solidity => "comment",
        Lang::Nix => "comment",
        Lang::Hcl => "comment",
    })
}

/// Parse `src` with the language's parser, returning a tree whose root is a
/// top level container node (`program`, `module`, ...).
pub fn parse(lang: Lang, src: &str) -> Tree {
    let mut p = crate::parser::imp::parse_with(lang, src);
    p.set_parents();
    let root = if p.nodes.is_empty() { 0 } else { (p.nodes.len() - 1) as u32 };
    Tree { nodes: p.nodes, root }
}
