//! Per-language parser implementations.
use crate::lang::Lang;
use crate::parser::P;

pub fn parse_with(lang: Lang, src: &str) -> P {
    let mut p = P::new(src);
    match lang {
        Lang::JavaScript | Lang::TypeScript | Lang::Tsx => crate::parser::js::parse_program(&mut p),
        Lang::Python => crate::parser::py::parse_program(&mut p),
        Lang::Json => crate::parser::json::parse_program(&mut p),
        Lang::Yaml => crate::parser::yaml::parse_program(&mut p),
        Lang::Css => crate::parser::css::parse_program(&mut p),
        Lang::Html => crate::parser::html::parse_program(&mut p),
        Lang::Bash => crate::parser::bash::parse_program(&mut p),
        _ => crate::parser::generic::parse_program(&mut p, lang),
    }
    // Any trailing unparsed content becomes an ERROR node.
    if p.i < p.s.len() {
        let start = p.i;
        p.i = p.s.len();
        let mut kids = Vec::new();
        let _ = &mut kids;
        p.make_span("ERROR", true, start);
    }
    p
}
