    pub meta: Vec<(u32, MetaVarKind, String)>,
    pub strictness: Strictness,
    pub root_is_error: bool,
}

pub fn is_meta_var(text: &str) -> Option<(MetaVarKind, String)> {
    let bytes = text.as_bytes();
    if bytes.first() != Some(&b'$') {
        return None;
    }
    let mut n = 0usize;
    while n < bytes.len() && bytes[n] == b'$' {
        n += 1;
    }
    if n > 3 { return None; }
    let name = &text[n..];
    if name.is_empty() { return None; }
    let cb = name.as_bytes();
    if !(cb[0].is_ascii_uppercase() || cb[0] == b'_') { return None; }
    if !cb.iter().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || *c == b'_') {
        return None;
    }
    let kind = if n == 3 { MetaVarKind::Multi } else { MetaVarKind::Single };
    Some((kind, name.to_string()))
}

/// Find the pattern root: walk down while a node has exactly one child.
fn find_root(tree: &Tree) -> Result<u32, SgError> {
    let mut node = tree.root;
    loop {
        let kids = tree.node(node).children.clone();
        if kids.is_empty() {
            // A container with no children: still a valid (empty) root.
            return Ok(node);
        }
        if kids.len() == 1 {
            node = kids[0];
            continue;
        }
        return Err(SgError::new("Cannot parse query as a valid pattern.")
            .help("The pattern either fails to parse or contains error. Please refer to pattern syntax guide.")
            .url(PATTERN_URL)
            .cause("Multiple AST nodes are detected. Please check the pattern source ``."));
    }
}

