    let tree = parse(lang, src);
    let root_node = tree.root;
    let kids = tree.node(root_node).children.clone();
    if kids.is_empty() {
        return Err(SgError::new("Cannot parse query as a valid pattern.")
            .help("The pattern either fails to parse or contains error. Please refer to pattern syntax guide.")
            .url(PATTERN_URL)
            .cause(format!("No AST root is detected. Please check the pattern source `{}`.", src)));
    }
    let mut root = if let Some(sel) = opts.selector {
        // Find the first node of the given kind in the tree.
        let mut found = None;
        tree.walk(root_node, &mut |id| {
            if found.is_none() && tree.kind(id) == sel {
                found = Some(id);
            }
        });
        match found {
            Some(f) => f,
            None => {
                return Err(SgError::new(format!("Selector `{}` is invalid in this language.", sel))
                    .help("Selector must be a valid AST kind in the language."))
            }
        }
    } else {
        match find_root(&tree) {
            Ok(r) => r,
            Err(mut e) => {
                if let Some(c) = &mut e.cause {
