//! Structural matching between a pattern tree and a source tree.

use crate::pattern::{MetaVarKind, Pattern, Strictness};
use crate::tree::Tree;

#[derive(Default, Debug, Clone)]
pub struct MetaVars {
    pub single: Vec<(String, u32)>,
    pub multi: Vec<(String, Vec<u32>)>,
}

impl MetaVars {
    pub fn get_single(&self, name: &str) -> Option<u32> {
        self.single.iter().find(|(n, _)| n == name).map(|(_, id)| *id)
    }
    pub fn insert_single(&mut self, name: &str, id: u32) {
        match self.single.iter_mut().find(|(n, _)| n == name) {
            Some(e) => e.1 = id,
            None => self.single.push((name.to_string(), id)),
        }
    }
    pub fn insert_multi(&mut self, name: &str, ids: Vec<u32>) {
        match self.multi.iter_mut().find(|(n, _)| n == name) {
            Some(e) => e.1 = ids,
            None => self.multi.push((name.to_string(), ids)),
        }
    }
}

pub struct Matcher<'a> {
    pub pt: &'a Tree,
    pub st: &'a Tree,
    pub src: &'a str,
    pub strictness: Strictness,
}

impl<'a> Matcher<'a> {
    fn meta_at(&self, p: u32) -> Option<(MetaVarKind, &'a String)> {
        self.pt.meta.iter().find(|(id, _, _)| *id == p).map(|(_, k, n)| (*k, n))
    }

    fn is_meta(&self, p: u32) -> bool { self.pt.meta.iter().any(|(id, _, _)| *id == p) }

    /// Which children of a node participate in matching for this strictness.
    fn relevant(&self, id: u32) -> Vec<u32> {
        match self.strictness {
            Strictness::Cst | Strictness::Smart | Strictness::Template => {
                self.st.node(id).children.clone()
            }
            Strictness::Ast => self.st.named_children(id),
            Strictness::Relaxed | Strictness::Signature => self
                .st
                .named_children(id)
                .into_iter()
                .filter(|&c| self.st.kind(c) != "comment")
                .collect(),
        }
    }

    fn pat_children(&self, p: u32) -> Vec<u32> {
        match self.strictness {
            Strictness::Cst | Strictness::Smart | Strictness::Template => {
                self.pt.node(p).children.clone()
            }
            Strictness::Ast => self.pt.named_children(p),
            Strictness::Relaxed | Strictness::Signature => self
                .pt
                .named_children(p)
                .into_iter()
                .filter(|&c| self.pt.kind(c) != "comment")
                .collect(),
        }
    }

    fn skip_unnamed(&self, id: u32) -> bool {
        match self.strictness {
            Strictness::Cst | Strictness::Template => false,
            Strictness::Smart => !self.st.named(id),
            Strictness::Ast | Strictness::Relaxed | Strictness::Signature => false,
        }
    }

    fn cmp_text(&self, p: u32, s: u32) -> bool {
        self.pt.text(self.src, p) == self.st.text(self.src, s)
    }

    pub fn match_node(&self, p: u32, s: u32, vars: &mut MetaVars) -> bool {
        // meta variables
        if let Some((kind, name)) = self.meta_at(p) {
            match kind {
                MetaVarKind::Single => {
                    if name.starts_with('_') {
                        return true;
                    }
                    if let Some(prev) = vars.get_single(name) {
                        return self.st.text(self.src, prev) == self.st.text(self.src, s);
                    }
                    vars.insert_single(name, s);
                    return true;
                }
                MetaVarKind::Multi => {
                    // A multi meta var must be handled in sequence matching.
                    return false;
                }
            }
        }
        let pk = self.pt.kind(p);
        let sk = self.st.kind(s);
        // ERROR nodes in the pattern match any *named* node with matching children.
        if pk == "ERROR" {
            if sk == "ERROR" {
                return self.match_children(p, s, vars);
            }
            if !self.st.named(s) {
                return false;
            }
            return self.match_children(p, s, vars);
        }
        match self.strictness {
            Strictness::Template => {
                let pk = self.pt.node(p).children.is_empty();
                let sk = self.st.node(s).children.is_empty();
                if pk && sk {
                    return self.cmp_text(p, s);
                }
                if !pk && sk {
                    // Compare the flattened text of both.
                    return self.cmp_text(p, s);
                }
                if pk && !sk {
                    return self.cmp_text(p, s);
                }
                self.match_children(p, s, vars)
            }
            Strictness::Signature => {
                if !pk_eq(pk, sk) {
                    return false;
                }
                if self.pt.node(p).children.is_empty() && self.st.node(s).children.is_empty() {
                    return true;
                }
                self.match_children(p, s, vars)
            }
            _ => {
                if pk != sk {
                    return false;
                }
                if self.pt.node(p).children.is_empty() && self.st.node(s).children.is_empty() {
                    return self.cmp_text(p, s);
                }
                self.match_children(p, s, vars)
            }
        }
    }

    fn match_children(&self, p: u32, s: u32, vars: &mut MetaVars) -> bool {
        let pc = self.pat_children(p);
        let sc = self.relevant(s);
        self.match_seq(&pc, &sc, vars)
    }

    pub fn match_seq(&self, pc: &[u32], sc: &[u32], vars: &mut MetaVars) -> bool {
        match self.strictness {
            Strictness::Cst | Strictness::Ast | Strictness::Relaxed | Strictness::Signature => {
                if pc.len() != sc.len() {
                    return false;
                }
                for (i, &p) in pc.iter().enumerate() {
                    if let Some((MetaVarKind::Multi, name)) = self.meta_at(p) {
                        // multi meta var in an exact match: capture the rest
                        let rest: Vec<u32> = sc[i..].to_vec();
                        if name.starts_with('_') {
                            return true;
                        }
                        vars.insert_multi(name, rest);
                        return true;
                    }
                    if !self.match_node(p, sc[i], vars) {
                        return false;
                    }
                }
                true
            }
            Strictness::Smart => self.match_seq_smart(pc, sc, vars),
            Strictness::Template => {
                if pc.len() != sc.len() {
                    return false;
                }
                for (i, &p) in pc.iter().enumerate() {
                    if let Some((MetaVarKind::Multi, _)) = self.meta_at(p) {
                        return true;
                    }
                    if !self.match_node(p, sc[i], vars) {
                        return false;
                    }
                }
                true
            }
        }
    }

    fn match_seq_smart(&self, pc: &[u32], sc: &[u32], vars: &mut MetaVars) -> bool {
        self.smart_rec(pc, 0, sc, 0, vars)
    }

    fn smart_rec(
        &self,
        pc: &[u32],
        pi: usize,
        sc: &[u32],
        si: usize,
        vars: &mut MetaVars,
    ) -> bool {
        if pi >= pc.len() {
            return true; // tolerate trailing source nodes
        }
        let p = pc[pi];
        if let Some((MetaVarKind::Multi, name)) = self.meta_at(p) {
            if name.starts_with('_') {
                return self.smart_rec(pc, pi + 1, sc, si, vars);
            }
            let mut k = 0usize;
            while si + k <= sc.len() {
                let before = vars.multi.len();
                vars.insert_multi(name, sc[si..si + k].to_vec());
                if self.smart_rec(pc, pi + 1, sc, si + k, vars) {
                    return true;
                }
                vars.multi.truncate(before);
                k += 1;
            }
            vars.multi.truncate(vars.multi.len());
            return false;
        }
        let mut j = si;
        loop {
            if j >= sc.len() {
                return false;
            }
            let snapshot = vars.clone();
            if self.match_node(p, sc[j], vars) && self.smart_rec(pc, pi + 1, sc, j + 1, vars) {
                return true;
            }
            *vars = snapshot;
            if self.skip_unnamed(sc[j]) {
                j += 1;
                continue;
            }
            return false;
        }
    }
}

fn pk_eq(a: &str, b: &str) -> bool { a == b }
