//! Pattern parsing: turn a snippet of code into a matchable pattern tree.

use crate::error::{SgError, PATTERN_URL};
use crate::lang::Lang;
use crate::tree::Tree;
use crate::parser::parse;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Strictness {
    Cst,
    Smart,
    Ast,
    Relaxed,
    Signature,
    Template,
}

impl Strictness {
    pub fn from_str(s: &str) -> Option<Strictness> {
        Some(match s {
            "cst" => Strictness::Cst,
            "smart" => Strictness::Smart,
            "ast" => Strictness::Ast,
            "relaxed" => Strictness::Relaxed,
            "signature" => Strictness::Signature,
            "template" => Strictness::Template,
            _ => return None,
        })
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum MetaVarKind {
    Single,
    Multi,
}

pub struct Pattern {
    pub tree: Tree,
    pub root: u32,
    /// node id -> meta variable
    pub meta: Vec<(u32, MetaVarKind, String)>,
    pub strictness: Strictness,
    pub root_is_error: bool,
}

pub fn is_meta_var(text: &str) -> Option<(MetaVarKind, String)> {
    let bytes = text.as_bytes();
    if bytes.first() != Some(&b'$') {
        return None;
    }
    let mut n = 0usize;
    while n < bytes.len() && bytes[n] == b'$' {
        n += 1;
    }
    if n > 3 { return None; }
    let name = &text[n..];
    if name.is_empty() { return None; }
    let cb = name.as_bytes();
    if !(cb[0].is_ascii_uppercase() || cb[0] == b'_') { return None; }
    if !cb.iter().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || *c == b'_') {
        return None;
    }
    let kind = if n == 3 { MetaVarKind::Multi } else { MetaVarKind::Single };
    Some((kind, name.to_string()))
}

/// Find the pattern root: walk down while a node has exactly one child.
fn find_root(tree: &Tree) -> Result<u32, SgError> {
    let mut node = tree.root;
    loop {
        let kids = tree.node(node).children.clone();
        if kids.is_empty() {
            // A container with no children: still a valid (empty) root.
            return Ok(node);
        }
        if kids.len() == 1 {
            node = kids[0];
            continue;
        }
        return Err(SgError::new("Cannot parse query as a valid pattern.")
            .help("The pattern either fails to parse or contains error. Please refer to pattern syntax guide.")
            .url(PATTERN_URL)
            .cause("Multiple AST nodes are detected. Please check the pattern source ``."));
    }
}

pub struct PatternOpts<'a> {
    pub selector: Option<&'a str>,
    pub strictness: Strictness,
}

pub fn build_pattern(lang: Lang, src: &str, opts: &PatternOpts) -> Result<Pattern, SgError> {
    let tree = parse(lang, src);
    let root_node = tree.root;
    let kids = tree.node(root_node).children.clone();
    if kids.is_empty() {
        return Err(SgError::new("Cannot parse query as a valid pattern.")
            .help("The pattern either fails to parse or contains error. Please refer to pattern syntax guide.")
            .url(PATTERN_URL)
            .cause(format!("No AST root is detected. Please check the pattern source `{}`.", src)));
    }
    let mut root = if let Some(sel) = opts.selector {
        // Find the first node of the given kind in the tree.
        let mut found = None;
        tree.walk(root_node, &mut |id| {
            if found.is_none() && tree.kind(id) == sel {
                found = Some(id);
            }
        });
        match found {
            Some(f) => f,
            None => {
                return Err(SgError::new(format!("Selector `{}` is invalid in this language.", sel))
                    .help("Selector must be a valid AST kind in the language."))
            }
        }
    } else {
        match find_root(&tree) {
            Ok(r) => r,
            Err(mut e) => {
                if let Some(c) = &mut e.cause {
                    *c = c.replace("``", &format!("`{}`", src));
                }
                return Err(e);
            }
        }
    };

    let mut meta = Vec::new();
    let mut root_is_error = false;
    tree.walk(root, &mut |id| {
        let t = tree.text(src, id);
        if let Some((kind, name)) = is_meta_var(t) {
            meta.push((id, kind, name));
        }
    });
    if tree.kind(root) == "ERROR" {
        root_is_error = true;
    }
    Ok(Pattern { tree, root, meta, strictness: opts.strictness, root_is_error })
}
