//! JavaScript / TypeScript / TSX parser producing tree-sitter compatible node kinds.

use crate::lang::Lang;
use crate::parser::P;

type Kids = Vec<u32>;

fn kw(p: &mut P, w: &'static str, out: &mut Kids) -> bool {
    if let Some(id) = p.kw(w) { out.push(id); true } else { false }
}
fn lit(p: &mut P, l: &'static str, out: &mut Kids) -> bool {
    if let Some(id) = p.lit(l) { out.push(id); true } else { false }
}
fn ws(p: &mut P, out: &mut Kids, lang: Lang) {
    p.ws(out, lang);
}
fn field(p: &mut P, id: u32, f: &'static str) {
    p.set_field(id, f);
}

fn is_lang_ts(lang: Lang) -> bool {
    matches!(lang, Lang::TypeScript | Lang::Tsx)
}
fn is_lang_jsx(lang: Lang) -> bool {
    matches!(lang, Lang::JavaScript | Lang::TypeScript | Lang::Tsx)
}

// ---------------------------------------------------------------- identifiers

fn parse_identifier(p: &mut P) -> Option<u32> {
    let start = p.i;
    let c = p.cur();
    if !(c.is_ascii_alphabetic() || c == b'_' || c == b'$' || c >= 0x80) {
        return None;
    }
    while !p.eof() {
        let c = p.cur();
        if c.is_ascii_alphanumeric() || c == b'_' || c == b'$' || c >= 0x80 {
            p.i += 1;
        } else {
            break;
        }
    }
    Some(p.make_span("identifier", true, start))
}

fn parse_property_identifier(p: &mut P) -> Option<u32> {
    let start = p.i;
    let c = p.cur();
    if !(c.is_ascii_alphabetic() || c == b'_' || c == b'$' || c.is_ascii_digit() || c >= 0x80) {
        return None;
    }
    while !p.eof() {
        let c = p.cur();
        if c.is_ascii_alphanumeric() || c == b'_' || c == b'$' || c >= 0x80 {
            p.i += 1;
        } else {
            break;
        }
    }
    Some(p.make_span("property_identifier", true, start))
}

fn parse_private_property_identifier(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'#' { return None; }
    p.i += 1;
    while !p.eof() {
        let c = p.cur();
        if c.is_ascii_alphanumeric() || c == b'_' || c == b'$' { p.i += 1 } else { break }
    }
    Some(p.make_span("private_property_identifier", true, start))
}

// ------------------------------------------------------------------- literals

fn parse_number(p: &mut P) -> Option<u32> {
    let start = p.i;
    let c = p.cur();
    if !(c.is_ascii_digit() || (c == b'.' && p.cur2().is_ascii_digit())) {
        return None;
    }
    if c == b'0' && (p.cur2() == b'b' || p.cur2() == b'o' || p.cur2() == b'x') {
        p.i += 2;
        while !p.eof() && (p.cur().is_ascii_alphanumeric() || p.cur() == b'_') { p.i += 1 }
        return Some(p.make_span("number", true, start));
    }
    let mut seen_dot = false;
    let mut seen_exp = false;
    while !p.eof() {
        let c = p.cur();
        if c.is_ascii_digit() || c == b'_' {
            p.i += 1;
        } else if c == b'.' && !seen_dot && !seen_exp {
            seen_dot = true;
            p.i += 1;
        } else if (c == b'e' || c == b'E')
            && !seen_exp
            && p.i > start
            && (p.cur2().is_ascii_digit()
                || ((p.cur2() == b'+' || p.cur2() == b'-') && {
                    let k = p.i + 2;
                    k < p.s.len() && p.s[k].is_ascii_digit()
                }))
        {
            seen_exp = true;
            p.i += 1;
            if p.cur() == b'+' || p.cur() == b'-' { p.i += 1 }
        } else if (c == b'n' || c == b'x' || c == b'b' || c == b'o') && p.i > start {
            p.i += 1;
            return Some(p.make_span("number", true, start));
        } else {
            break;
        }
    }
    if p.i == start { return None; }
    Some(p.make_span("number", true, start))
}

fn parse_escape(p: &mut P, out: &mut Kids, kind: &'static str) {
    let start = p.i;
    if p.cur() == b'\\' {
        p.i += 1;
        // unicode escapes
        if p.cur() == b'u' || p.cur() == b'x' {
            p.i += 1;
            if p.cur() == b'{' {
                while !p.eof() && p.cur() != b'}' { p.i += 1 }
                if p.cur() == b'}' { p.i += 1 }
            } else {
                let n = if p.cur() == b'u' { 4 } else { 2 };
                for _ in 0..n {
                    if p.cur().is_ascii_hexdigit() { p.i += 1 } else { break }
                }
            }
        } else if !p.eof() {
            p.i += 1;
        }
    }
    out.push(p.make_span(kind, true, start));
}

fn parse_string(p: &mut P) -> Option<u32> {
    let start = p.i;
    let quote = p.cur();
    if quote != b'"' && quote != b'\'' { return None; }
    let mut kids = Kids::new();
    kids.push(p.make_span("\"", false, start));
    p.i += 1;
    // string_fragment
    let fs = p.i;
    let mut esc = Kids::new();
    while !p.eof() && p.cur() != quote {
        if p.cur() == b'\\' {
            if p.i > fs { esc.push(p.make_span("string_fragment", true, fs)); }
            parse_escape(p, &mut esc, "escape_sequence");
            p.ws(&mut esc, Lang::JavaScript);
            break;
        }
        p.i += 1;
    }
    if p.i > fs {
        esc.push(p.make_span("string_fragment", true, fs));
    }
    // single fragment case: string_fragment directly
    let frag = esc.pop();
    if let Some(f) = frag { kids.push(f); }
    if p.cur() == quote {
        let qs = p.i;
        p.i += 1;
        kids.push(p.make_span("\"", false, qs));
    }
    let mut all_named = kids.iter().all(|&k| p.nodes[k as usize].named);
    if kids.len() == 1 && !all_named {
        // unterminated string: keep as is
        all_named = false;
    }
    let _ = all_named;
    Some(p.make_span("string", true, start))
}

fn parse_template_string(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'`' { return None; }
    let mut kids = Kids::new();
    kids.push(p.make_span("`", false, start));
    p.i += 1;
    loop {
        if p.eof() { break }
        if p.cur() == b'`' {
            let s = p.i;
            p.i += 1;
            kids.push(p.make_span("`", false, s));
            break;
        }
        if p.cur() == b'\\' {
            let mut esc = Kids::new();
            parse_escape(p, &mut esc, "escape_sequence");
            kids.extend(esc);
            continue;
        }
        if p.cur() == b'$' && p.cur2() == b'{' {
            let ss = p.i;
            p.i += 2;
            let mut sub = Kids::new();
            sub.push(p.make_span("${", false, ss));
            ws(p, &mut sub, Lang::JavaScript);
            let inner_start = p.i;
            let mut inner = Kids::new();
            if parse_expression(p, &mut inner, 0) {
                sub.extend(inner);
            } else {
                p.i = inner_start;
            }
            ws(p, &mut sub, Lang::JavaScript);
            let _ = lit(p, "}", &mut sub);
            kids.push(p.make_span("template_substitution", true, ss));
            continue;
        }
        let fs = p.i;
        while !p.eof() && p.cur() != b'`' && p.cur() != b'\\' && !(p.cur() == b'$' && p.cur2() == b'{') {
            p.i += 1;
        }
        if p.i > fs {
            kids.push(p.make_span("string_fragment", true, fs));
        }
    }
    Some(p.make_span("template_string", true, start))
}

fn parse_regex(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'/' { return None; }
    // only treat as regex when not obviously a division
    let mut kids = Kids::new();
    kids.push(p.make_span("/", false, start));
    p.i += 1;
    let ps = p.i;
    let mut in_class = false;
    while !p.eof() {
        let c = p.cur();
        if c == b'\\' { p.i += 2; continue }
        if c == b'[' { in_class = true; p.i += 1; continue }
        if c == b']' { in_class = false; p.i += 1; continue }
        if c == b'/' && !in_class { break }
        if c == b'\n' { return None; }
        p.i += 1;
    }
    if p.cur() != b'/' { return None }
    if p.i > ps {
        kids.push(p.make_span("regex_pattern", true, ps));
    }
    let sl = p.i;
    p.i += 1;
    kids.push(p.make_span("/", false, sl));
    let fl = p.i;
    while !p.eof() && p.cur().is_ascii_alphabetic() { p.i += 1 }
    if p.i > fl {
        kids.push(p.make_span("regex_flags", true, fl));
    }
    Some(p.make_span("regex", true, start))
}

// -------------------------------------------------------------- parentheses

fn parse_parenthesized(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'(' { return None; }
    let mut kids = Kids::new();
    kids.push(p.make_span("(", false, start));
    p.i += 1;
    ws(p, &mut kids, Lang::JavaScript);
    let mut inner = Kids::new();
    if !parse_expression(p, &mut inner, 0) {
        return None;
    }
    kids.extend(inner);
    ws(p, &mut kids, Lang::JavaScript);
    if !lit(p, ")", &mut kids) { return None }
    Some(p.make_span("parenthesized_expression", true, start))
}

// -------------------------------------------------------------- TS type bits

fn parse_type(p: &mut P, out: &mut Kids) -> bool {
    let mut kids = Kids::new();
    if !parse_type_inner(p, &mut kids) {
        return false;
    }
    // union / intersection
    ws(p, &mut kids, Lang::JavaScript);
    loop {
        let save = p.i;
        let is_union = p.cur() == b'|' && p.cur2() != b'|';
        let is_inter = p.cur() == b'&' && p.cur2() != b'&';
        if !(is_union || is_inter) { p.i = save; break }
        let opstart = p.i;
        p.i += 1;
        kids.push(p.make_span("|", false, opstart));
        ws(p, &mut kids, Lang::JavaScript);
        if !parse_type_inner(p, &mut kids) { p.i = save; break }
        ws(p, &mut kids, Lang::JavaScript);
    }
    let start = kids.first().map(|&k| p.nodes[k as usize].start).unwrap_or(p.i);
    out.push(p.make_span("union_type", true, start));
    true
}

fn parse_type_inner(p: &mut P, out: &mut Kids) -> bool {
    ws(p, out, Lang::JavaScript);
    let start = p.i;
    match p.cur() {
        b'(' => {
            // function type / parenthesized type
            let mut kids = Kids::new();
            if !parse_parenthesized(p) { return false }
            let id = p.nodes.len() as u32 - 1;
            let _ = id;
            out.push(p.make_span("parenthesized_type", true, start));
            true
        }
        b'[' => {
            // array type or tuple
            let mut kids = Kids::new();
            kids.push(p.make_span("[", false, start));
            p.i += 1;
            ws(p, &mut kids, Lang::JavaScript);
            if p.cur() == b']' {
                let s = p.i; p.i += 1;
                kids.push(p.make_span("]", false, s));
                out.push(p.make_span("array_type", true, start));
                return true;
            }
            let mut inner = Kids::new();
            if !parse_type(p, &mut inner) { return false }
            kids.extend(inner);
            loop {
                ws(p, &mut kids, Lang::JavaScript);
                if !lit(p, ",", &mut kids) { break }
                ws(p, &mut kids, Lang::JavaScript);
                if p.cur() == b']' { break }
                if !parse_type(p, &mut kids) { break }
            }
            ws(p, &mut kids, Lang::JavaScript);
            if !lit(p, "]", &mut kids) { return false }
            out.push(p.make_span("tuple_type", true, start));
            true
        }
        b'{' => {
            // object type
            let mut kids = Kids::new();
            kids.push(p.make_span("{", false, start));
            p.i += 1;
            loop {
                ws(p, &mut kids, Lang::JavaScript);
                if p.cur() == b'}' || p.eof() { break }
                let ms = p.i;
                let mut member = Kids::new();
                // property signature
                if p.cur() == b'[' {
                    // index signature
                    let mut inner = Kids::new();
                    if !parse_type(p, &mut inner) { break }
                    member.extend(inner);
                    ws(p, &mut member, Lang::JavaScript);
                    let _ = lit(p, "]", &mut member);
                    ws(p, &mut member, Lang::JavaScript);
                    let _ = lit(p, ":", &mut member);
                    ws(p, &mut member, Lang::JavaScript);
                    if !parse_type(p, &mut member) { break }
                    out.push(p.make_span("index_signature", true, ms));
                } else {
                    // modifiers
                    loop {
                        ws(p, &mut member, Lang::JavaScript);
                        if kw(p, "readonly", &mut member)
                            || kw(p, "public", &mut member)
                            || kw(p, "private", &mut member)
                            || kw(p, "protected", &mut member)
                            || kw(p, "static", &mut member)
                            || kw(p, "abstract", &mut member)
                            || kw(p, "override", &mut member)
                        { continue }
                        break
                    }
                    if p.cur() == b'*' || p.text_at("new") || (p.cur() == b'[') {
                        // method signature
                        let name_start = p.i;
                        if p.cur() == b'*' { p.i += 1 }
                        let _ = parse_property_identifier(p);
                        ws(p, &mut member, Lang::JavaScript);
                        if !parse_formal_parameters(p, &mut member) { break }
                        ws(p, &mut member, Lang::JavaScript);
                        let _ = lit(p, ":", &mut member);
                        if p.cur() == b':' {
                            ws(p, &mut member, Lang::JavaScript);
                            let _ = parse_type(p, &mut member);
                        }
                        out.push(p.make_span("method_signature", true, ms));
                    } else {
                        let _ = parse_property_identifier(p);
                        // optional
                        ws(p, &mut member, Lang::JavaScript);
                        let _ = lit(p, "?", &mut member);
                        ws(p, &mut member, Lang::JavaScript);
                        let _ = lit(p, ":", &mut member);
                        if p.cur() == b':' {
                            ws(p, &mut member, Lang::JavaScript);
                            let _ = parse_type(p, &mut member);
                        }
                        out.push(p.make_span("property_signature", true, ms));
                    }
                }
                ws(p, &mut kids, Lang::JavaScript);
                if !lit(p, ";", &mut kids) && !lit(p, ",", &mut kids) {
                    // allow newline separation
                }
                if p.cur() == b'}' { break }
            }
            ws(p, &mut kids, Lang::JavaScript);
            let _ = lit(p, "}", &mut kids);
            out.push(p.make_span("object_type", true, start));
            true
        }
        b'<' => {
            // generic type
            let mut kids = Kids::new();
            if !parse_type_identifier(p, &mut kids) { return false }
            // type_arguments
            ws(p, &mut kids, Lang::JavaScript);
            if p.cur() == b'<' {
                let ts = p.i;
                p.i += 1;
                kids.push(p.make_span("<", false, ts));
                loop {
                    ws(p, &mut kids, Lang::JavaScript);
                    if p.cur() == b'>' { break }
                    if !parse_type(p, &mut kids) { break }
                    ws(p, &mut kids, Lang::JavaScript);
                    if !lit(p, ",", &mut kids) { break }
                }
                ws(p, &mut kids, Lang::JavaScript);
                let _ = lit(p, ">", &mut kids);
                out.push(p.make_span("generic_type", true, start));
            } else {
                out.extend(kids);
            }
            true
        }
        b'\'' | b'"' => {
            let mut kids = Kids::new();
            let _ = parse_string(p);
            out.push(p.make_span("literal_type", true, start));
            true
        }
        b'-' | b'0'..=b'9' => {
            let _ = parse_number(p);
            out.push(p.make_span("literal_type", true, start));
            true
        }
        _ => {
            if kw(p, "typeof", out) {
                ws(p, out, Lang::JavaScript);
                return parse_type(p, out);
            }
            if kw(p, "keyof", out) {
                ws(p, out, Lang::JavaScript);
                return parse_type(p, out);
            }
            if kw(p, "readonly", out) {
                ws(p, out, Lang::JavaScript);
                return parse_type(p, out);
            }
            if kw(p, "infer", out) {
                ws(p, out, Lang::JavaScript);
                let _ = parse_type_identifier(p, out);
                out.push(p.make_span("infer_type", true, start));
                return true;
            }
            if kw(p, "asserts", out) {
                return true;
            }
            if kw(p, "void", out)
                || kw(p, "any", out)
                || kw(p, "never", out)
                || kw(p, "unknown", out)
                || kw(p, "boolean", out)
                || kw(p, "string", out)
                || kw(p, "number", out)
                || kw(p, "symbol", out)
                || kw(p, "object", out)
                || kw(p, "bigint", out)
                || kw(p, "null", out)
                || kw(p, "undefined", out)
            {
                out.push(p.make_span("predefined_type", true, start));
                return true;
            }
            let mut kids = Kids::new();
            if !parse_type_identifier(p, &mut kids) {
                return false;
            }
            out.extend(kids);
            // optional generic arguments
            ws(p, out, Lang::JavaScript);
            if p.cur() == b'<' {
                let ts = p.i;
                p.i += 1;
                out.push(p.make_span("<", false, ts));
                loop {
                    ws(p, out, Lang::JavaScript);
                    if p.cur() == b'>' { break }
                    if !parse_type(p, out) { break }
                    ws(p, out, Lang::JavaScript);
                    if !lit(p, ",", out) { break }
                }
                ws(p, out, Lang::JavaScript);
                let _ = lit(p, ">", out);
                out.push(p.make_span("generic_type", true, start));
            }
            true
        }
    }
}

fn parse_type_identifier(p: &mut P, out: &mut Kids) -> Option<u32> {
    let start = p.i;
    let mut kids = Kids::new();
    let first = parse_identifier(p)?;
    kids.push(first);
    loop {
        ws(p, &mut kids, Lang::JavaScript);
        if p.cur() == b'.' {
            let ds = p.i;
            p.i += 1;
            kids.push(p.make_span(".", false, ds));
            let id = parse_identifier(p)?;
            kids.push(id);
        } else {
            break
        }
    }
    // if there's a dot it's a nested type identifier
    let has_dot = kids.iter().any(|&k| p.nodes[k as usize].kind == ".");
    if has_dot {
        let id = p.make_span("nested_type_identifier", true, start);
        out.push(id);
        Some(id)
    } else {
        let id = p.make_span("type_identifier", true, start);
        out.push(id);
        Some(id)
    }
}

pub fn parse_type_annotation(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b':' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span(":", false, start));
    p.i += 1;
    if !parse_type(p, &mut kids) { return false }
    out.push(p.make_span("type_annotation", true, start));
    true
}

// ----------------------------------------------------------- formal params

pub fn parse_formal_parameters(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b'(' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span("(", false, start));
    p.i += 1;
    loop {
        ws(p, &mut kids, Lang::JavaScript);
        if p.cur() == b')' || p.eof() { break }
        let ps = p.i;
        let mut param = Kids::new();
        parse_decorators(p, &mut param);
        ws(p, &mut param, Lang::JavaScript);
        // modifiers
        loop {
            let save = p.i;
            ws(p, &mut param, Lang::JavaScript);
            if kw(p, "public", &mut param)
                || kw(p, "private", &mut param)
                || kw(p, "protected", &mut param)
                || kw(p, "readonly", &mut param)
                || kw(p, "override", &mut param)
            { continue }
            p.i = save;
            break
        }
        ws(p, &mut param, Lang::JavaScript);
        let inner_start = p.i;
        let mut inner = Kids::new();
        let ok = parse_pattern(p, &mut inner);
        if !ok {
            p.i = inner_start;
            break;
        }
        param.extend(inner);
        ws(p, &mut param, Lang::JavaScript);
        if p.cur() == b'?' {
            let qs = p.i; p.i += 1;
            param.push(p.make_span("?", false, qs));
            ws(p, &mut param, Lang::JavaScript);
        }
        if p.cur() == b':' {
            let _ = parse_type_annotation(p, &mut param);
            ws(p, &mut param, Lang::JavaScript);
        }
        if p.cur() == b'=' {
            let es = p.i; p.i += 1;
            param.push(p.make_span("=", false, es));
            ws(p, &mut param, Lang::JavaScript);
            let mut init = Kids::new();
            if parse_expression(p, &mut init, 0) { param.extend(init) }
        }
        let kind = if p.nodes[param[0] as usize].kind == "rest_pattern" {
            "rest_pattern"
        } else if p.cur2() == 0 {
            "required_parameter"
        } else {
            "required_parameter"
        };
        let _ = kind;
        out.push(p.make_span("required_parameter", true, ps));
        ws(p, out, Lang::JavaScript);
        if !lit(p, ",", out) { break }
    }
    ws(p, &mut kids, Lang::JavaScript);
    let _ = lit(p, ")", &mut kids);
    let id = p.make_span("formal_parameters", true, start);
    out.push(id);
    true
}

fn parse_decorators(p: &mut P, out: &mut Kids) -> bool {
    let mut found = false;
    loop {
        let save = p.i;
        let mut kids = Kids::new();
        ws(p, &mut kids, Lang::JavaScript);
        if p.cur() != b'@' { p.i = save; break }
        let start = p.i;
        p.i += 1;
        kids.push(p.make_span("@", false, start));
        ws(p, &mut kids, Lang::JavaScript);
        let mut inner = Kids::new();
        if !parse_primary_expression(p, &mut inner) {
            p.i = save;
            break;
        }
        kids.extend(inner);
        out.push(p.make_span("decorator", true, start));
        found = true;
    }
    found
}
RSEOF
echo ok"}

