                    } else if p.cur() == b':' {
                        let cs = p.i;
                        p.i += 1;
                        item.push(p.make_span(":", false, cs));
                        ws(p, &mut item, Lang::JavaScript);
                        if !parse_pattern(p, &mut item) { p.i = is; break }
                        out.push(p.make_span("pair_pattern", true, is));
                    } else {
                        // shorthand
                        out.push(p.make_span("shorthand_property_identifier_pattern", true, ks));
                    }
                }
                ws(p, out, Lang::JavaScript);
                if !lit(p, ",", out) { break }
            }
            ws(p, &mut kids, Lang::JavaScript);
            let _ = lit(p, "}", &mut kids);
            out.push(p.make_span("object_pattern", true, start));
            true
        }
        b'[' => {
            let mut kids = Kids::new();
            kids.push(p.make_span("[", false, start));
            p.i += 1;
            loop {
                ws(p, &mut kids, Lang::JavaScript);
                if p.cur() == b']' || p.eof() { break }
                let is = p.i;
                if p.cur() == b'.' && p.cur2() == b'.' && p.cur3() == b'.' {
                    let rs = p.i;
                    p.i += 3;
                    kids.push(p.make_span("...", false, rs));
                    ws(p, &mut kids, Lang::JavaScript);
                    let _ = parse_pattern(p, &mut kids);
                    out.push(p.make_span("rest_pattern", true, is));
                } else {
                    let mut inner = Kids::new();
                    if !parse_pattern(p, &mut inner) { p.i = is; break }
                    let id = p.make_span("array_pattern", true, is);
                    let _ = id;
                    // treat as element
                    ws(p, &mut kids, Lang::JavaScript);
                    if p.cur() == b'=' {
                        let es = p.i;
                        p.i += 1;
                        kids.push(p.make_span("=", false, es));
                        ws(p, &mut kids, Lang::JavaScript);
                        let _ = parse_expression(p, &mut kids, 0);
                    }
                }
                ws(p, out, Lang::JavaScript);
                if !lit(p, ",", out) { break }
            }
            ws(p, &mut kids, Lang::JavaScript);
            let _ = lit(p, "]", &mut kids);
            out.push(p.make_span("array_pattern", true, start));
            true
        }
        _ => {
            let id = parse_identifier(p);
            match id {
                Some(id) => {
                    out.push(id);
                    true
                }
                None => false,
            }
        }
    }
}

// ---------------------------------------------------------------- expressions

/// Binary operator precedence table (higher binds tighter).
fn binary_prec(op: &str) -> i32 {
    match op {
        "??" => 1,
        "||" => 2,
        "&&" => 3,
        "|" => 4,
        "^" => 5,
        "&" => 6,
        "==" | "!=" | "===" | "!==" => 7,
        "<" | ">" | "<=" | ">=" | "in" | "instanceof" => 8,
        "<<" | ">>" | ">>>" => 9,
        "+" | "-" => 10,
        "*" | "/" | "%" => 11,
        "**" => 12,
        _ => -1,
    }
}

fn peek_binary_op(p: &P) -> Option<&'static str> {
    let c = p.cur();
    let c2 = p.cur2();
    let c3 = p.cur3();
    match (c, c2) {
        (b'=', b'=') if c3 == b'=' => Some("==="),
        (b'=', b'=') => Some("=="),
        (b'!', b'=') if c3 == b'=' => Some("!=="),
        (b'!', b'=') => Some("!="),
        (b'<', b'<') if c3 == b'<' => Some("<<<"),
        (b'<', b'<') => Some("<<"),
        (b'<', b'=') => Some("<="),
        (b'<', b'=') => Some("<="),
        (b'<', _) if c2 == b'<' => Some("<<"),
        (b'<', _) => Some("<"),
        (b'>', b'>') if c3 == b'>' => Some(">>>"),
        (b'>', b'>') => Some(">>"),
        (b'>', b'=') => Some(">="),
        (b'>', _) => Some(">"),
        (b'&', b'&') => Some("&&"),
        (b'&', b'=') => Some("&="),
        (b'&', _) => Some("&"),
        (b'|', b'|') => Some("||"),
        (b'|', b'=') => Some("|="),
        (b'|', _) => Some("|"),
        (b'^', b'=') => Some("^="),
        (b'^', _) => Some("^"),
        (b'*', b'*') => Some("**"),
        (b'*', b'=') => Some("*="),
        (b'*', _) => Some("*"),
        (b'/', b'=') => Some("/="),
        (b'/', _) => Some("/"),
        (b'%', b'=') => Some("%="),
        (b'%', _) => Some("%"),
        (b'+', b'=') => Some("+="),
        (b'+', _) => Some("+"),
        (b'-', b'=') => Some("-="),
        (b'-', _) => Some("-"),
        (b'?', b'?') if c3 == b'=' => Some("??="),
        (b'?', b'?') => Some("??"),
        _ => None,
    }
}

fn binary_op_word(p: &mut P) -> Option<u32> {
    if let Some(id) = p.kw("in") { return Some(id) }
    if let Some(id) = p.kw("instanceof") { return Some(id) }
    None
}

/// Parse an expression with the given minimum precedence.
pub fn parse_expression(p: &mut P, out: &mut Kids, min_prec: i32) -> bool {
    ws(p, out, Lang::JavaScript);
    let start = p.i;
    // sequence expression / assignment
    let mut lhs = Kids::new();
    if !parse_unary_chain(p, &mut lhs) {
        return false;
    }
    loop {
        ws(p, &mut lhs, Lang::JavaScript);
        let save = p.i;
        // comma -> sequence expression
        if p.cur() == b',' && min_prec <= 0 {
            let cs = p.i;
            p.i += 1;
            lhs.push(p.make_span(",", false, cs));
            let mut rhs = Kids::new();
            if !parse_expression(p, &mut rhs, 0) {
                p.i = save;
                break;
            }
            lhs.extend(rhs);
            let id = p.make_span("sequence_expression", true, start);
            out.push(id);
            return true;
        }
        // ternary
        if p.cur() == b'?' && p.cur2() != b'?' {
            let qs = p.i;
            p.i += 1;
            lhs.push(p.make_span("?", false, qs));
            ws(p, &mut lhs, Lang::JavaScript);
            let mut cons = Kids::new();
            if !parse_expression(p, &mut cons, 0) { p.i = save; break }
            lhs.extend(cons);
            ws(p, &mut lhs, Lang::JavaScript);
            if !lit(p, ":", &mut lhs) { p.i = save; break }
            ws(p, &mut lhs, Lang::JavaScript);
            let mut alt = Kids::new();
            if !parse_assignment_expr(p, &mut alt) { p.i = save; break }
            lhs.extend(alt);
            let id = p.make_span("ternary_expression", true, start);
            out.push(id);
            return true;
        }
        // assignment
        if p.cur() == b'=' && p.cur2() != b'=' {
            let es = p.i;
            p.i += 1;
            lhs.push(p.make_span("=", false, es));
            ws(p, &mut lhs, Lang::JavaScript);
            let mut rhs = Kids::new();
            if !parse_assignment_expr(p, &mut rhs) { p.i = save; break }
            lhs.extend(rhs);
            let id = p.make_span("assignment_expression", true, start);
            out.push(id);
            return true;
        }
        // augmented assignment
        if let Some(op) = peek_binary_op(p) {
            if op.ends_with('=') && op != "==" && op != "!=" && op != "<=" && op != ">=" {
                let os = p.i;
                p.i += op.len();
                lhs.push(p.make_span(BOX(op), false, os));
                ws(p, &mut lhs, Lang::JavaScript);
                let mut rhs = Kids::new();
                if !parse_assignment_expr(p, &mut rhs) { p.i = save; break }
                lhs.extend(rhs);
                let id = p.make_span("augmented_assignment_expression", true, start);
                out.push(id);
                return true;
            }
        }
        // binary operators
        if let Some(op) = peek_binary_op(p) {
            let prec = binary_prec(op);
            if prec >= min_prec && !op.ends_with('=') {
                let os = p.i;
                p.i += op.len();
                lhs.push(p.make_span(BOX(op), false, os));
                ws(p, &mut lhs, Lang::JavaScript);
                let mut rhs = Kids::new();
                let right_assoc = op == "**";
                if !parse_expression(p, &mut rhs, if right_assoc { prec } else { prec + 1 }) {
                    p.i = save;
                    break;
                }
                lhs.extend(rhs);
                let id = p.make_span("binary_expression", true, start);
                out.push(id);
                return true;
            }
            p.i = save;
        }
        if let Some(op) = binary_op_word(p) {
            let prec = 8;
            if prec >= min_prec {
                lhs.push(op);
                ws(p, &mut lhs, Lang::JavaScript);
                let mut rhs = Kids::new();
                if !parse_expression(p, &mut rhs, prec + 1) { p.i = save; break }
                lhs.extend(rhs);
                let id = p.make_span("binary_expression", true, start);
                out.push(id);
                return true;
            }
            p.i = save;
        }
        break;
    }
    out.extend(lhs);
    true
}

fn BOX(op: &str) -> &'static str {
    match op {
        "===" => "===",
        "==" => "==",
        "!==" => "!==",
        "!=" => "!=",
        "<<" => "<<",
        "<=" => "<=",
        "<" => "<",
        ">>>" => ">>>",
        ">>" => ">>",
        ">=" => ">=",
        ">" => ">",
        "&&" => "&&",
        "&=" => "&=",
        "&" => "&",
        "||" => "||",
        "|=" => "|=",
        "|" => "|",
        "^=" => "^=",
        "^" => "^",
        "**" => "**",
        "*=" => "*=",
        "*" => "*",
        "/=" => "/=",
        "/" => "/",
        "%=" => "%=",
        "%" => "%",
        "+=" => "+=",
        "+" => "+",
        "-=" => "-=",
        "-" => "-",
        "??=" => "??=",
        "??" => "??",
        _ => op,
    }
}

fn parse_assignment_expr(p: &mut P, out: &mut Kids) -> bool {
    parse_expression(p, out, 1)
}

fn parse_unary_chain(p: &mut P, out: &mut Kids) -> bool {
    ws(p, out, Lang::JavaScript);
    let start = p.i;
    let c = p.cur();
    // unary operators
    if (c == b'!' || c == b'~' || c == b'+' || c == b'-')
        && !(c == b'+' && p.cur2() == b'+')
        && !(c == b'-' && p.cur2() == b'-')
    {
        let os = p.i;
        p.i += 1;
        out.push(p.make_span(BOX(if c == b'!' { "!" } else if c == b'~' { "~" } else if c == b'+' { "+" } else { "-" }), false, os));
        ws(p, out, Lang::JavaScript);
        let mut inner = Kids::new();
        if !parse_unary_chain(p, &mut inner) { return false }
        out.extend(inner);
        let id = p.make_span("unary_expression", true, start);
        out.push(id);
        return true;
    }
    if kw(p, "typeof", out) || kw(p, "void", out) || kw(p, "delete", out) {
        ws(p, out, Lang::JavaScript);
        let mut inner = Kids::new();
        if !parse_unary_chain(p, &mut inner) { return false }
        out.extend(inner);
        let id = p.make_span("unary_expression", true, start);
        out.push(id);
        return true;
    }
    if kw(p, "await", out) {
        ws(p, out, Lang::JavaScript);
        let mut inner = Kids::new();
        if parse_unary_chain(p, &mut inner) { out.extend(inner) }
        let id = p.make_span("await_expression", true, start);
        out.push(id);
        return true;
    }
    if kw(p, "yield", out) {
        ws(p, out, Lang::JavaScript);
        if p.cur() == b'*' {
            let ss = p.i;
            p.i += 1;
            out.push(p.make_span("*", false, ss));
        }
        ws(p, out, Lang::JavaScript);
        let mut inner = Kids::new();
        if parse_unary_chain(p, &mut inner) { out.extend(inner) }
        let id = p.make_span("yield_expression", true, start);
        out.push(id);
        return true;
    }
    // prefix update
    if (c == b'+' && p.cur2() == b'+') || (c == b'-' && p.cur2() == b'-') {
        let os = p.i;
        p.i += 2;
        out.push(p.make_span(BOX(if c == b'+' { "++" } else { "--" }), false, os));
        ws(p, out, Lang::JavaScript);
        let mut inner = Kids::new();
        if !parse_postfix(p, &mut inner) { return false }
        out.extend(inner);
        let id = p.make_span("update_expression", true, start);
        out.push(id);
        return true;
    }
    parse_postfix(p, out)
}

fn parse_postfix(p: &mut P, out: &mut Kids) -> bool {
    ws(p, out, Lang::JavaScript);
    let start = p.i;
    let mut kids = Kids::new();
    if !parse_primary_expression(p, &mut kids) {
        return false;
    }
    loop {
        ws(p, &mut kids, Lang::JavaScript);
        let save = p.i;
        if p.cur() == b'(' {
            // call or new call
            let mut args = Kids::new();
            if !parse_arguments(p, &mut args) { p.i = save; break }
            kids.push(args);
            let id = p.make_span("call_expression", true, start);
            kids.clear();
            kids.push(id);
            continue;
        }
        if p.cur() == b'.' || p.text_at("?.") {
            let member_start = p.i;
            if p.text_at("?.") {
                p.i += 2;
                kids.push(p.make_span("?.", false, member_start));
            } else {
                p.i += 1;
                kids.push(p.make_span(".", false, member_start));
            }
            ws(p, &mut kids, Lang::JavaScript);
            let prop = if p.cur() == b'#' {
                parse_private_property_identifier(p)
            } else {
                parse_property_identifier(p)
            };
            match prop {
                Some(pr) => kids.push(pr),
                None => { p.i = save; break }
            }
            let id = p.make_span("member_expression", true, start);
            kids.clear();
            kids.push(id);
            continue;
        }
        if p.cur() == b'[' {
            let ms = p.i;
            p.i += 1;
            kids.push(p.make_span("[", false, ms));
            ws(p, &mut kids, Lang::JavaScript);
            let mut idx = Kids::new();
            if !parse_expression(p, &mut idx, 0) { p.i = save; break }
            kids.extend(idx);
            ws(p, &mut kids, Lang::JavaScript);
            if !lit(p, "]", &mut kids) { p.i = save; break }
            let id = p.make_span("subscript_expression", true, start);
            kids.clear();
            kids.push(id);
            continue;
        }
        if (p.cur() == b'+' && p.cur2() == b'+') || (p.cur() == b'-' && p.cur2() == b'-') {
            let os = p.i;
            p.i += 2;
            kids.push(p.make_span(BOX(if p.s[os] == b'+' { "++" } else { "--" }), false, os));
            let id = p.make_span("update_expression", true, start);
            kids.clear();
            kids.push(id);
            continue;
        }
        if is_lang_jsx(p_lang()) && (p.cur() == b'<' || p.cur() == b'>') {
            // could be jsx; handled in primary
        }
        break;
    }
    out.extend(kids);
    true
}

fn p_lang() -> Lang { Lang::JavaScript }

fn parse_arguments(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b'(' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span("(", false, start));
    p.i += 1;
    loop {
        ws(p, &mut kids, Lang::JavaScript);
        if p.cur() == b')' || p.eof() { break }
        let as_ = p.i;
        let mut arg = Kids::new();
        if p.cur() == b'.' && p.cur2() == b'.' && p.cur3() == b'.' {
            let rs = p.i;
            p.i += 3;
            arg.push(p.make_span("...", false, rs));
            ws(p, &mut arg, Lang::JavaScript);
            let _ = parse_expression(p, &mut arg, 0);
            kids.push(p.make_span("spread_element", true, as_));
        } else {
            if !parse_expression(p, &mut arg, 0) { break }
            kids.push(arg.pop().unwrap_or_else(|| 0));
        }
        ws(p, out, Lang::JavaScript);
        if !lit(p, ",", out) { break }
    }
    ws(p, &mut kids, Lang::JavaScript);
    let _ = lit(p, ")", &mut kids);
    let id = p.make_span("arguments", true, start);
    out.push(id);
    true
}
