/// Binary operator precedence table (higher binds tighter).
fn binary_prec(op: &str) -> i32 {
    match op {
        "??" => 1,
        "||" => 2,
        "&&" => 3,
        "|" => 4,
        "^" => 5,
        "&" => 6,
        "==" | "!=" | "===" | "!==" => 7,
        "<" | ">" | "<=" | ">=" | "in" | "instanceof" => 8,
        "<<" | ">>" | ">>>" => 9,
        "+" | "-" => 10,
        "*" | "/" | "%" => 11,
        "**" => 12,
        _ => -1,
    }
}

fn peek_binary_op(p: &P) -> Option<&'static str> {
    let c = p.cur();
    let c2 = p.cur2();
    let c3 = p.cur3();
    match (c, c2) {
        (b'=', b'=') if c3 == b'=' => Some("==="),
        (b'=', b'=') => Some("=="),
        (b'!', b'=') if c3 == b'=' => Some("!=="),
        (b'!', b'=') => Some("!="),
        (b'<', b'<') if c3 == b'<' => Some("<<<"),
        (b'<', b'<') => Some("<<"),
        (b'<', b'=') => Some("<="),
        (b'<', b'=') => Some("<="),
        (b'<', _) if c2 == b'<' => Some("<<"),
        (b'<', _) => Some("<"),
        (b'>', b'>') if c3 == b'>' => Some(">>>"),
        (b'>', b'>') => Some(">>"),
        (b'>', b'=') => Some(">="),
        (b'>', _) => Some(">"),
        (b'&', b'&') => Some("&&"),
        (b'&', b'=') => Some("&="),
        (b'&', _) => Some("&"),
        (b'|', b'|') => Some("||"),
        (b'|', b'=') => Some("|="),
        (b'|', _) => Some("|"),
        (b'^', b'=') => Some("^="),
        (b'^', _) => Some("^"),
        (b'*', b'*') => Some("**"),
        (b'*', b'=') => Some("*="),
        (b'*', _) => Some("*"),
        (b'/', b'=') => Some("/="),
        (b'/', _) => Some("/"),
        (b'%', b'=') => Some("%="),
        (b'%', _) => Some("%"),
        (b'+', b'=') => Some("+="),
        (b'+', _) => Some("+"),
        (b'-', b'=') => Some("-="),
        (b'-', _) => Some("-"),
        (b'?', b'?') if c3 == b'=' => Some("??="),
        (b'?', b'?') => Some("??"),
        _ => None,
    }
}

fn binary_op_word(p: &mut P) -> Option<u32> {
    if let Some(id) = p.kw("in") { return Some(id) }
    if let Some(id) = p.kw("instanceof") { return Some(id) }
    None
}

