                let id = p.make_span("this", true, start);
                out.push(id);
                return true;
            }
            if kw(p, "super", out) {
                let id = p.make_span("super", true, start);
                out.push(id);
                return true;
            }
            if kw(p, "true", out) {
                let id = p.make_span("true", true, start);
                out.push(id);
                return true;
            }
            if kw(p, "false", out) {
                let id = p.make_span("false", true, start);
                out.push(id);
                return true;
