                return false;
            }
            if let Some(id) = parse_identifier(p) {
                out.push(id);
                return true;
            }
            false
        }
    }
}

fn parse_postfix_new(p: &mut P, out: &mut Kids) -> bool {
    // after `new`, parse the callee expression (member/subscript chain)
    ws(p, out, Lang::JavaScript);
    let start = p.i;
    let mut kids = Kids::new();
    if !parse_primary_expression(p, &mut kids) {
        return false;
    }
    // optional type arguments for TS
    loop {
        ws(p, &mut kids, Lang::JavaScript);
        let save = p.i;
        if p.cur() == b'.' {
            p.i += 1;
            kids.push(p.make_span(".", false, save));
            let pr = parse_property_identifier(p);
            match pr {
                Some(pr) => kids.push(pr),
                None => { p.i = save; break }
            }
            let id = p.make_span("member_expression", true, start);
            kids.clear();
            kids.push(id);
            continue;
        }
        if p.cur() == b'[' {
            let ms = p.i;
            p.i += 1;
            kids.push(p.make_span("[", false, ms));
            ws(p, &mut kids, Lang::JavaScript);
            let mut idx = Kids::new();
            if !parse_expression(p, &mut idx, 0) { p.i = save; break }
            kids.extend(idx);
            ws(p, &mut kids, Lang::JavaScript);
            if !lit(p, "]", &mut kids) { p.i = save; break }
            let id = p.make_span("subscript_expression", true, start);
            kids.clear();
            kids.push(id);
            continue;
        }
        break;
    }
    out.extend(kids);
    true
}

fn parse_arrow_function(p: &mut P, start: usize) -> Option<u32> {
    // look ahead for `(...)` or identifier followed by `=>`
    let save = p.i;
    let mut kids = Kids::new();
    ws(p, &mut kids, Lang::JavaScript);
    let mut is_async = false;
    if p.text_at("async") {
        let after = p.i + 5;
        if !(after < p.s.len() && p.is_word(p.s[after])) {
            is_async = true;
            p.i = after;
            ws(p, &mut kids, Lang::JavaScript);
        }
    }
    let mut params = Kids::new();
    let ok = if p.cur() == b'(' {
        // try parenthesized params
        parse_formal_parameters(p, &mut params)
    } else {
        if let Some(id) = parse_identifier(p) { params.push(id); true } else { false }
    };
    if !ok {
        p.i = save;
        return None;
    }
    ws(p, &mut params, Lang::JavaScript);
    // optional return type annotation (TS)
    if p.cur() == b':' {
        let _ = parse_type_annotation(p, &mut params);
        ws(p, &mut params, Lang::JavaScript);
    }
    if !(p.cur() == b'=' && p.cur2() == b'>') {
        p.i = save;
        return None;
    }
    let as_ = p.i;
    p.i += 2;
    params.push(p.make_span("=>", false, as_));
    ws(p, &mut params, Lang::JavaScript);
    let mut body = Kids::new();
    if p.cur() == b'{' {
        if !parse_statement_block(p, &mut body) {
            p.i = save;
            return None;
        }
    } else {
        let mut inner = Kids::new();
        if !parse_assignment_expr(p, &mut inner) {
            p.i = save;
            return None;
        }
        body.extend(inner);
    }
    let id = p.make_span("arrow_function", true, start);
    for &c in &kids {
        let _ = c;
    }
    let _ = is_async;
    out_push_arrow(p, id, &kids, &params, &body, start);
    Some(id)
}

fn out_push_arrow(
    p: &mut P,
    _id: u32,
    _kids: &[u32],
    params: &[u32],
    body: &[u32],
    _start: usize,
) {
    // children are already appended in order by parse; nothing to do
    let _ = (p, params, body);
}
