        b'0'..=b'9' => match parse_number(p) {
            Some(id) => { out.push(id); true }
            None => false,
        },
        _ => {
            // keywords that are primary expressions
            if kw(p, "new", out) {
                ws(p, out, Lang::JavaScript);
                let mut inner = Kids::new();
                let cs = p.i;
                if !parse_postfix_new(p, &mut inner) { return false }
                let ctor = inner.pop();
                if let Some(cc) = ctor {
                    field(p, cc, "constructor");
                    out.push(cc);
                }
                out.extend(inner);
                let _ = cs;
                let id = p.make_span("new_expression", true, start);
                out.push(id);
                return true;
            }
            if kw(p, "this", out) {
                let id = p.make_span("this", true, start);
                out.push(id);
                return true;
