            if kw(p, "super", out) {
                let id = p.make_span("super", true, start);
                out.push(id);
                return true;
            }
            if kw(p, "true", out) {
                let id = p.make_span("true", true, start);
                out.push(id);
                return true;
            }
            if kw(p, "false", out) {
                let id = p.make_span("false", true, start);
                out.push(id);
                return true;
            }
            if kw(p, "null", out) {
                let id = p.make_span("null", true, start);
                out.push(id);
                return true;
            }
            if kw(p, "undefined", out) {
                let id = p.make_span("undefined", true, start);
                out.push(id);
                return true;
            }
            if kw(p, "function", out) {
                // function expression
                ws(p, out, Lang::JavaScript);
                if p.cur() == b'*' {
                    let ss = p.i;
                    p.i += 1;
                    out.push(p.make_span("*", false, ss));
                    ws(p, out, Lang::JavaScript);
                }
                let _ = parse_identifier(p);
                ws(p, out, Lang::JavaScript);
                if !parse_formal_parameters(p, out) { return false }
                ws(p, out, Lang::JavaScript);
                if !parse_statement_block(p, out) { return false }
                let kind = if p.nodes[out.last().unwrap_or(&0) as usize].kind == "*" {
                    "generator_function_expression"
                } else {
                    "function_expression"
                };
                out.push(p.make_span(kind, true, start));
                return true;
            }
            if kw(p, "class", out) {
                return parse_class_body_after_kw(p, out, start, "class");
            }
            if kw(p, "import", out) {
                // dynamic import: import(...)
                ws(p, out, Lang::JavaScript);
                let mut args = Kids::new();
                if p.cur() == b'(' {
                    if !parse_arguments(p, &mut args) { return false }
                    field(p, args, "source");
                    out.push(args);
                    out.push(p.make_span("import", true, start));
                    return true;
                }
                return false;
            }
            if let Some(id) = parse_identifier(p) {
                out.push(id);
                return true;
            }
            false
        }
    }
}

fn parse_postfix_new(p: &mut P, out: &mut Kids) -> bool {
    // after `new`, parse the callee expression (member/subscript chain)
    ws(p, out, Lang::JavaScript);
    let start = p.i;
    let mut kids = Kids::new();
    if !parse_primary_expression(p, &mut kids) {
        return false;
    }
    // optional type arguments for TS
    loop {
        ws(p, &mut kids, Lang::JavaScript);
        let save = p.i;
        if p.cur() == b'.' {
            p.i += 1;
            kids.push(p.make_span(".", false, save));
            let pr = parse_property_identifier(p);
            match pr {
                Some(pr) => kids.push(pr),
                None => { p.i = save; break }
            }
            let id = p.make_span("member_expression", true, start);
            kids.clear();
            kids.push(id);
            continue;
        }
        if p.cur() == b'[' {
            let ms = p.i;
            p.i += 1;
            kids.push(p.make_span("[", false, ms));
            ws(p, &mut kids, Lang::JavaScript);
            let mut idx = Kids::new();
            if !parse_expression(p, &mut idx, 0) { p.i = save; break }
            kids.extend(idx);
            ws(p, &mut kids, Lang::JavaScript);
            if !lit(p, "]", &mut kids) { p.i = save; break }
            let id = p.make_span("subscript_expression", true, start);
            kids.clear();
            kids.push(id);
            continue;
        }
        break;
    }
    out.extend(kids);
    true
}

