//! JavaScript / TypeScript / TSX parser producing tree-sitter compatible node kinds.

use crate::lang::Lang;
use crate::parser::P;

pub type Kids = Vec<u32>;

// ------------------------------------------------------------------- helpers

fn kw(p: &mut P, w: &'static str, out: &mut Kids) -> bool {
    if let Some(id) = p.kw(w) { out.push(id); true } else { false }
}
fn lit(p: &mut P, l: &'static str, out: &mut Kids) -> bool {
    if let Some(id) = p.lit(l) { out.push(id); true } else { false }
}
fn ws(p: &mut P, out: &mut Kids) { p.ws(out, Lang::JavaScript); }
fn f(p: &mut P, id: u32, name: &'static str) { p.set_field(id, name); }

fn box_op(op: &str) -> &'static str {
    match op {
        "===" => "===", "==" => "==", "!==" => "!==", "!=" => "!=", "<<" => "<<",
        "<=" => "<=", "<" => "<", ">>>" => ">>>", ">>" => ">>", ">=" => ">=", ">" => ">",
        "&&" => "&&", "&=" => "&=", "&" => "&", "||" => "||", "|=" => "|=", "|" => "|",
        "^=" => "^=", "^" => "^", "**" => "**", "*=" => "*=", "*" => "*", "/=" => "/=",
        "/" => "/", "%=" => "%=", "%" => "%", "+=" => "+=", "+" => "+", "-=" => "-=",
        "-" => "-", "??=" => "??=", "??" => "??", _ => op,
    }
}

fn is_ts(lang: Lang) -> bool { matches!(lang, Lang::TypeScript | Lang::Tsx) }

fn is_ident_char(c: u8) -> bool { c.is_ascii_alphanumeric() || c == b'_' || c == b'$' || c >= 0x80 }

// -------------------------------------------------------------- lexing bits

fn parse_identifier(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    let c = p.cur();
    if !(c.is_ascii_alphabetic() || c == b'_' || c == b'$' || c >= 0x80) { return false }
    while !p.eof() && is_ident_char(p.cur()) { p.i += 1 }
    let id = p.make_span("identifier", true, start);
    out.push(id);
    true
}

fn parse_property_identifier(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    let c = p.cur();
    if !(c.is_ascii_alphabetic() || c == b'_' || c == b'$' || c.is_ascii_digit() || c >= 0x80) {
        return false;
    }
    while !p.eof() && is_ident_char(p.cur()) { p.i += 1 }
    let id = p.make_span("property_identifier", true, start);
    out.push(id);
    true
}

fn parse_private_property_identifier(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b'#' { return false }
    p.i += 1;
    while !p.eof() && is_ident_char(p.cur()) { p.i += 1 }
    let id = p.make_span("private_property_identifier", true, start);
    out.push(id);
    true
}

fn parse_number(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    let c = p.cur();
    if !(c.is_ascii_digit() || (c == b'.' && p.cur2().is_ascii_digit())) { return false }
    if c == b'0' && (p.cur2() == b'b' || p.cur2() == b'o' || p.cur2() == b'x') {
        p.i += 2;
        while !p.eof() && (p.cur().is_ascii_alphanumeric() || p.cur() == b'_') { p.i += 1 }
        out.push(p.make_span("number", true, start));
        return true;
    }
    let mut seen_dot = false;
    let mut seen_exp = false;
    while !p.eof() {
        let c = p.cur();
        if c.is_ascii_digit() || c == b'_' { p.i += 1 }
        else if c == b'.' && !seen_dot && !seen_exp { seen_dot = true; p.i += 1 }
        else if (c == b'e' || c == b'E') && !seen_exp && p.i > start {
            seen_exp = true;
            p.i += 1;
            if p.cur() == b'+' || p.cur() == b'-' { p.i += 1 }
        } else if c == b'n' && p.i > start {
            p.i += 1;
            break;
        } else { break }
    }
    if p.i == start { return false }
    out.push(p.make_span("number", true, start));
    true
}

fn parse_escape(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b'\\' { return false }
    p.i += 1;
    if p.cur() == b'u' || p.cur() == b'x' {
        p.i += 1;
        if p.cur() == b'{' {
            while !p.eof() && p.cur() != b'}' { p.i += 1 }
            if p.cur() == b'}' { p.i += 1 }
        } else {
            let n = 4;
            for _ in 0..n {
                if p.cur().is_ascii_hexdigit() { p.i += 1 } else { break }
            }
        }
    } else if !p.eof() {
        p.i += 1;
    }
    out.push(p.make_span("escape_sequence", true, start));
    true
}

fn parse_string(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    let quote = p.cur();
    if quote != b'"' && quote != b'\'' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span("\"", false, start));
    p.i += 1;
    let fs = p.i;
    loop {
        if p.eof() || p.cur() == quote { break }
        if p.cur() == b'\\' {
            if p.i > fs { kids.push(p.make_span("string_fragment", true, fs)) }
            if !parse_escape(p, &mut kids) { break }
            p.i = p.i; // continue scanning after escape
            // remaining fragment
            let fs2 = p.i;
            while !p.eof() && p.cur() != quote && p.cur() != b'\\' { p.i += 1 }
            if p.i > fs2 { kids.push(p.make_span("string_fragment", true, fs2)) }
            continue;
        }
        p.i += 1;
    }
    if p.i > fs && kids.last().map(|k| p.nodes[k as usize].kind) != Some("string_fragment") {
        kids.push(p.make_span("string_fragment", true, fs));
    }
    if p.cur() == quote {
        let qs = p.i;
        p.i += 1;
        kids.push(p.make_span("\"", false, qs));
    }
    out.push(p.make_node("string", true, start, kids));
    true
}

fn parse_template_string(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b'`' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span("`", false, start));
    p.i += 1;
    loop {
        if p.eof() { break }
        if p.cur() == b'`' {
            let s = p.i;
            p.i += 1;
            kids.push(p.make_span("`", false, s));
            break;
        }
        if p.cur() == b'\\' {
            parse_escape(p, &mut kids);
            continue;
        }
        if p.cur() == b'$' && p.cur2() == b'{' {
            let ss = p.i;
            p.i += 2;
            let mut sub = Kids::new();
            sub.push(p.make_span("${", false, ss));
            ws(p, &mut sub);
            if !parse_expression(p, &mut sub, 0) { }
            ws(p, &mut sub);
            let _ = lit(p, "}", &mut sub);
            kids.push(p.make_node("template_substitution", true, ss, sub));
            continue;
        }
        let fs = p.i;
        while !p.eof() && p.cur() != b'`' && p.cur() != b'\\'
            && !(p.cur() == b'$' && p.cur2() == b'{') { p.i += 1 }
        if p.i > fs { kids.push(p.make_span("string_fragment", true, fs)) }
    }
    out.push(p.make_node("template_string", true, start, kids));
    true
}

fn parse_regex(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b'/' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span("/", false, start));
    p.i += 1;
    let ps = p.i;
    let mut in_class = false;
    while !p.eof() {
        let c = p.cur();
        if c == b'\\' { p.i += 2; continue }
        if c == b'[' { in_class = true; p.i += 1; continue }
        if c == b']' { in_class = false; p.i += 1; continue }
        if c == b'/' && !in_class { break }
        if c == b'\n' { return false }
        p.i += 1;
    }
    if p.cur() != b'/' { return false }
    if p.i > ps { kids.push(p.make_span("regex_pattern", true, ps)) }
    let sl = p.i;
    p.i += 1;
    kids.push(p.make_span("/", false, sl));
    let fl = p.i;
    while !p.eof() && p.cur().is_ascii_alphabetic() { p.i += 1 }
    if p.i > fl { kids.push(p.make_span("regex_flags", true, fl)) }
    out.push(p.make_node("regex", true, start, kids));
    true
}
