// ------------------------------------------------------------- type syntax

fn parse_type_identifier(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    let mut kids = Kids::new();
    if !parse_identifier(p, &mut kids) { return false }
    let mut has_dot = false;
    loop {
        ws(p, &mut kids);
        if p.cur() == b'.' {
            let ds = p.i;
            p.i += 1;
            kids.push(p.make_span(".", false, ds));
            if !parse_identifier(p, &mut kids) { break }
            has_dot = true;
        } else { break }
    }
    let kind = if has_dot { "nested_type_identifier" } else { "type_identifier" };
    out.push(p.make_node(kind, true, start, kids));
    true
}

fn parse_type(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    let mut kids = Kids::new();
    if !parse_type_inner(p, &mut kids) { return false }
    loop {
        ws(p, &mut kids);
        let save = p.i;
        let is_union = p.cur() == b'|' && p.cur2() != b'|';
        let is_inter = p.cur() == b'&' && p.cur2() != b'&';
        if !(is_union || is_inter) { p.i = save; break }
        let os = p.i;
        p.i += 1;
        kids.push(p.make_span("|", false, os));
        ws(p, &mut kids);
        if !parse_type_inner(p, &mut kids) { p.i = save; break }
    }
    out.push(p.make_node("union_type", true, start, kids));
    true
}

fn parse_type_inner(p: &mut P, out: &mut Kids) -> bool {
    ws(p, out);
    let start = p.i;
    match p.cur() {
        b'[' => {
            let mut kids = Kids::new();
            kids.push(p.make_span("[", false, start));
            p.i += 1;
            ws(p, &mut kids);
            if p.cur() == b']' {
                let s = p.i; p.i += 1;
                kids.push(p.make_span("]", false, s));
                out.push(p.make_node("array_type", true, start, kids));
                return true;
            }
            if !parse_type(p, &mut kids) { return false }
            loop {
                ws(p, &mut kids);
                if !lit(p, ",", &mut kids) { break }
                ws(p, &mut kids);
                if p.cur() == b']' { break }
                if !parse_type(p, &mut kids) { break }
            }
            ws(p, &mut kids);
            if !lit(p, "]", &mut kids) { return false }
            out.push(p.make_node("tuple_type", true, start, kids));
            true
        }
        b'{' => {
            let mut kids = Kids::new();
            kids.push(p.make_span("{", false, start));
            p.i += 1;
            loop {
                ws(p, &mut kids);
                if p.cur() == b'}' || p.eof() { break }
                let ms = p.i;
                let mut member = Kids::new();
                if p.cur() == b'[' {
                    let mut inner = Kids::new();
                    if !parse_type(p, &mut inner) { break }
                    member.extend(inner);
                    ws(p, &mut member);
                    let _ = lit(p, "]", &mut member);
                    ws(p, &mut member);
                    let _ = lit(p, ":", &mut member);
                    ws(p, &mut member);
                    let _ = parse_type(p, &mut member);
                    out.push(p.make_node("index_signature", true, ms, member));
                } else {
                    loop {
                        ws(p, &mut member);
                        if kw(p, "readonly", &mut member) || kw(p, "public", &mut member)
                            || kw(p, "private", &mut member) || kw(p, "protected", &mut member)
                            || kw(p, "static", &mut member) || kw(p, "override", &mut member)
                        { continue }
                        break
