                    ws(p, &mut member);
                    if p.cur() == b'*' || p.text_at("new") || p.cur() == b'(' {
                        if p.cur() == b'*' {
                            let ss = p.i; p.i += 1;
                            member.push(p.make_span("*", false, ss));
                        }
                        if p.text_at("new") { kw(p, "new", &mut member); }
                        ws(p, &mut member);
                        if p.cur() != b'(' { let _ = parse_property_identifier(p, &mut member); }
                        ws(p, &mut member);
                        let _ = parse_formal_parameters(p, &mut member);
                        ws(p, &mut member);
                        if p.cur() == b':' {
                            let _ = parse_type_annotation(p, &mut member);
                        }
                        out.push(p.make_node("method_signature", true, ms, member));
