                        }
                        out.push(p.make_node("property_signature", true, ms, member));
                    }
                }
                ws(p, &mut kids);
                if !lit(p, ";", &mut kids) { let _ = lit(p, ",", &mut kids); }
                if p.cur() == b'}' { break }
            }
            ws(p, &mut kids);
            let _ = lit(p, "}", &mut kids);
            out.push(p.make_node("object_type", true, start, kids));
