                    if !parse_type(p, &mut kids) { break }
                    ws(p, &mut kids);
                    if !lit(p, ",", &mut kids) { break }
                }
                ws(p, &mut kids);
                let _ = lit(p, ">", &mut kids);
                out.push(p.make_node("generic_type", true, start, kids));
            } else {
                out.extend(kids);
            }
            true
        }
        b'\'' | b'"' => {
            let _ = parse_string(p, out);
            out.push(p.make_span("literal_type", true, start));
            true
        }
        b'-' | b'0'..=b'9' => {
            let _ = parse_number(p, out);
            out.push(p.make_span("literal_type", true, start));
            true
        }
        _ => {
            if kw(p, "typeof", out) {
                ws(p, out);
                if p.cur() == b'(' {
                    let mut inner = Kids::new();
                    let _ = parse_parenthesized(p, &mut inner);
                } else {
                    let _ = parse_type(p, out);
                }
                out.push(p.make_span("typeof_type", true, start));
                return true;
            }
            if kw(p, "keyof", out) || kw(p, "readonly", out) || kw(p, "unique", out) {
                ws(p, out);
                let _ = parse_type(p, out);
                out.push(p.make_span("keyof_type", true, start));
                return true;
            }
            if kw(p, "infer", out) {
                ws(p, out);
                let _ = parse_type_identifier(p, out);
                out.push(p.make_span("infer_type", true, start));
                return true;
            }
            for w in ["void", "any", "never", "unknown", "boolean", "string", "number",
                      "symbol", "object", "bigint", "null", "undefined"] {
                if kw(p, w, out) {
                    out.push(p.make_span("predefined_type", true, start));
                    return true;
                }
            }
            let mut kids = Kids::new();
            if !parse_type_identifier(p, &mut kids) { return false }
            out.extend(kids);
            ws(p, out);
            if p.cur() == b'<' {
                let ts = p.i;
                p.i += 1;
                out.push(p.make_span("<", false, ts));
                loop {
                    ws(p, out);
                    if p.cur() == b'>' { break }
                    if !parse_type(p, out) { break }
                    ws(p, out);
                    if !lit(p, ",", out) { break }
                }
                ws(p, out);
                let _ = lit(p, ">", out);
                out.push(p.make_span("generic_type", true, start));
            }
            true
        }
    }
}

pub fn parse_type_annotation(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b':' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span(":", false, start));
    p.i += 1;
    if !parse_type(p, &mut kids) { return false }
    out.push(p.make_node("type_annotation", true, start, kids));
    true
}

fn parse_type_arguments(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b'<' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span("<", false, start));
    p.i += 1;
    loop {
        ws(p, &mut kids);
        if p.cur() == b'>' { break }
        if !parse_type(p, &mut kids) { break }
        ws(p, &mut kids);
        if !lit(p, ",", &mut kids) { break }
    }
    ws(p, &mut kids);
    let _ = lit(p, ">", &mut kids);
    out.push(p.make_node("type_arguments", true, start, kids));
    true
}

// ------------------------------------------------------------ parameters

pub fn parse_formal_parameters(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b'(' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span("(", false, start));
    p.i += 1;
    loop {
        ws(p, &mut kids);
        if p.cur() == b')' || p.eof() { break }
        let ps = p.i;
        let mut param = Kids::new();
        parse_decorators(p, &mut param);
        ws(p, &mut param);
        loop {
            let save = p.i;
            ws(p, &mut param);
            if kw(p, "public", &mut param) || kw(p, "private", &mut param)
                || kw(p, "protected", &mut param) || kw(p, "readonly", &mut param)
                || kw(p, "override", &mut param)
            { continue }
            p.i = save;
            break
        }
        ws(p, &mut param);
        if !parse_pattern(p, &mut param) { break }
        let has_default = {
            let save = p.i;
            ws(p, &mut param);
            let has = p.cur() == b'?' || p.cur() == b':' || p.cur() == b'=';
            p.i = save;
            has
        };
        ws(p, &mut param);
        if p.cur() == b'?' {
            let qs = p.i; p.i += 1;
            param.push(p.make_span("?", false, qs));
            ws(p, &mut param);
        }
        if p.cur() == b':' {
            let _ = parse_type_annotation(p, &mut param);
            ws(p, &mut param);
        }
        if p.cur() == b'=' {
            let es = p.i; p.i += 1;
            param.push(p.make_span("=", false, es));
            ws(p, &mut param);
            let _ = parse_expression(p, &mut param, 0);
        }
        let kind = if has_default { "optional_parameter" } else { "required_parameter" };
        out.push(p.make_node(kind, true, ps, param));
        ws(p, out);
        if !lit(p, ",", out) { break }
    }
    ws(p, &mut kids);
    let _ = lit(p, ")", &mut kids);
    out.push(p.make_node("formal_parameters", true, start, kids));
    true
}

fn parse_decorators(p: &mut P, out: &mut Kids) -> bool {
    let mut found = false;
    loop {
        let save = p.i;
        let mut kids = Kids::new();
        ws(p, &mut kids);
        if p.cur() != b'@' { p.i = save; break }
        let start = p.i;
        p.i += 1;
        kids.push(p.make_span("@", false, start));
        ws(p, &mut kids);
        if !parse_primary_expression(p, &mut kids) { p.i = save; break }
        out.push(p.make_node("decorator", true, start, kids));
        found = true;
    }
    found
}
