                if !parse_expression(p, &mut item, 0) { break }
                kids.push(p.make_node("pair", true, is, item));
            } else {
                // shorthand property
                let k = p.make_node("shorthand_property_identifier", true, is, item);
                kids.push(k);
            }
        }
        ws(p, &mut kids);
        if !lit(p, ",", &mut kids) { break }
    }
    ws(p, &mut kids);
    let _ = lit(p, "}", &mut kids);
    out.push(p.make_node("object", true, start, kids));
