}

fn parse_array(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b'[' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span("[", false, start));
    p.i += 1;
    loop {
        ws(p, &mut kids);
        if p.cur() == b']' || p.eof() { break }
        let as_ = p.i;
        let mut item = Kids::new();
        if p.text_at("...") {
            let rs = p.i;
            p.i += 3;
            item.push(p.make_span("...", false, rs));
            ws(p, &mut item);
            let _ = parse_expression(p, &mut item, 0);
            kids.push(p.make_node("spread_element", true, as_, item));
        } else {
            if !parse_expression(p, &mut item, 0) {
                if p.cur() != b',' { break }
            } else {
                kids.push(item.pop().unwrap());
            }
        }
        ws(p, &mut kids);
        if !lit(p, ",", &mut kids) { break }
    }
    ws(p, &mut kids);
    let _ = lit(p, "]", &mut kids);
    out.push(p.make_node("array", true, start, kids));
    true
}
