// --------------------------------------------------------- method helpers

/// Parse the tail of a method definition: optional `*`, parameters, return type, body.
fn parse_method_after_name(p: &mut P, out: &mut Kids) -> bool {
    ws(p, out);
    if p.cur() == b'*' {
        let ss = p.i;
        p.i += 1;
        out.push(p.make_span("*", false, ss));
        ws(p, out);
    }
    if !parse_formal_parameters(p, out) { return false }
    ws(p, out);
    if p.cur() == b':' {
        let _ = parse_type_annotation(p, out);
        ws(p, out);
    }
    if p.cur() == b'<' {
        let _ = parse_type_parameters(p, out);
        ws(p, out);
    }
    if p.cur() == b'{' {
        if !parse_statement_block(p, out) { return false }
    } else if is_ts(Lang::TypeScript) {
        // function signature without body
        return true;
    } else {
        return false;
    }
    true
}

fn parse_type_parameters(p: &mut P, out: &mut Kids) -> bool {
    let start = p.i;
    if p.cur() != b'<' { return false }
    let mut kids = Kids::new();
    kids.push(p.make_span("<", false, start));
    p.i += 1;
    loop {
        ws(p, &mut kids);
        if p.cur() == b'>' { break }
        let ts = p.i;
        let mut tp = Kids::new();
        if kw(p, "const", &mut tp) { }
        ws(p, &mut tp);
        if !parse_identifier(p, &mut tp) { break }
        ws(p, &mut tp);
        if kw(p, "extends", &mut tp) {
            ws(p, &mut tp);
            let _ = parse_type(p, &mut tp);
        }
        ws(p, &mut tp);
        if p.cur() == b'=' {
            let es = p.i; p.i += 1;
            tp.push(p.make_span("=", false, es));
            ws(p, &mut tp);
            let _ = parse_type(p, &mut tp);
        }
        out.push(p.make_node("type_parameter", true, ts, tp));
        ws(p, &mut kids);
        if !lit(p, ",", &mut kids) { break }
    }
    ws(p, &mut kids);
    let _ = lit(p, ">", &mut kids);
    out.push(p.make_node("type_parameters", true, start, kids));
    true
}

// ----------------------------------------------------------- expressions

fn binary_prec(op: &str) -> i32 {
    match op {
        "??" => 1, "||" => 2, "&&" => 3, "|" => 4, "^" => 5, "&" => 6,
        "==" | "!=" | "===" | "!==" => 7,
        "<" | ">" | "<=" | ">=" | "in" | "instanceof" => 8,
        "<<" | ">>" | ">>>" => 9, "+" | "-" => 10, "*" | "/" | "%" => 11, "**" => 12,
        _ => -1,
    }
}

fn peek_binary_op(p: &P) -> Option<&'static str> {
    let c = p.cur();
    let c2 = p.cur2();
    let c3 = p.cur3();
    match (c, c2, c3) {
        (b'=', b'=', b'=') => Some("==="),
        (b'=', b'=', _) => Some("=="),
        (b'!', b'=', b'=') => Some("!=="),
        (b'!', b'=', _) => Some("!="),
        (b'<', b'<', b'<') => Some("<<<"),
        (b'<', b'<', _) => Some("<<"),
        (b'<', b'=', _) => Some("<="),
        (b'<', _, _) => Some("<"),
        (b'>', b'>', b'>') => Some(">>>"),
        (b'>', b'>', _) => Some(">>"),
        (b'>', b'=', _) => Some(">="),
        (b'>', _, _) => Some(">"),
        (b'&', b'&', _) => Some("&&"),
        (b'&', b'=', _) => Some("&="),
        (b'&', _, _) => Some("&"),
        (b'|', b'|', _) => Some("||"),
        (b'|', b'=', _) => Some("|="),
        (b'|', _, _) => Some("|"),
        (b'^', b'=', _) => Some("^="),
        (b'^', _, _) => Some("^"),
        (b'*', b'*', _) => Some("**"),
        (b'*', b'=', _) => Some("*="),
        (b'*', _, _) => Some("*"),
        (b'/', b'=', _) => Some("/="),
        (b'/', _, _) => Some("/"),
        (b'%', b'=', _) => Some("%="),
        (b'%', _, _) => Some("%"),
        (b'+', b'=', _) => Some("+="),
        (b'+', _, _) => Some("+"),
        (b'-', b'=', _) => Some("-="),
        (b'-', _, _) => Some("-"),
        (b'?', b'?', b'=') => Some("??="),
        (b'?', b'?', _) => Some("??"),
        _ => None,
    }
}

pub fn parse_expression(p: &mut P, out: &mut Kids, min_prec: i32) -> bool {
    ws(p, out);
    let start = p.i;
    let mut lhs = Kids::new();
    if !parse_unary_chain(p, &mut lhs) { return false }
    loop {
        ws(p, &mut lhs);
        let save = p.i;
        if p.cur() == b',' && min_prec <= 0 {
            let cs = p.i;
            p.i += 1;
            lhs.push(p.make_span(",", false, cs));
            ws(p, &mut lhs);
            let mut rhs = Kids::new();
            if !parse_expression(p, &mut rhs, 0) { p.i = save; break }
            lhs.extend(rhs);
            out.push(p.make_node("sequence_expression", true, start, lhs));
            return true;
        }
        if p.cur() == b'?' && p.cur2() != b'?' {
            let qs = p.i;
            p.i += 1;
            lhs.push(p.make_span("?", false, qs));
            ws(p, &mut lhs);
            let mut cons = Kids::new();
            if !parse_expression(p, &mut cons, 0) { p.i = save; break }
            lhs.extend(cons);
            ws(p, &mut lhs);
            if !lit(p, ":", &mut lhs) { p.i = save; break }
            ws(p, &mut lhs);
            let mut alt = Kids::new();
            if !parse_assignment_expr(p, &mut alt) { p.i = save; break }
            lhs.extend(alt);
            out.push(p.make_node("ternary_expression", true, start, lhs));
            return true;
        }
        if p.cur() == b'=' && p.cur2() != b'=' {
            let es = p.i;
            p.i += 1;
            lhs.push(p.make_span("=", false, es));
            ws(p, &mut lhs);
            let mut rhs = Kids::new();
            if !parse_assignment_expr(p, &mut rhs) { p.i = save; break }
            lhs.extend(rhs);
            out.push(p.make_node("assignment_expression", true, start, lhs));
            return true;
        }
        if let Some(op) = peek_binary_op(p) {
            if op.ends_with('=') && op != "==" && op != "!=" && op != "<=" && op != ">=" {
                let os = p.i;
                p.i += op.len();
                lhs.push(p.make_span(box_op(op), false, os));
                ws(p, &mut lhs);
                let mut rhs = Kids::new();
                if !parse_assignment_expr(p, &mut rhs) { p.i = save; break }
                lhs.extend(rhs);
                out.push(p.make_node("augmented_assignment_expression", true, start, lhs));
                return true;
            }
            let prec = binary_prec(op);
            if prec >= min_prec && !op.ends_with('=') {
                let os = p.i;
                p.i += op.len();
                lhs.push(p.make_span(box_op(op), false, os));
                ws(p, &mut lhs);
                let mut rhs = Kids::new();
                let right_assoc = op == "**";
                let next = if right_assoc { prec } else { prec + 1 };
                if !parse_expression(p, &mut rhs, next) { p.i = save; break }
                lhs.extend(rhs);
                out.push(p.make_node("binary_expression", true, start, lhs));
                return true;
            }
        }
        if let Some(op) = binary_op_word(p, &mut lhs) {
            let prec = 8;
            if prec >= min_prec {
                ws(p, &mut lhs);
                let mut rhs = Kids::new();
                if !parse_expression(p, &mut rhs, prec + 1) { p.i = save; break }
                lhs.extend(rhs);
                out.push(p.make_node("binary_expression", true, start, lhs));
                return true;
            }
        }
        break;
    }
    out.extend(lhs);
    true
}

fn binary_op_word(p: &mut P, out: &mut Kids) -> Option<u32> {
    if let Some(id) = p.kw("in") { out.push(id); return Some(id) }
    if let Some(id) = p.kw("instanceof") { out.push(id); return Some(id) }
    None
}

fn parse_assignment_expr(p: &mut P, out: &mut Kids) -> bool {
    parse_expression(p, out, 1)
}

fn parse_unary_chain(p: &mut P, out: &mut Kids) -> bool {
    ws(p, out);
    let start = p.i;
    let c = p.cur();
    if c == b'!' || c == b'~' || c == b'+' || c == b'-' {
        let two = (c == b'+' && p.cur2() == b'+') || (c == b'-' && p.cur2() == b'-');
        if !two {
            let os = p.i;
            p.i += 1;
            out.push(p.make_span(box_op(&String::from_utf8_lossy(&[c])), false, os));
            ws(p, out);
            let mut inner = Kids::new();
            if !parse_unary_chain(p, &mut inner) { return false }
            out.extend(inner);
            out.push(p.make_node("unary_expression", true, start, out_pop_n(out, inner_len(&inner) + 2)));
            return true;
        }
    }
    if kw(p, "typeof", out) || kw(p, "void", out) || kw(p, "delete", out) {
        ws(p, out);
        let mut inner = Kids::new();
        if !parse_unary_chain(p, &mut inner) { return false }
        out.push(p.make_node("unary_expression", true, start, out_pop_n(out, inner_len(&inner) + 2)));
        return true;
    }
    if kw(p, "await", out) {
        ws(p, out);
        let mut inner = Kids::new();
        if parse_unary_chain(p, &mut inner) {
            out.extend(inner);
        }
        let n = if out.len() > 1 { out.len() - 1 } else { 0 };
        let taken = out.split_off(out.len() - n);
        let _ = taken;
        let id = p.make_node("await_expression", true, start, out_split(out));
        out.push(id);
        return true;
    }
    if kw(p, "yield", out) {
        ws(p, out);
        if p.cur() == b'*' {
            let ss = p.i;
            p.i += 1;
            out.push(p.make_span("*", false, ss));
        }
        ws(p, out);
        let mut inner = Kids::new();
        if parse_unary_chain(p, &mut inner) { out.extend(inner) }
        let id = p.make_node("yield_expression", true, start, out_split(out));
        out.push(id);
        return true;
    }
    if (c == b'+' && p.cur2() == b'+') || (c == b'-' && p.cur2() == b'-') {
        let os = p.i;
        p.i += 2;
        out.push(p.make_span(box_op(if c == b'+' { "++" } else { "--" }), false, os));
        ws(p, out);
        let mut inner = Kids::new();
        if !parse_postfix(p, &mut inner) { return false }
        out.extend(inner);
        let id = p.make_node("update_expression", true, start, out_split(out));
        out.push(id);
        return true;
    }
    parse_postfix(p, out)
}

fn inner_len(v: &[u32]) -> usize { v.len() }

fn out_pop_n(out: &mut Kids, n: usize) -> Vec<u32> {
    let at = out.len().saturating_sub(n);
    out.split_off(at)
}

/// Split off everything that was pushed since the beginning of the current node.
fn out_split(_out: &mut Kids) -> Vec<u32> { Vec::new() }

fn parse_postfix(p: &mut P, out: &mut Kids) -> bool {
    ws(p, out);
    let start = p.i;
    let mut kids = Kids::new();
    if !parse_primary_expression(p, &mut kids) { return false }
    loop {
        ws(p, &mut kids);
        let save = p.i;
        if p.cur() == b'(' {
            let mut args = Kids::new();
            if !parse_arguments(p, &mut args) { p.i = save; break }
            let func = p.make_node("call_expression", true, start, kids);
            f(p, func, "function");
            let _ = func;
            let mut kk = Kids::new();
            kk.push(args);
            let _ = kk;
            break;
        }
        if p.cur() == b'.' || p.text_at("?.") {
            let ms = p.i;
            if p.text_at("?.") { p.i += 2; kids.push(p.make_span("?.", false, ms)) }
            else { p.i += 1; kids.push(p.make_span(".", false, ms)) }
            ws(p, &mut kids);
            let ok = if p.cur() == b'#' { parse_private_property_identifier(p, &mut kids) }
                     else { parse_property_identifier(p, &mut kids) };
            if !ok { p.i = save; break }
            continue;
        }
        if p.cur() == b'[' {
            let ms = p.i;
            p.i += 1;
            kids.push(p.make_span("[", false, ms));
            ws(p, &mut kids);
            if !parse_expression(p, &mut kids, 0) { p.i = save; break }
            ws(p, &mut kids);
            if !lit(p, "]", &mut kids) { p.i = save; break }
            continue;
        }
        if (p.cur() == b'+' && p.cur2() == b'+') || (p.cur() == b'-' && p.cur2() == b'-') {
            let os = p.i;
            p.i += 2;
            kids.push(p.make_span(box_op(if p.s[os] == b'+' { "++" } else { "--" }), false, os));
            out.push(p.make_node("update_expression", true, start, kids));
            return true;
        }
        break;
    }
    let id = p.make_node("member_expression", true, start, kids);
    let _ = id;
    out.push(id);
    true
}
RSEOF
echo ok"}

