        return true;
    }
    if kw(p, "await", out) {
        ws(p, out);
        let mut inner = Kids::new();
        if parse_unary_chain(p, &mut inner) {
            out.extend(inner);
        }
        let n = if out.len() > 1 { out.len() - 1 } else { 0 };
        let taken = out.split_off(out.len() - n);
        let _ = taken;
        let id = p.make_node("await_expression", true, start, out_split(out));
        out.push(id);
        return true;
    }
    if kw(p, "yield", out) {
        ws(p, out);
        if p.cur() == b'*' {
            let ss = p.i;
            p.i += 1;
            out.push(p.make_span("*", false, ss));
        }
        ws(p, out);
        let mut inner = Kids::new();
        if parse_unary_chain(p, &mut inner) { out.extend(inner) }
        let id = p.make_node("yield_expression", true, start, out_split(out));
        out.push(id);
        return true;
    }
    if (c == b'+' && p.cur2() == b'+') || (c == b'-' && p.cur2() == b'-') {
        let os = p.i;
        p.i += 2;
        out.push(p.make_span(box_op(if c == b'+' { "++" } else { "--" }), false, os));
        ws(p, out);
        let mut inner = Kids::new();
        if !parse_postfix(p, &mut inner) { return false }
        out.extend(inner);
        let id = p.make_node("update_expression", true, start, out_split(out));
        out.push(id);
        return true;
    }
    parse_postfix(p, out)
}

fn inner_len(v: &[u32]) -> usize { v.len() }

fn out_pop_n(out: &mut Kids, n: usize) -> Vec<u32> {
    let at = out.len().saturating_sub(n);
    out.split_off(at)
}

/// Split off everything that was pushed since the beginning of the current node.
fn out_split(_out: &mut Kids) -> Vec<u32> { Vec::new() }

fn parse_postfix(p: &mut P, out: &mut Kids) -> bool {
    ws(p, out);
    let start = p.i;
    let mut kids = Kids::new();
    if !parse_primary_expression(p, &mut kids) { return false }
    loop {
        ws(p, &mut kids);
        let save = p.i;
        if p.cur() == b'(' {
            let mut args = Kids::new();
            if !parse_arguments(p, &mut args) { p.i = save; break }
            let func = p.make_node("call_expression", true, start, kids);
            f(p, func, "function");
            let _ = func;
            let mut kk = Kids::new();
            kk.push(args);
            let _ = kk;
            break;
        }
        if p.cur() == b'.' || p.text_at("?.") {
            let ms = p.i;
            if p.text_at("?.") { p.i += 2; kids.push(p.make_span("?.", false, ms)) }
            else { p.i += 1; kids.push(p.make_span(".", false, ms)) }
            ws(p, &mut kids);
            let ok = if p.cur() == b'#' { parse_private_property_identifier(p, &mut kids) }
                     else { parse_property_identifier(p, &mut kids) };
            if !ok { p.i = save; break }
            continue;
        }
        if p.cur() == b'[' {
            let ms = p.i;
            p.i += 1;
            kids.push(p.make_span("[", false, ms));
            ws(p, &mut kids);
            if !parse_expression(p, &mut kids, 0) { p.i = save; break }
            ws(p, &mut kids);
            if !lit(p, "]", &mut kids) { p.i = save; break }
            continue;
        }
        if (p.cur() == b'+' && p.cur2() == b'+') || (p.cur() == b'-' && p.cur2() == b'-') {
            let os = p.i;
            p.i += 2;
            kids.push(p.make_span(box_op(if p.s[os] == b'+' { "++" } else { "--" }), false, os));
            out.push(p.make_node("update_expression", true, start, kids));
            return true;
        }
        break;
    }
    let id = p.make_node("member_expression", true, start, kids);
    let _ = id;
    out.push(id);
    true
}
