{"command": "cd /workspace && cat > src/parser/mod.rs <<'RSEOF'
//! Shared parser infrastructure: cursor, token helpers, node construction.

use crate::lang::Lang;
use crate::tree::{Node, Tree, NONE};

struct Frame {
    kind: &'static str,
    named: bool,
    start: usize,
    kids: Vec<u32>,
}

pub struct P<'a> {
    pub s: &'a [u8],
    pub i: usize,
    pub nodes: Vec<Node>,
    stack: Vec<Frame>,
}

#[derive(Clone, Copy)]
pub struct Mark {
    i: usize,
    n: usize,
    depth: usize,
}

impl<'a> P<'a> {
    pub fn new(s: &'a str) -> Self {
        P { s: s.as_bytes(), i: 0, nodes: Vec::new(), stack: Vec::new() }
    }

    pub fn len(&self) -> usize { self.s.len() }
    pub fn cur(&self) -> u8 { if self.i < self.s.len() { self.s[self.i] } else { 0 } }
    pub fn cur2(&self) -> u8 { if self.i + 1 < self.s.len() { self.s[self.i + 1] } else { 0 } }
    pub fn cur3(&self) -> u8 { if self.i + 2 < self.s.len() { self.s[self.i + 2] } else { 0 } }
    pub fn eof(&self) -> bool { self.i >= self.s.len() }

    pub fn text_at(&self, t: &str) -> bool {
        let b = t.as_bytes();
        self.s.len() >= self.i + b.len() && &self.s[self.i..self.i + b.len()] == b
    }

    pub fn is_word(&self, c: u8) -> bool {
        c.is_ascii_alphanumeric() || c == b'_' || c == b'$' || c >= 0x80
    }

    fn word_follows(&self, pos: usize) -> bool {
        pos < self.s.len() && self.is_word(self.s[pos])
    }

    // ------------------------------------------------------------- markers

    pub fn mark(&self) -> Mark { Mark { i: self.i, n: self.nodes.len(), depth: self.stack.len() } }

    pub fn reset(&mut self, m: Mark) {
        self.i = m.i;
        self.nodes.truncate(m.n);
        self.stack.truncate(m.depth);
    }

    // --------------------------------------------------------- node building

    pub fn begin(&mut self, kind: &'static str, named: bool) {
        self.stack.push(Frame { kind, named, start: self.i, kids: Vec::new() });
    }

    pub fn push(&mut self, id: u32) { self.stack.last_mut().unwrap().kids.push(id); }

    pub fn end(&mut self) -> u32 {
        let f = self.stack.pop().expect("unbalanced begin/end");
        let id = self.nodes.len() as u32;
        self.nodes.push(Node {
            kind: f.kind,
            named: f.named,
            field: None,
            start: f.start,
            end: self.i,
            children: f.kids,
            parent: NONE,
            is_error: f.kind == "ERROR",
        });
        if let Some(top) = self.stack.last_mut() {
            top.kids.push(id);
        }
        id
    }

    /// Create a node from an explicit list of children (used for ad-hoc nodes).
    pub fn make_node(
        &mut self,
        kind: &'static str,
        named: bool,
        start: usize,
        children: Vec<u32>,
    ) -> u32 {
        let id = self.nodes.len() as u32;
        self.nodes.push(Node {
            kind,
            named,
            field: None,
            start,
            end: self.i,
            children,
            parent: NONE,
            is_error: kind == "ERROR",
        });
        if let Some(top) = self.stack.last_mut() {
            top.kids.push(id);
        }
        id
    }

    pub fn set_field(&mut self, id: u32, field: &str) {
        if let Some(f) = crate::tree::field_idx(field) {
            self.nodes[id as usize].field = Some(f);
        }
    }

    // ------------------------------------------------------------- tokens

    pub fn kw(&mut self, w: &'static str) -> bool {
        if self.text_at(w) && !self.word_follows(self.i + w.len()) {
            let start = self.i;
            self.i += w.len();
            let id = self.make_token(w, false, start);
            self.push(id);
            true
        } else {
            false
        }
    }

    pub fn kw_ci(&mut self, w: &'static str) -> bool {
        let b = w.as_bytes();
        if self.i + b.len() <= self.s.len()
            && self.s[self.i..self.i + b.len()].eq_ignore_ascii_case(b)
            && !self.word_follows(self.i + b.len())
        {
            let start = self.i;
            self.i += b.len();
            let id = self.make_token(w, false, start);
            self.push(id);
            true
        } else {
            false
        }
    }

    pub fn lit(&mut self, l: &'static str) -> bool {
        if self.text_at(l) && !self.word_follows(self.i + l.len()) {
            let start = self.i;
            self.i += l.len();
            let id = self.make_token(l, false, start);
            self.push(id);
            true
        } else {
            false
        }
    }

    fn make_token(&mut self, kind: &'static str, named: bool, start: usize) -> u32 {
        let id = self.nodes.len() as u32;
        self.nodes.push(Node {
            kind,
            named,
            field: None,
            start,
            end: self.i,
            children: Vec::new(),
            parent: NONE,
            is_error: false,
        });
        id
    }

    /// Skip whitespace and comments, adding comment nodes to the current node.
    pub fn ws(&mut self, lang: Lang) {
        loop {
            let c = self.cur();
            match c {
                b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c => { self.i += 1; }
                _ => {
                    if let Some(cm) = self.try_comment(lang) {
                        self.push(cm);
                    } else {
                        break;
                    }
                }
            }
        }
    }

    fn try_comment(&mut self, lang: Lang) -> Option<u32> {
        let hash_style = matches!(
            lang,
            Lang::Yaml | Lang::Bash | Lang::Ruby | Lang::Elixir | Lang::Nix | Lang::Lua | Lang::Php
        );
        if hash_style && self.cur() == b'#' {
            let start = self.i;
            while !self.eof() && self.cur() != b'\n' { self.i += 1; }
            return Some(self.make_token("comment", true, start));
        }
        match lang {
            Lang::Python => {
                if self.cur() == b'#' {
                    let start = self.i;
                    while !self.eof() && self.cur() != b'\n' { self.i += 1; }
                    return Some(self.make_token("comment", true, start));
                }
                None
            }
            Lang::Html => {
                if self.text_at("<!--") {
                    let start = self.i;
                    self.i += 4;
                    while !self.eof() && !self.text_at("-->") { self.i += 1; }
                    if self.text_at("-->") { self.i += 3; }
                    return Some(self.make_token("comment", true, start));
                }
                None
            }
            Lang::Haskell | Lang::Lua => {
                if self.text_at("--") {
                    let start = self.i;
                    self.i += 2;
                    while !self.eof() && self.cur() != b'\n' { self.i += 1; }
                    return Some(self.make_token("comment", true, start));
                }
                None
            }
            Lang::Css => {
                if self.text_at("/*") {
                    let start = self.i;
                    self.i += 2;
                    while !self.eof() && !self.text_at("*/") { self.i += 1; }
                    if self.text_at("*/") { self.i += 2; }
                    return Some(self.make_token("comment", true, start));
                }
                None
            }
            Lang::Json => {
                if self.text_at("//") {
                    let start = self.i;
                    self.i += 2;
                    while !self.eof() && self.cur() != b'\n' { self.i += 1; }
                    return Some(self.make_token("comment", true, start));
                }
                if self.text_at("/*") {
                    let start = self.i;
                    self.i += 2;
                    while !self.eof() && !self.text_at("*/") { self.i += 1; }
                    if self.text_at("*/") { self.i += 2; }
                    return Some(self.make_token("comment", true, start));
                }
                None
            }
            Lang::Bash => {
                if self.cur() == b'#' {
                    let start = self.i;
                    while !self.eof() && self.cur() != b'\n' { self.i += 1; }
                    return Some(self.make_token("comment", true, start));
                }
                None
            }
            _ => {
                if self.text_at("/*") {
                    let start = self.i;
                    self.i += 2;
                    while !self.eof() && !self.text_at("*/") { self.i += 1; }
                    if self.text_at("*/") { self.i += 2; }
                    return Some(self.make_token("comment", true, start));
                }
                if self.text_at("//") {
                    let start = self.i;
                    self.i += 2;
                    while !self.eof() && self.cur() != b'\n' { self.i += 1; }
                    return Some(self.make_token("comment", true, start));
                }
                None
            }
        }
    }
}

/// Parse `src` with the language's parser, returning a tree whose root is a
/// top level container node (`program`, `module`, ...).
pub fn parse(lang: Lang, src: &str) -> Tree {
    let mut p = crate::parser::imp::parse_with(lang, src);
    // flush remaining stack frames
    while p.stack.len() > 1 {
        p.end();
    }
    p.set_parents();
    let root = if p.nodes.is_empty() { 0 } else { (p.nodes.len() - 1) as u32 };
    Tree { nodes: p.nodes, root }
}
RSEOF
echo ok"}

