                p.push(p.make_node("string_fragment", true, fs2, Vec::new()));
                have_frag = true;
            }
            continue;
        }
        if !have_frag && p.i > fs { }
        p.i += 1;
    }
    if have_frag || p.i > fs {
        if p.nodes.last().map(|n| n.kind) != Some("string_fragment") {
            p.push(p.make_node("string_fragment", true, fs, Vec::new()));
        }
    }
    if p.cur() == quote {
        let qs = p.i;
        p.i += 1;
        p.push(p.make_node(q, false, qs, Vec::new()));
    }
    Some(p.end())
}

fn template_string(p: &mut P) -> Option<u32> {
    if p.cur() != b'`' { return None }
    let start = p.i;
    p.begin("template_string", true);
    let qs = p.i;
    p.i += 1;
    p.push(p.make_node("`", false, qs, Vec::new()));
    loop {
        if p.eof() { break }
        if p.cur() == b'`' {
