// ---------------------------------------------------------- type syntax

fn type_ident(p: &mut P) -> Option<u32> {
    let start = p.i;
    p.begin("type_identifier", true);
    if ident(p).is_none() { p.reset_to(start); return None }
    let mut has_dot = false;
    loop {
        ws(p);
        if p.cur() == b'.' {
            let ds = p.i;
            p.i += 1;
            p.push(p.make_node(".", false, ds, Vec::new()));
            if ident(p).is_none() { break }
            has_dot = true;
        } else { break }
    }
    if has_dot {
        // rebuild as nested_type_identifier
        let kids = std::mem::take(&mut p.stack.last_mut().unwrap().kids);
        let s = p.stack.last().unwrap().start;
        p.pop_frame();
        p.push(p.make_node("nested_type_identifier", true, s, kids));
    }
    Some(p.end())
}

trait ResetTo { fn reset_to(&mut self, i: usize); }
impl ResetTo for P<'_> {
    fn reset_to(&mut self, i: usize) {
        // drop any nodes created since position i within the current frame
        if let Some(fr) = self.stack.last_mut() {
            let keep: Vec<u32> = fr.kids.iter().copied().filter(|&k| self.nodes[k as usize].end <= i || self.nodes[k as usize].start < i).collect();
            fr.kids = keep;
        }
        self.i = i;
        self.nodes.truncate(self.nodes.len());
    }
}

fn type_args(p: &mut P) -> bool {
    let start = p.i;
    if p.cur() != b'<' { return false }
    p.begin("type_arguments", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'>' { break }
        if !type_(p) { break }
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, ">");
    p.end();
    let _ = start;
    true
}

fn type_params(p: &mut P) -> bool {
    let start = p.i;
    if p.cur() != b'<' { return false }
    p.begin("type_parameters", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'>' { break }
        p.begin("type_parameter", true);
        let _ = kw(p, "const");
        ws(p);
        if ident(p).is_none() { p.end(); break }
        ws(p);
        if kw(p, "extends") { ws(p); let _ = type_(p); }
        ws(p);
        if p.cur() == b'=' {
            let es = p.i; p.i += 1;
            p.push(p.make_node("=", false, es, Vec::new()));
            ws(p);
            let _ = type_(p);
        }
        p.end();
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, ">");
    p.end();
    let _ = start;
    true
}

fn type_(p: &mut P) -> bool {
    let start = p.i;
    p.begin("union_type", true);
    if !type_inner(p) {
        p.reset_mark();
        return false;
    }
    loop {
        ws(p);
        let save = p.i;
        let is_union = p.cur() == b'|' && p.cur2() != b'|';
        let is_inter = p.cur() == b'&' && p.cur2() != b'&';
        if !(is_union || is_inter) { p.i = save; break }
        let os = p.i;
        p.i += 1;
        p.push(p.make_node("|", false, os, Vec::new()));
        ws(p);
        if !type_inner(p) { p.i = save; break }
    }
    p.end();
    let _ = start;
    true
