    loop {
        let save = p.i;
        ws(p);
        if p.cur() != b'@' { p.i = save; break }
        p.begin("decorator", true);
        p.i += 1;
        ws(p);
        if primary(p).is_none() { p.reset_mark(); p.i = save; break }
        p.end();
    }
