// -------------------------------------------------------------- patterns

fn pattern(p: &mut P) -> bool {
    ws(p);
    let start = p.i;
    match p.cur() {
        b'{' => {
            p.begin("object_pattern", true);
            p.i += 1;
            loop {
                ws(p);
                if p.cur() == b'}' || p.eof() { break }
                let is = p.i;
                if p.text_at("...") {
                    p.begin("rest_pattern", true);
                    let rs = p.i;
                    p.i += 3;
                    p.push(p.make_node("...", false, rs, Vec::new()));
                    ws(p);
                    let _ = pattern(p);
                    p.end();
                } else if p.cur() == b'[' {
                    let m = p.mark();
                    let inner = parenthesized_like_pattern(p, is);
                    let _ = inner;
                    let _ = m;
                } else {
                    p.begin("pair_pattern", true);
                    let key = if p.cur() == b'"' || p.cur() == b'\'' { string(p) }
                              else if p.cur() == b'#' { private_prop_ident(p) }
                              else { prop_ident(p) };
                    if key.is_none() { p.reset_mark(); break }
                    ws(p);
                    if p.cur() == b'=' {
                        // shorthand with default
                        let kids = p.swap_frame_kind("object_assignment_pattern");
                        let _ = kids;
                        let es = p.i; p.i += 1;
                        p.push(p.make_node("=", false, es, Vec::new()));
                        ws(p);
                        let _ = expression(p, 0);
                        p.end();
                    } else if p.cur() == b':' {
                        let cs = p.i; p.i += 1;
                        p.push(p.make_node(":", false, cs, Vec::new()));
                        ws(p);
                        if !pattern(p) { p.reset_mark(); break }
                        p.end();
                    } else {
                        let kids = p.swap_frame_kind("shorthand_property_identifier_pattern");
                        let _ = kids;
                        p.end();
                    }
                }
                ws(p);
                if !lit(p, ",") { break }
            }
            ws(p);
            let _ = lit(p, "}");
            p.end();
            true
        }
        b'[' => {
            p.begin("array_pattern", true);
            p.i += 1;
            loop {
                ws(p);
                if p.cur() == b']' || p.eof() { break }
                let is = p.i;
                if p.text_at("...") {
                    p.begin("rest_pattern", true);
                    let rs = p.i;
                    p.i += 3;
                    p.push(p.make_node("...", false, rs, Vec::new()));
                    ws(p);
                    let _ = pattern(p);
                    p.end();
                } else {
                    let m = p.mark();
                    p.begin("array_pattern", true);
                    if pattern(p) {
                        ws(p);
                        if p.cur() == b'=' {
                            let kids = p.swap_frame_kind("object_assignment_pattern");
                            let _ = kids;
                            let es = p.i; p.i += 1;
                            p.push(p.make_node("=", false, es, Vec::new()));
                            ws(p);
                            let _ = expression(p, 0);
                        }
                        p.end();
                    } else {
                        p.reset_mark();
                        p.reset(m);
                        break;
                    }
                }
                let _ = is;
                ws(p);
                if !lit(p, ",") { break }
            }
            ws(p);
            let _ = lit(p, "]");
            p.end();
            true
        }
        _ => {
            if kw(p, "this") {
                p.begin("this", true);
                p.end();
                return true;
            }
            ident(p).is_some()
        }
    }
}

fn parenthesized_like_pattern(p: &mut P, is: usize) -> bool {
    // computed property name pattern: [expr]: pattern
    p.begin("object_assignment_pattern", true);
    p.begin("computed_property_name", true);
    p.i += 1;
    ws(p);
    let _ = expression(p, 0);
    ws(p);
    let _ = lit(p, "]");
    p.end();
    ws(p);
    if p.cur() == b':' {
        let cs = p.i; p.i += 1;
        p.push(p.make_node(":", false, cs, Vec::new()));
        ws(p);
        let _ = pattern(p);
        p.end();
    } else {
        let kids = p.swap_frame_kind("array_pattern");
        let _ = kids;
        p.end();
    }
    let _ = is;
    true
}
