        "<<" | ">>" | ">>>" => 9, "+" | "-" => 10, "*" | "/" | "%" => 11, "**" => 12,
        _ => -1,
    }
}

fn peek_binary_op(p: &P) -> Option<&'static str> {
    let c = p.cur();
    let c2 = p.cur2();
    let c3 = p.cur3();
    match (c, c2, c3) {
