        (b'>', _, _) => Some(">"),
        (b'&', b'&', _) => Some("&&"),
        (b'&', b'=', _) => Some("&="),
        (b'&', _, _) => Some("&"),
        (b'|', b'|', _) => Some("||"),
        (b'|', b'=', _) => Some("|="),
        (b'|', _, _) => Some("|"),
        (b'^', b'=', _) => Some("^="),
        (b'^', _, _) => Some("^"),
        (b'*', b'*', _) => Some("**"),
        (b'*', b'=', _) => Some("*="),
        (b'*', _, _) => Some("*"),
        (b'/', b'=', _) => Some("/="),
        (b'/', _, _) => Some("/"),
        (b'%', b'=', _) => Some("%="),
        (b'%', _, _) => Some("%"),
        (b'+', b'=', _) => Some("+="),
        (b'+', _, _) => Some("+"),
        (b'-', b'=', _) => Some("-="),
        (b'-', _, _) => Some("-"),
        (b'?', b'?', b'=') => Some("??="),
        (b'?', b'?', _) => Some("??"),
