pub fn expression(p: &mut P, min_prec: i32) -> Option<u32> {
    ws(p);
    let start = p.i;
    p.begin("expression", true);
    let lhs_start = p.nodes.len();
    if unary_chain(p).is_none() {
        p.reset_mark();
        return None;
    }
    loop {
        ws(p);
        let save = p.i;
        if p.cur() == b',' && min_prec <= 0 {
            let cs = p.i;
            p.i += 1;
            p.push(p.make_node(",", false, cs, Vec::new()));
            ws(p);
            if expression(p, 0).is_none() { p.i = save; break }
            // rebuild as sequence_expression
            let kids = p.take_frame_kids();
            let s = p.frame_start();
            p.pop_frame();
            p.push(p.make_node("sequence_expression", true, s, kids));
            return Some(p.end());
        }
        if p.cur() == b'?' && p.cur2() != b'?' {
            let qs = p.i;
            p.i += 1;
            p.push(p.make_node("?", false, qs, Vec::new()));
            ws(p);
            if expression(p, 0).is_none() { p.i = save; break }
            ws(p);
            if !lit(p, ":") { p.i = save; break }
            ws(p);
            if assignment_expr(p).is_none() { p.i = save; break }
            let kids = p.take_frame_kids();
            let s = p.frame_start();
            p.pop_frame();
            p.push(p.make_node("ternary_expression", true, s, kids));
            return Some(p.end());
        }
        if p.cur() == b'=' && p.cur2() != b'=' {
            let es = p.i;
            p.i += 1;
            p.push(p.make_node("=", false, es, Vec::new()));
            ws(p);
            if assignment_expr(p).is_none() { p.i = save; break }
            let kids = p.take_frame_kids();
            let s = p.frame_start();
            p.pop_frame();
            p.push(p.make_node("assignment_expression", true, s, kids));
            return Some(p.end());
        }
        if let Some(op) = peek_binary_op(p) {
            if op.ends_with('=') && op != "==" && op != "!=" && op != "<=" && op != ">=" {
                let os = p.i;
                p.i += op.len();
                p.push(p.make_node(box_op(op), false, os, Vec::new()));
                ws(p);
                if assignment_expr(p).is_none() { p.i = save; break }
                let kids = p.take_frame_kids();
                let s = p.frame_start();
                p.pop_frame();
                p.push(p.make_node("augmented_assignment_expression", true, s, kids));
                return Some(p.end());
            }
            let prec = binary_prec(op);
            if prec >= min_prec && !op.ends_with('=') {
                let os = p.i;
                p.i += op.len();
                p.push(p.make_node(box_op(op), false, os, Vec::new()));
                ws(p);
                let right_assoc = op == "**";
                let next = if right_assoc { prec } else { prec + 1 };
                if expression(p, next).is_none() { p.i = save; break }
                let kids = p.take_frame_kids();
                let s = p.frame_start();
                p.pop_frame();
                p.push(p.make_node("binary_expression", true, s, kids));
                return Some(p.end());
            }
        }
        if kw(p, "in") || kw(p, "instanceof") {
            let prec = 8;
            if prec >= min_prec {
                ws(p);
                if expression(p, prec + 1).is_none() { p.i = save; break }
                let kids = p.take_frame_kids();
                let s = p.frame_start();
                p.pop_frame();
                p.push(p.make_node("binary_expression", true, s, kids));
                return Some(p.end());
            }
        }
        break;
    }
    // no operator consumed: unwrap the "expression" frame into its lhs
    if p.nodes.len() == lhs_start + 1 && p.nodes[lhs_start].kind != "expression" {
        // single lhs node: pop the frame and push the lhs directly
        let kids = p.take_frame_kids();
        let s = p.frame_start();
        p.pop_frame();
        let first = kids.into_iter().next();
        if let Some(k) = first {
            p.push(k);
            return Some(k);
        }
        return None;
    }
    let kids = p.take_frame_kids();
    let s = p.frame_start();
    p.pop_frame();
    let first = kids.into_iter().next();
    match first {
        Some(k) => { p.push(k); Some(k) }
        None => None,
    }
}

fn assignment_expr(p: &mut P) -> Option<u32> { expression(p, 1) }
