                    p.begin("import", true);
                    let args = match arguments(p) { Some(a) => a, None => { p.reset_mark(); return None } };
                    f(p, args, "source");
                    p.push(args);
                    p.end_node().into()
                } else {
                    None
                }
            } else if ident(p).is_some() {
                Some(p.nodes_last_id())
            } else {
                None
            }
        }
    }
}

fn reorder_new(p: &mut P, id: u32) -> u32 {
    // children were pushed as [callee, arguments]; tree-sitter order is
    // constructor then arguments, so swap if needed.
    let kids = p.nodes[id as usize].children.clone();
    if kids.len() == 2 && p.nodes[kids[1] as usize].kind == "arguments" {
        let swapped = vec![kids[1], kids[0]];
        p.nodes[id as usize].children = swapped;
    }
    id
}

fn postfix_no_call(p: &mut P) -> Option<u32> {
    let mut base = primary(p)?;
    loop {
        ws(p);
        let save = p.i;
        if p.cur() == b'.' || p.text_at("?.") {
            let ms = p.i;
            p.i += if p.text_at("?.") { 2 } else { 1 };
            p.begin("member_expression", true);
            p.push(p.make_node(if p.s[ms] == b'?' { "?." } else { "." }, false, ms, Vec::new()));
            ws(p);
            let prop = if p.cur() == b'#' { private_prop_ident(p) } else { prop_ident(p) };
            let prop = match prop { Some(x) => x, None => { p.reset_mark(); p.i = save; break } };
            p.push(base);
            p.push(prop);
            f(p, prop, "property");
            base = p.end_node();
            continue;
        }
        if p.cur() == b'[' {
            let ms = p.i;
            p.i += 1;
            p.begin("subscript_expression", true);
            p.push(p.make_node("[", false, ms, Vec::new()));
            ws(p);
            let idx = match expression(p, 0) { Some(x) => x, None => { p.reset_mark(); p.i = save; break } };
            ws(p);
            if !lit(p, "]") { p.reset_mark(); p.i = save; break }
            p.push(base);
            f(p, base, "object");
            p.push(idx);
            f(p, idx, "index");
            base = p.end_node();
            continue;
        }
        break;
    }
    Some(base)
}

fn nodes_last_id(p: &P) -> u32 { (p.nodes.len() - 1) as u32 }
