{"command": "cd /workspace && cat >> src/parser/js.rs <<'RSEOF'

// ------------------------------------------------------------- statements

pub fn statement_block(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'{' { return None }
    p.begin("statement_block", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        if statement(p).is_none() {
            error_recovery(p);
        }
    }
    ws(p);
    let _ = lit(p, "}");
    Some(p.end())
}

fn error_recovery(p: &mut P) {
    let start = p.i;
    if p.eof() { return }
    // consume until a statement boundary
    while !p.eof() {
        let c = p.cur();
        if c == b';' { p.i += 1; break }
        if c == b'\n' { p.i += 1; break }
        if c == b'}' { break }
        p.i += 1;
    }
    p.push(p.make_node("ERROR", true, start, Vec::new()));
}

fn semicolon(p: &mut P) -> bool {
    if p.cur() == b';' {
        lit(p, ";");
        true
    } else {
        // automatic semicolon insertion: consume a newline if present
        false
    }
}

fn opt_semicolon(p: &mut P) {
    let save = p.i;
    ws(p);
    if p.cur() == b';' {
        lit(p, ";");
    } else {
        p.i = save;
    }
}

pub fn statement(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    let c = p.cur();
    match c {
        b';' => {
            p.begin("empty_statement", true);
            p.i += 1;
            Some(p.end_node())
        }
        b'{' => statement_block(p),
        b'#' if p.text_at("#!") => {
            p.begin("hash_bang_line", true);
            while !p.eof() && p.cur() != b'\n' { p.i += 1 }
            Some(p.end_node())
        }
        b'@' => {
            decorators(p);
            statement(p)
        }
        b'0'..=b'9' | b'"' | b'\'' | b'`' | b'/' | b'[' | b'(' | b'+' | b'-' | b'!' | b'~'
        | b'!' | b'?' | b'*' | b'&' => {
            let id = expression(p, 0)?;
            p.begin("expression_statement", true);
            p.push(id);
            opt_semicolon(p);
            Some(p.end_node())
        }
        _ => {
            // word-initial statements
            let m = p.mark();
            if kw(p, "const") || kw(p, "let") {
                if let Some(id) = lexical_declaration(p, start) { return Some(id) }
                p.reset(m);
            } else if kw(p, "var") {
                if let Some(id) = variable_declaration(p, start) { return Some(id) }
                p.reset(m);
            } else if kw(p, "function") {
                ws(p);
                let is_gen = p.cur() == b'*';
                if is_gen { p.i += 1; ws(p) }
                let _ = ident(p);
                ws(p);
                if formal_parameters(p) {
                    ws(p);
                    if statement_block(p).is_some() {
                        let kind = if is_gen { "generator_function_declaration" } else { "function_declaration" };
                        let kids = p.take_frame_kids();
                        p.pop_frame();
                        p.push(p.make_node(kind, true, start, kids));
                        return Some(p.nodes_last_id());
                    }
                }
                p.reset(m);
            } else if kw(p, "class") {
                if let Some(id) = class_decl(p, start, true) { return Some(id) }
                p.reset(m);
            } else if kw(p, "if") {
                if let Some(id) = if_statement(p, start) { return Some(id) }
                p.reset(m);
            } else if kw(p, "for") {
                if let Some(id) = for_statement(p, start) { return Some(id) }
                p.reset(m);
            } else if kw(p, "while") {
                ws(p);
                if p.cur() == b'(' {
                    p.begin("while_statement", true);
                    p.i += 1;
                    ws(p);
                    let cond = parenthesized(p);
                    match cond {
                        Some(cond) => {
                            f(p, cond, "condition");
                            p.push(cond);
                            ws(p);
                            let _ = statement(p);
                            opt_semicolon(p);
                            let id = p.end_node();
                            return Some(id);
                        }
                        None => { p.reset_mark(); p.reset(m) }
                    }
                }
                p.reset(m);
            } else if kw(p, "do") {
                p.begin("do_statement", true);
                ws(p);
                let _ = statement(p);
                ws(p);
                if kw(p, "while") {
                    ws(p);
                    if let Some(cond) = parenthesized(p) {
                        f(p, cond, "condition");
                        p.push(cond);
                    }
                }
                opt_semicolon(p);
                return Some(p.end_node());
            } else if kw(p, "try") {
                p.begin("try_statement", true);
                ws(p);
                if let Some(b) = statement_block(p) {
                    f(p, b, "body");
                    p.push(b);
                    ws(p);
                    if p.cur() == b'c' && p.text_at("catch") {
                        p.begin("catch_clause", true);
                        kw(p, "catch");
                        ws(p);
                        if p.cur() == b'(' {
                            p.begin("catch_parameters", true);
                            p.i += 1;
                            ws(p);
                            let _ = pattern(p);
                            ws(p);
                            let _ = lit(p, ")");
                            p.end();
                        }
                        ws(p);
                        if let Some(b) = statement_block(p) {
                            f(p, b, "body");
                            p.push(b);
                        }
                        let h = p.end_node();
                        f(p, h, "handler");
                        p.push(h);
                    }
                    ws(p);
                    if p.text_at("finally") {
                        p.begin("finally_clause", true);
                        kw(p, "finally");
                        ws(p);
                        if let Some(b) = statement_block(p) {
                            f(p, b, "body");
                            p.push(b);
                        }
                        let fin = p.end_node();
                        f(p, fin, "finalizer");
                        p.push(fin);
                    }
                    opt_semicolon(p);
                    return Some(p.end_node());
                }
                p.reset_mark();
                p.reset(m);
            } else if kw(p, "switch") {
                p.begin("switch_statement", true);
                ws(p);
                if let Some(v) = parenthesized(p) {
                    f(p, v, "value");
                    p.push(v);
                    ws(p);
                    if p.cur() == b'{' {
                        p.begin("switch_body", true);
                        p.i += 1;
                        loop {
                            ws(p);
                            if p.cur() == b'}' || p.eof() { break }
                            if p.text_at("case") {
                                p.begin("switch_case", true);
                                kw(p, "case");
                                ws(p);
                                if let Some(v) = expression(p, 0) {
                                    f(p, v, "value");
                                    p.push(v);
                                }
                                ws(p);
                                let _ = lit(p, ":");
                                loop {
                                    ws(p);
                                    if p.cur() == b'}' || p.eof() || p.text_at("case") || p.text_at("default") { break }
                                    if statement(p).is_none() { break }
                                }
                                p.end();
                            } else if p.text_at("default") {
                                p.begin("switch_default", true);
                                kw(p, "default");
                                ws(p);
                                let _ = lit(p, ":");
                                loop {
                                    ws(p);
                                    if p.cur() == b'}' || p.eof() || p.text_at("case") || p.text_at("default") { break }
                                    if statement(p).is_none() { break }
                                }
                                p.end();
                            } else {
                                break;
                            }
                        }
                        ws(p);
                        let _ = lit(p, "}");
                        let b = p.end_node();
                        f(p, b, "body");
                        p.push(b);
                    }
                    opt_semicolon(p);
                    return Some(p.end_node());
                }
                p.reset_mark();
                p.reset(m);
            } else if kw(p, "return") {
                p.begin("return_statement", true);
                ws(p);
                if p.cur() != b';' && p.cur() != b'}' && !p.eof() {
                    let _ = expression(p, 0);
                }
                opt_semicolon(p);
                return Some(p.end_node());
            } else if kw(p, "throw") {
                p.begin("throw_statement", true);
                ws(p);
                let _ = expression(p, 0);
                opt_semicolon(p);
                return Some(p.end_node());
            } else if kw(p, "break") || kw(p, "continue") {
                let is_break = p.nodes[p.nodes_last_id()].kind == "break";
                p.begin(if is_break { "break_statement" } else { "continue_statement" }, true);
                ws(p);
                if p.cur() != b';' && p.cur() != b'}' {
                    if let Some(l) = ident(p) {
                        f(p, l, "label");
                        p.push(l);
                    }
                }
                opt_semicolon(p);
                return Some(p.end_node());
            } else if kw(p, "debugger") {
                p.begin("debugger_statement", true);
                opt_semicolon(p);
                return Some(p.end_node());
            } else if kw(p, "import") {
                if let Some(id) = import_statement(p, start) { return Some(id) }
                p.reset(m);
            } else if kw(p, "export") {
                if let Some(id) = export_statement(p, start) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && kw(p, "interface") {
                if let Some(id) = interface_declaration(p, start) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && kw(p, "type") {
                if let Some(id) = type_alias(p, start) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && kw(p, "enum") {
                if let Some(id) = enum_declaration(p, start) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && (kw(p, "declare") || kw(p, "namespace") || kw(p, "module")) {
                if let Some(id) = ambient_or_namespace(p, start) { return Some(id) }
                p.reset(m);
            } else if kw(p, "async") {
                // async function / async arrow statement
                let after = p.i;
                if after < p.s.len() && p.is_word(p.s[after]) { p.reset(m); }
                else {
                    ws(p);
                    if p.text_at("function") {
                        kw(p, "function");
                        ws(p);
                        let is_gen = p.cur() == b'*';
                        if is_gen { p.i += 1; ws(p) }
                        let _ = ident(p);
                        ws(p);
                        if formal_parameters(p) {
                            ws(p);
                            if statement_block(p).is_some() {
                                let kind = if is_gen { "generator_function_declaration" } else { "function_declaration" };
                                let kids = p.take_frame_kids();
                                p.pop_frame();
                                p.push(p.make_node(kind, true, start, kids));
                                return Some(p.nodes_last_id());
                            }
                        }
                        p.reset(m);
                    } else {
                        p.reset(m);
                    }
                }
            }
            // labeled statement
            if let Some(l) = p.mark_try_ident() {
                let _ = l;
            }
            // try: identifier followed by ':' -> labeled statement
            {
                let save = p.i;
                if let Some(l) = ident(p) {
                    ws(p);
                    if p.cur() == b':' {
                        let cs = p.i;
                        p.i += 1;
                        p.begin("labeled_statement", true);
                        f(p, l, "label");
                        p.push(l);
                        p.push(p.make_node(":", false, cs, Vec::new()));
                        ws(p);
                        let _ = statement(p);
                        return Some(p.end_node());
                    }
                }
                p.i = save;
            }
            // fall back: expression statement
            let e = expression(p, 0)?;
            p.begin("expression_statement", true);
            p.push(e);
            opt_semicolon(p);
            Some(p.end_node())
        }
    }
}

trait MarkTryIdent { fn mark_try_ident(&mut self) -> Option<u32>; }
impl MarkTryIdent for P<'_> { fn mark_try_ident(&mut self) -> Option<u32> { None } }
RSEOF
echo ok"}

