            f(p, u, "increment");
        }
    }
    ws(p);
    if !lit(p, ")") { p.reset_mark(); return None }
    ws(p);
    if statement(p).is_none() { p.reset_mark(); return None }
    opt_semicolon(p);
    p.end_node()
