fn class_decl(p: &mut P, start: usize, top_level: bool) -> Option<u32> {
    let _ = top_level;
    ws(p);
    let is_abstract = kw(p, "abstract");
    ws(p);
    let _ = is_abstract;
    let name = ident(p);
    ws(p);
    // heritage
    let mut heritage = None;
    if kw(p, "extends") {
        p.begin("class_heritage", true);
        ws(p);
        let _ = expression(p, 0);
        heritage = Some(p.end_node());
    } else if is_ts(L) && kw(p, "implements") {
        p.begin("class_heritage", true);
        ws(p);
        loop {
            ws(p);
            if type_(p).is_none() { break }
            ws(p);
            if !lit(p, ",") { break }
        }
        heritage = Some(p.end_node());
    }
    ws(p);
    if p.cur() != b'{' { return None }
    p.begin("class_body", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        let m = p.mark();
        if class_member(p).is_none() { p.reset(m); error_recovery(p); }
    }
    ws(p);
    let _ = lit(p, "}");
    let body = p.end_node();
    f(p, body, "body");
    let kind = if is_abstract { "abstract_class_declaration" } else { "class_declaration" };
    p.begin(kind, true);
    if let Some(n) = name { p.push(n); f(p, n, "name") }
    if let Some(h) = heritage { p.push(h) }
    p.push(body);
    let _ = start;
    Some(p.end_node())
}

fn class_member(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    // static block
    if p.text_at("static") {
        let after = p.i + 6;
        if after < p.s.len() && p.s[after] == b'{' {
            kw(p, "static");
            ws(p);
            if let Some(b) = statement_block(p) {
                p.push(b);
                return Some(p.make_node("class_static_block", true, start, p.frame_pop_kids()));
            }
        }
    }
    p.begin("method_definition", true);
    let mut is_field = false;
    let mut has_value = false;
    // modifiers
    loop {
        ws(p);
        if kw(p, "public") || kw(p, "private") || kw(p, "protected")
            || kw(p, "static") || kw(p, "abstract") || kw(p, "override") || kw(p, "declare")
            || kw(p, "readonly") { continue }
        break
    }
    ws(p);
    if kw(p, "get") || kw(p, "set") {
        ws(p);
    }
    ws(p);
    if p.cur() == b'*' { p.i += 1; ws(p) }
    if p.cur() == b'async' {
        let after = p.i + 5;
        if !(after < p.s.len() && p.is_word(p.s[after])) { kw(p, "async"); ws(p); }
    }
    ws(p);
    // name
    let name = if p.cur() == b'[' {
        p.begin("computed_property_name", true);
        let cs = p.i;
        p.i += 1;
        p.push(p.make_node("[", false, cs, Vec::new()));
        ws(p);
        let _ = expression(p, 0);
        ws(p);
        let _ = lit(p, "]");
        Some(p.end_node())
    } else if p.cur() == b'#' {
        private_prop_ident(p)
    } else if p.cur() == b'"' || p.cur() == b'\'' {
        string(p)
    } else {
        prop_ident(p)
    };
    let name = match name { Some(n) => n, None => { p.reset_mark(); return None } };
    f(p, name, "name");
    ws(p);
    if p.cur() == b'<' && is_ts(L) {
        let _ = type_params(p);
        ws(p);
    }
    if p.cur() == b'(' {
        if !formal_parameters(p) { p.reset_mark(); return None }
        ws(p);
        if p.cur() == b':' { let _ = type_annotation(p); ws(p) }
        if p.cur() == b'{' {
            if statement_block(p).is_none() { p.reset_mark(); return None }
        } else if is_ts(L) {
            // signature only
        } else {
            p.reset_mark();
            return None;
        }
        let id = p.end_node();
        return Some(id);
    }
    // field definition
    is_field = true;
    if p.cur() == b'!' && is_ts(L) { p.i += 1; ws(p) }
    if p.cur() == b':' {
        let _ = type_annotation(p);
        ws(p);
    }
    if p.cur() == b'=' {
        let es = p.i; p.i += 1;
        p.push(p.make_node("=", false, es, Vec::new()));
        ws(p);
        if expression(p, 0).is_none() { p.reset_mark(); return None }
        has_value = true;
    }
    let _ = (is_field, has_value);
    let kids = p.take_frame_kids();
    let s = p.frame_start();
    p.pop_frame();
    p.push(p.make_node("field_definition", true, s, kids));
    opt_semicolon(p);
    Some(p.nodes_last_id())
}
