    let mut have_clause = false;
    if p.cur() == b'*' {
        p.begin("import_clause", true);
        p.begin("namespace_import", true);
        p.i += 1;
        ws(p);
        if kw(p, "as") {
            ws(p);
            let _ = ident(p);
        }
        p.end();
        p.end();
        have_clause = true;
    } else if p.cur() == b'{' {
        p.begin("import_clause", true);
        named_imports(p);
        p.end();
        have_clause = true;
    } else if p.cur() == b'"' || p.cur() == b'\'' {
