        let m = p.mark();
        let id = ident(p);
        if let Some(id) = id {
            p.begin("import_clause", true);
            p.push(id);
            ws(p);
            if p.cur() == b',' {
                p.i += 1;
                ws(p);
                if p.cur() == b'*' {
                    p.begin("namespace_import", true);
                    p.i += 1;
                    ws(p);
                    if kw(p, "as") { ws(p); let _ = ident(p) }
                    p.end();
                } else if p.cur() == b'{' {
                    named_imports(p);
                }
            }
            p.end();
            have_clause = true;
        } else {
            p.reset(m);
        }
    }
    ws(p);
    if p.cur() == b',' {
        p.i += 1;
        ws(p);
    }
    let from = kw(p, "from");
    if from {
        ws(p);
    }
    if p.cur() == b'"' || p.cur() == b'\'' {
        let s = string(p);
        if let Some(s) = s {
            f(p, s, "source");
            p.push(s);
        }
    } else if !from {
        p.reset_mark();
        return None;
    }
    // import attributes: with { ... }
    ws(p);
    if p.text_at("with") || p.text_at("assert") {
        let save = p.i;
        kw(p, "with").then(|| ()) ;
        if p.i == save { kw(p, "assert"); }
        ws(p);
        if p.cur() == b'{' {
            p.begin("import_attribute", true);
            p.i += 1;
            loop {
                ws(p);
                if p.cur() == b'}' || p.eof() { break }
                let _ = parse_pair_like(p);
                ws(p);
                if !lit(p, ",") { break }
            }
            ws(p);
            let _ = lit(p, "}");
            p.end();
        }
    }
    opt_semicolon(p);
    let _ = have_clause;
    let _ = start;
    Some(p.end_node())
}

fn parse_pair_like(p: &mut P) -> bool {
    p.begin("pair", true);
    let key = if p.cur() == b'"' || p.cur() == b'\'' { string(p) } else { prop_ident(p) };
    if key.is_none() { p.reset_mark(); return false }
    ws(p);
    if p.cur() == b':' {
        let cs = p.i; p.i += 1;
        p.push(p.make_node(":", false, cs, Vec::new()));
