    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        p.begin("import_specifier", true);
        if kw(p, "type") { ws(p) }
        let name = ident(p);
        if name.is_none() { p.reset_mark(); break }
        ws(p);
        if kw(p, "as") {
            ws(p);
            if let Some(a) = ident(p) { f(p, a, "alias"); p.push(a) }
        }
        p.end();
