        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, "}");
    Some(p.end_node())
}

fn export_statement(p: &mut P, start: usize) -> Option<u32> {
    ws(p);
    p.begin("export_statement", true);
    if is_ts(L) && p.text_at("type") {
        let after = p.i + 4;
