    ws(p);
    if p.cur() == b'*' {
        p.i += 1;
        ws(p);
        if kw(p, "as") { ws(p); let _ = ident(p); ws(p) }
        if kw(p, "from") {
            ws(p);
            if let Some(s) = string(p) { f(p, s, "source"); p.push(s) }
        }
        opt_semicolon(p);
        return Some(p.end_node());
    }
    if p.text_at("default") {
        kw(p, "default");
        ws(p);
        let e = expression(p, 0);
        if let Some(e) = e { f(p, e, "value"); }
        opt_semicolon(p);
        return Some(p.end_node());
    }
    if p.cur() == b'{' {
        p.begin("export_clause", true);
        p.i += 1;
        loop {
            ws(p);
            if p.cur() == b'}' || p.eof() { break }
            p.begin("export_specifier", true);
            if kw(p, "type") { ws(p) }
            if ident(p).is_none() { p.reset_mark(); break }
            ws(p);
            if kw(p, "as") {
                ws(p);
                if let Some(a) = ident(p) { f(p, a, "alias"); p.push(a) }
            }
            p.end();
            ws(p);
            if !lit(p, ",") { break }
        }
        ws(p);
        let _ = lit(p, "}");
        p.end();
        ws(p);
        if kw(p, "from") {
            ws(p);
            if let Some(s) = string(p) { f(p, s, "source"); p.push(s) }
        }
        opt_semicolon(p);
        return Some(p.end_node());
    }
    // export <declaration>
    let m = p.mark();
    let decl = declaration(p);
    match decl {
        Some(d) => {
            f(p, d, "declaration");
            opt_semicolon(p);
            Some(p.end_node())
        }
        None => { p.reset(m); None }
    }
}

/// Parse a declaration node (used by `export`).
fn declaration(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    let m = p.mark();
    if kw(p, "const") || kw(p, "let") {
        let k = p.nodes_last_id();
        if let Some(d) = lexical_declaration_from(p, start, k) { return Some(d) }
        p.reset(m);
    } else if kw(p, "var") {
        let k = p.nodes_last_id();
        if let Some(d) = variable_declaration_from(p, start, k) { return Some(d) }
        p.reset(m);
    } else if kw(p, "function") {
        let is_gen = { ws(p); p.cur() == b'*' };
        let gen = if is_gen { p.i += 1; ws(p); true } else { false };
        let _ = ident(p);
        ws(p);
        if formal_parameters(p) {
            ws(p);
            if statement_block(p).is_some() {
                let kind = if gen { "generator_function_declaration" } else { "function_declaration" };
                let kids = p.take_frame_kids();
                let s = p.frame_start();
                p.pop_frame();
                return Some(p.make_node(kind, true, s, kids));
            }
        }
        p.reset(m);
    } else if kw(p, "class") {
        return class_decl(p, start, true);
    } else if is_ts(L) && kw(p, "interface") {
        return interface_declaration(p, start);
    } else if is_ts(L) && kw(p, "type") {
        return type_alias(p, start);
    } else if is_ts(L) && kw(p, "enum") {
        return enum_declaration(p, start);
    }
    None
}

fn lexical_declaration_from(p: &mut P, start: usize, kind_id: u32) -> Option<u32> {
    p.begin("lexical_declaration", true);
    p.push(kind_id);
    f(p, kind_id, "kind");
    loop {
        ws(p);
        if declarator(p).is_none() { break }
        ws(p);
        if !lit(p, ",") { break }
    }
    opt_semicolon(p);
    let _ = start;
    Some(p.end_node())
}

fn variable_declaration_from(p: &mut P, start: usize, kind_id: u32) -> Option<u32> {
    p.begin("variable_declaration", true);
    p.push(kind_id);
    loop {
        ws(p);
        if declarator(p).is_none() { break }
        ws(p);
        if !lit(p, ",") { break }
    }
    opt_semicolon(p);
    let _ = start;
    Some(p.end_node())
}
