// --------------------------------------------------- TS type declarations

fn interface_declaration(p: &mut P, start: usize) -> Option<u32> {
    ws(p);
    p.begin("interface_declaration", true);
    if ident(p).is_none() { p.reset_mark(); return None }
    ws(p);
    if p.cur() == b'<' { let _ = type_params(p); ws(p) }
    if p.cur() == b':' { let _ = type_annotation(p); ws(p) }
    if p.cur() != b'{' { p.reset_mark(); return None }
    p.begin("object_type", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        let ms = p.i;
        if p.cur() == b'[' {
            p.begin("index_signature", true);
            let _ = type_(p);
            ws(p);
            let _ = lit(p, "]");
            ws(p);
            let _ = lit(p, ":");
            ws(p);
            let _ = type_(p);
            p.end();
        } else {
            p.begin("property_signature", true);
            loop {
                ws(p);
                if kw(p, "readonly") || kw(p, "public") || kw(p, "private")
                    || kw(p, "protected") || kw(p, "static") { continue }
                break
            }
            ws(p);
            if p.cur() == b'(' || p.cur() == b'*' {
                p.reset_mark();
                p.begin("method_signature", true);
                if p.cur() == b'*' { p.i += 1 }
                ws(p);
                if p.cur() != b'(' { let _ = prop_ident(p) }
                ws(p);
                let _ = formal_parameters(p);
                ws(p);
                if p.cur() == b':' { let _ = type_annotation(p) }
                p.end();
            } else {
                let _ = prop_ident(p);
                ws(p);
                let _ = lit(p, "?");
                ws(p);
                if p.cur() == b':' { let _ = type_annotation(p) }
                p.end();
            }
        }
        ws(p);
        if !lit(p, ";") { let _ = lit(p, ",") }
        if p.cur() == b'}' { break }
    }
    ws(p);
    let _ = lit(p, "}");
    p.end();
    let _ = start;
    Some(p.end_node())
}

fn type_alias(p: &mut P, start: usize) -> Option<u32> {
    ws(p);
    p.begin("type_alias_declaration", true);
    if ident(p).is_none() { p.reset_mark(); return None }
    ws(p);
    if p.cur() == b'<' { let _ = type_params(p); ws(p) }
    if !lit(p, "=") { p.reset_mark(); return None }
    ws(p);
    if type_(p).is_none() { p.reset_mark(); return None }
    opt_semicolon(p);
    let _ = start;
    Some(p.end_node())
}

fn enum_declaration(p: &mut P, start: usize) -> Option<u32> {
    ws(p);
    p.begin("enum_declaration", true);
    if ident(p).is_none() { p.reset_mark(); return None }
    ws(p);
    if p.cur() != b'{' { p.reset_mark(); return None }
    p.begin("enum_body", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        p.begin("enum_member", true);
        if prop_ident(p).is_none() { p.reset_mark(); break }
        ws(p);
        if p.cur() == b'=' {
            let es = p.i; p.i += 1;
            p.push(p.make_node("=", false, es, Vec::new()));
            ws(p);
            let _ = expression(p, 0);
        }
        p.end();
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, "}");
    p.end();
    let _ = start;
    Some(p.end_node())
}

fn ambient_or_namespace(p: &mut P, start: usize) -> Option<u32> {
    let is_declare = p.nodes[p.nodes_last_id()].kind == "declare";
    let _ = is_declare;
    ws(p);
    if p.text_at("namespace") || p.text_at("module") {
        kw(p, "namespace");
        ws(p);
        p.begin("ambient_declaration", true);
        let _ = ident(p);
        ws(p);
        if p.cur() == b'{' {
            p.begin("statement_block", true);
            p.i += 1;
            loop {
                ws(p);
                if p.cur() == b'}' || p.eof() { break }
                if statement(p).is_none() { error_recovery(p) }
            }
            ws(p);
            let _ = lit(p, "}");
            p.end();
        }
        let _ = start;
        return Some(p.end_node());
    }
    // declare <declaration>
    let d = declaration(p);
    if let Some(d) = d {
        p.begin("ambient_declaration", true);
        p.push(d);
        return Some(p.end_node());
    }
    None
}

// ------------------------------------------------------------------- JSX

fn jsx_element(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'<' { return None }
    // opening tag
    p.begin("jsx_element", true);
    if !jsx_opening_tag(p) { p.reset_mark(); return None }
    // children
    loop {
        ws(p);
        if p.eof() { break }
        if p.text_at("</") {
            if !jsx_closing_tag(p) { break }
            break;
        }
        if p.cur() == b'<' {
            let m = p.mark();
            if jsx_element(p).is_none() { p.reset(m); jsx_text(p); }
            continue;
        }
        if p.cur() == b'{' {
            p.begin("jsx_expression", true);
            p.i += 1;
            ws(p);
            if p.cur() == b'}' {
                let es = p.i; p.i += 1;
                p.push(p.make_node("}", false, es, Vec::new()));
            } else {
                let _ = expression(p, 0);
                ws(p);
                let _ = lit(p, "}");
            }
            p.end();
            continue;
        }
        jsx_text(p);
    }
    Some(p.end_node())
}

fn jsx_text(p: &mut P) {
    let start = p.i;
    while !p.eof() && p.cur() != b'<' && p.cur() != b'{' { p.i += 1 }
    if p.i > start {
        p.push(p.make_node("jsx_text", true, start, Vec::new()));
    }
}

fn jsx_name(p: &mut P) -> Option<u32> {
    let start = p.i;
    if ident(p).is_none() { return None }
    loop {
        if p.cur() == b'.' {
            p.i += 1;
            if ident(p).is_none() { break }
        } else if p.cur() == b':' {
            p.i += 1;
            if ident(p).is_none() { break }
        } else {
            break
        }
    }
    Some(p.make_node("jsx_element", true, start, Vec::new()))
}

fn jsx_opening_tag(p: &mut P) -> bool {
    let start = p.i;
    p.i += 1;
    ws(p);
    let name_start = p.i;
    if ident(p).is_none() { p.reset_to_pos(start); return false }
    loop {
        if p.cur() == b'.' || p.cur() == b':' {
            p.i += 1;
            if ident(p).is_none() { break }
        } else { break }
    }
    let _ = name_start;
    ws(p);
    // attributes
    loop {
        ws(p);
        if p.cur() == b'>' || p.cur() == b'/' || p.eof() { break }
        let as_ = p.i;
        if p.cur() == b'{' {
            p.begin("jsx_expression", true);
            p.i += 1;
            ws(p);
            let _ = expression(p, 0);
            ws(p);
            let _ = lit(p, "}");
            p.end();
            continue;
        }
        p.begin("jsx_attribute", true);
        if jsx_attribute_name(p).is_none() { p.reset_mark(); p.reset_to_pos(as_); break }
        ws(p);
        if p.cur() == b'=' {
            let es = p.i; p.i += 1;
            p.push(p.make_node("=", false, es, Vec::new()));
            ws(p);
            if p.cur() == b'"' || p.cur() == b'\'' {
                p.begin("jsx_attribute_value", true);
                let qs = p.i;
                let q = p.cur();
                p.i += 1;
                p.push(p.make_node(if q == b'"' { "\"" } else { "'" }, false, qs, Vec::new()));
                let ts = p.i;
                while !p.eof() && p.cur() != q { p.i += 1 }
                if p.i > ts { p.push(p.make_node("jsx_text", true, ts, Vec::new())) }
                if p.cur() == q {
                    let qe = p.i; p.i += 1;
                    p.push(p.make_node(if q == b'"' { "\"" } else { "'" }, false, qe, Vec::new()));
                }
                p.end();
            } else if p.cur() == b'{' {
                p.begin("jsx_expression", true);
                p.i += 1;
                ws(p);
                let _ = expression(p, 0);
                ws(p);
                let _ = lit(p, "}");
                p.end();
            } else {
                let _ = expression(p, 0);
            }
        }
        p.end();
    }
    ws(p);
    if p.text_at("/>") {
        // self closing: rebuild
        let kids = p.take_frame_kids();
        let s = p.frame_start();
        p.pop_frame();
        p.i += 2;
        let id = p.make_node("jsx_self_closing_element", true, start, kids);
        p.push(id);
        return true;
    }
    if !lit(p, ">") { p.reset_to_pos(start); return false }
    true
}

fn jsx_closing_tag(p: &mut P) -> bool {
    let start = p.i;
    p.i += 2;
    ws(p);
    if ident(p).is_none() { p.reset_to_pos(start); return false }
    loop {
        if p.cur() == b'.' || p.cur() == b':' { p.i += 1; if ident(p).is_none() { break } } else { break }
    }
    ws(p);
    if !lit(p, ">") { p.reset_to_pos(start); return false }
    true
}

fn jsx_attribute_name(p: &mut P) -> Option<u32> {
    if kw(p, "style") || kw(p, "class") || kw(p, "className") || kw(p, "id") || kw(p, "href") {
        return Some(p.nodes_last_id());
    }
    if ident(p).is_none() { return None }
    loop {
        if p.cur() == b'-' {
            p.i += 1;
            if ident(p).is_none() { break }
        } else { break }
    }
    Some(p.nodes_last_id())
}

// ------------------------------------------------------------------ program

pub fn parse_program(p: &mut P) {
    p.begin("program", true);
    loop {
        ws(p);
        if p.eof() { break }
        if p.text_at("#!") {
            p.begin("hash_bang_line", true);
            while !p.eof() && p.cur() != b'\n' { p.i += 1 }
            p.end();
            continue;
        }
        if statement(p).is_none() {
            error_recovery(p);
        }
    }
    p.end();
}
