//! A generic brace/indent based parser used for languages without a dedicated
//! implementation. It produces plausible node kinds so that pattern search
//! still works structurally.

use crate::lang::Lang;
use crate::parser::{Mark, P};

pub fn parse_program(p: &mut P, lang: Lang) {
    p.begin("program", true);
    loop {
        p.ws(lang);
        if p.eof() { break }
        let start = p.i;
        let m = p.mark();
        if !parse_item(p, lang) {
            p.reset(m);
            p.i = start + 1;
            p.push(p.make_node("ERROR", true, start, Vec::new()));
        }
    }
    p.end();
}

fn parse_item(p: &mut P, lang: Lang) -> bool {
    p.ws(lang);
    let start = p.i;
    match p.cur() {
        b'{' => { parse_block(p, lang); true }
        b'(' | b'[' => { parse_balanced(p, lang); true }
        _ => {
            // consume a "line" of tokens, wrapping in an expression_statement
            let mut any = false;
            while !p.eof() {
                let c = p.cur();
                if c == b'\n' || c == b';' || c == b'{' || c == b'}' { break }
                p.i += 1;
                any = true;
            }
            if !any { return false }
            p.push(p.make_node("ERROR", true, start, Vec::new()));
            true
        }
    }
}

fn parse_block(p: &mut P, lang: Lang) {
    let start = p.i;
    p.i += 1;
    loop {
        p.ws(lang);
        if p.eof() || p.cur() == b'}' { break }
        let m = p.mark();
        if !parse_item(p, lang) {
            p.reset(m);
            break;
        }
    }
    if !p.eof() && p.cur() == b'}' { p.i += 1 }
    p.push(p.make_node("ERROR", true, start, Vec::new()));
}

fn parse_balanced(p: &mut P, lang: Lang) {
    let open = p.cur();
    let close = if open == b'(' { b')' } else { b']' };
    let start = p.i;
    p.i += 1;
    let mut depth = 1;
    while !p.eof() && depth > 0 {
        let c = p.cur();
        if c == open { depth += 1 }
        if c == close { depth -= 1 }
        p.i += 1;
        let _ = lang;
    }
    p.push(p.make_node("ERROR", true, start, Vec::new()));
}
