//! Line / column index helpers shared by all printers.

#[derive(Clone)]
pub struct Lines {
    /// byte offset of the start of each line
    pub starts: Vec<usize>,
    pub len: usize,
}

impl Lines {
    pub fn new(src: &str) -> Lines {
        let mut starts = vec![0usize];
        for (i, b) in src.bytes().enumerate() {
            if b == b'\n' {
                starts.push(i + 1);
            }
        }
        Lines { starts, len: src.len() }
    }

    pub fn line_count(&self) -> usize { self.starts.len() }

    /// 0-based line index containing byte offset `pos`.
    pub fn line_of(&self, pos: usize) -> usize {
        match self.starts.binary_search(&pos) {
            Ok(i) => i,
            Err(i) => i - 1,
        }
    }

    pub fn line_start(&self, line: usize) -> usize {
        if line >= self.starts.len() { self.len } else { self.starts[line] }
    }

    pub fn line_end(&self, line: usize) -> usize {
        if line + 1 >= self.starts.len() { self.len } else { self.starts[line + 1] - 1 }
    }

    /// (line, column) of a byte offset, both 0-based; column counts bytes.
    pub fn point(&self, pos: usize) -> (usize, usize) {
        let line = self.line_of(pos);
        (line, pos - self.starts[line])
    }
}
