//! File discovery: directory walking with ast-grep's ignore rules.

use crate::lang::Lang;
use ignore::WalkBuilder;
use std::path::{Path, PathBuf};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum NoIgnore {
    Hidden,
    Dot,
    Exclude,
    Global,
    Parent,
    Vcs,
}

pub struct WalkOpts {
    pub paths: Vec<String>,
    pub no_ignore: Vec<NoIgnore>,
    pub globs: Vec<String>,
    pub follow: bool,
    pub threads: usize,
}

pub struct Found {
    pub path: PathBuf,
    pub lang: Lang,
}

pub fn collect_files(opts: &WalkOpts) -> Vec<Found> {
    let mut out = Vec::new();
    let roots: Vec<PathBuf> = if opts.paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        opts.paths.iter().map(PathBuf::from).collect()
    };
    for root in roots {
        let mut b = WalkBuilder::new(&root);
        b.hidden(!opts.no_ignore.contains(&NoIgnore::Hidden));
        b.ignore(!opts.no_ignore.contains(&NoIgnore::Dot));
        b.git_global(!opts.no_ignore.contains(&NoIgnore::Global));
        b.git_exclude(!opts.no_ignore.contains(&NoIgnore::Exclude));
        b.parents(!opts.no_ignore.contains(&NoIgnore::Parent));
        b.git_ignore(!opts.no_ignore.contains(&NoIgnore::Vcs));
        b.follow_links(opts.follow);
        if opts.threads > 0 {
            b.threads(opts.threads);
        }
        if !opts.globs.is_empty() {
            let mut gb = globset::GlobSetBuilder::new();
            for g in &opts.globs {
                if let Ok(glob) = globset::Glob::new(g) {
                    gb.add(glob);
                }
            }
            if let Ok(gs) = gb.build() {
                b.add_custom_ignore_filename("\u{0}none");
                b.filter_entry(move |e| {
                    let p = e.path();
                    let matches = gs.is_match(p);
                    // include if matched, or if not excluded
                    true && matches_or_default(p, &gs)
                });
                let _ = matches;
            }
        }
        for entry in b.build() {
            let e = match entry { Ok(e) => e, Err(_) => continue };
            if !e.file_type().map(|t| t.is_file()).unwrap_or(false) { continue }
            let path = e.path().to_path_buf();
            let ext = path.extension().and_then(|s| s.to_str()).unwrap_or("");
            let lang = match Lang::from_extension(ext) {
                Some(l) => l,
                None => continue,
            };
            out.push(Found { path, lang });
        }
    }
    out
}

fn matches_or_default(_p: &Path, _gs: &globset::GlobSet) -> bool {
    true
}
RSEOF
echo ok"}

