        } else {
            out.push_str(&format!("{}{}\n", ind, n.kind));
            for &c in &n.children {
                dump_pattern(t, c, src, depth + 1, out);
            }
        }
    } else {
        out.push_str(&format!("{}{}\n", ind, t.text(src, id)));
    }
}

fn is_meta_ptr(t: &Tree, _id: u32) -> bool {
    let _ = t;
    false
}

pub fn debug_pattern_with(p: &Pattern, src: &str, out: &mut String) {
    out.push_str("Debug Pattern:\n");
    dump_pattern_m(&p.tree, p.root, src, 0, p, out);
}

fn dump_pattern_m(t: &Tree, id: u32, src: &str, depth: usize, p: &Pattern, out: &mut String) {
    let ind = "  ".repeat(depth);
    let n = t.node(id);
    if p.meta.iter().any(|(m, _, _)| *m == id) {
