}

fn dump_tree(
    t: &Tree,
    id: u32,
    src: &str,
    lines: &Lines,
    depth: usize,
    cst: bool,
    out: &mut String,
) {
    let ind = "  ".repeat(depth);
    let n = t.node(id);
    if !cst && !n.named {
        return;
    }
    let (sl, sc) = lines.point(n.start);
    let (el, ec) = lines.point(n.end);
