// ------------------------------------------------------------ search text

pub struct PrintOpts {
    pub color: bool,
    pub heading: bool,
    pub before: usize,
    pub after: usize,
}

pub fn print_text(
    path: &str,
    src: &str,
    lines: &Lines,
    hits: &[Hit],
    tree: &Tree,
    opts: &PrintOpts,
    out: &mut String,
) {
    if hits.is_empty() {
        return;
    }
    let mut printed_any = false;
    let groups = group_hits(hits, lines, opts.before, opts.after);
    for (gi, (lo, hi)) in groups.iter().enumerate() {
        if printed_any && opts.heading {
            out.push('\n');
        }
        let mut last = None;
        let mut i = 0usize;
        let _ = i;
        let mut idx = 0usize;
        for &h in hits {
            let _ = h;
        }
        let _ = idx;
        // iterate over the lines of this group, highlighting matched ranges
        let mut ranges: Vec<(usize, usize)> = hits
            .iter()
            .filter(|h| {
                let (s, e) = (lines.line_of(h.start), lines.line_of(h.end.saturating_sub(1)));
                s >= *lo && e <= *hi || (h.start >= lines.line_start(*lo) && h.start < lines.line_end(*hi) + 1)
            })
            .map(|h| (h.start, h.end))
            .collect();
        ranges.sort();
        let mut cur = lines.line_start(*lo);
        while cur <= lines.line_end(*hi) && cur <= lines.len {
            let line = lines.line_of(cur);
            if let Some(prev) = last {
                if line > prev + 1 {
                    out.push_str("--\n");
                }
            }
            let le = lines.line_end(line);
            let text = &src[cur..=le.min(src.len().saturating_sub(1)).max(cur)];
            let text = if le >= src.len() { &src[cur..] } else { &src[cur..=le] };
            let _ = text;
            if opts.heading {
                if opts.color {
                    out.push_str(&format!("{}{}{}│", ANSI_DIM, line + 1, ANSI_RESET));
                } else {
                    out.push_str(&format!("{}│", line + 1));
                }
            } else if opts.color {
                out.push_str(&format!("{}:{}:", path, line + 1));
            } else {
                out.push_str(&format!("{}:{}:", path, line + 1));
            }
            emit_line(src, cur, le, &ranges, opts.color, out);
            out.push('\n');
            last = Some(line);
            if le >= src.len() { break }
            cur = le + 1;
            if cur < lines.len && src.as_bytes()[cur] == b'\n' { cur += 1 }
            let _ = printed_any;
        }
        printed_any = true;
        let _ = gi;
    }
    let _ = tree;
}

fn emit_line(src: &str, start: usize, end: usize, ranges: &[(usize, usize)], color: bool, out: &mut String) {
    let line_text = if end >= src.len() { &src[start..] } else { &src[start..=end] };
    let mut pos = start;
    let mut chars = line_text.char_indices();
    let _ = &mut chars;
    let mut idx = start;
    while idx <= end && idx < src.len() {
        let mut hit_here = false;
        for &(rs, re) in ranges {
            if idx >= rs && idx < re {
                hit_here = true;
                break;
            }
        }
        if hit_here {
            let mut stop = idx;
            while stop <= end && stop < src.len() {
                let mut inside = false;
                for &(rs, re) in ranges {
                    if stop >= rs && stop < re { inside = true; break }
                }
                if !inside { break }
                stop += 1;
            }
            let _ = pos;
            let text = &src[idx..stop];
            if color {
                out.push_str(ANSI_BOLD_RED);
                out.push_str(text);
                out.push_str(ANSI_RESET);
            } else {
                out.push_str(text);
            }
            idx = stop;
        } else {
            let b = src.as_bytes()[idx];
            let l = utf8_len(b);
            let stop = (idx + l).min(src.len());
            out.push_str(&src[idx..stop]);
            idx = stop;
        }
    }
    let _ = pos;
}

fn utf8_len(b: u8) -> usize {
    if b < 0x80 { 1 } else if b >> 5 == 0b110 { 2 } else if b >> 4 == 0b1110 { 3 } else if b >> 3 == 0b11110 { 4 } else { 1 }
}

/// Group hits into (start_line, end_line) context blocks.
pub fn group_hits(hits: &[Hit], lines: &Lines, before: usize, after: usize) -> Vec<(usize, usize)> {
    let n = lines.line_count();
    let mut out: Vec<(usize, usize)> = Vec::new();
    if hits.is_empty() { return out }
    let mut blocks: Vec<(usize, usize)> = hits
        .iter()
        .map(|h| {
            let s = lines.line_of(h.start);
            let e = lines.line_of(h.end.saturating_sub(1));
            (s.saturating_sub(before), (e + after).min(n.saturating_sub(1)))
        })
        .collect();
    let mut cur_start = blocks[0].0;
    let mut cur_end = blocks[0].1;
    for &(bs, be) in blocks.iter().skip(1) {
        if be <= cur_end + before + after + 1 {
            cur_end = cur_end.max(be);
        } else {
            out.push((cur_start, cur_end));
            cur_start = bs;
            cur_end = be;
        }
    }
    out.push((cur_start, cur_end));
    out
}

// ------------------------------------------------------------------- JSON

pub fn hit_json(
    path: &str,
    src: &str,
    lines: &Lines,
    tree: &Tree,
    lang: Lang,
    hit: &Hit,
    p: &Pattern,
    include_meta: bool,
    meta: Option<&serde_json::Value>,
) -> serde_json::Value {
    let (sl, sc) = lines.point(hit.start);
    let (el, ec) = lines.point(hit.end);
    let (b, a) = (0usize, 0usize);
    let _ = (b, a);
    let region = context_lines(src, lines, hit, 0, 0);
    let leading = hit.start - region.0;
    let trailing = region.1 - hit.end;
    let mut single = serde_json::Map::new();
    for (name, id) in &hit.vars.single {
        if name.starts_with('_') { continue }
        let n = tree.node(*id);
        let (s1, c1) = lines.point(n.start);
        let (e1, c2) = lines.point(n.end);
        single.insert(
            name.clone(),
            serde_json::json!({
                "text": tree.text(src, *id),
                "range": {
                    "byteOffset": {"start": n.start, "end": n.end},
                    "start": {"line": s1, "column": c1},
                    "end": {"line": e1, "column": c2},
                }
            }),
        );
    }
    let mut multi = serde_json::Map::new();
    for (name, ids) in &hit.vars.multi {
        if name.starts_with('_') { continue }
        let arr: Vec<serde_json::Value> = ids
            .iter()
            .map(|&id| {
                let n = tree.node(id);
                let (s1, c1) = lines.point(n.start);
                let (e1, c2) = lines.point(n.end);
                serde_json::json!({
                    "text": tree.text(src, id),
                    "range": {
                        "byteOffset": {"start": n.start, "end": n.end},
                        "start": {"line": s1, "column": c1},
                        "end": {"line": e1, "column": c2},
                    }
                })
            })
            .collect();
        multi.insert(name.clone(), serde_json::Value::Array(arr));
    }
    let mut obj = serde_json::Map::new();
    obj.insert("text".into(), serde_json::Value::String(tree.text(src, hit.node).to_string()));
    obj.insert(
        "range".into(),
        serde_json::json!({
            "byteOffset": {"start": hit.start, "end": hit.end},
            "start": {"line": sl, "column": sc},
            "end": {"line": el, "column": ec},
        }),
    );
    obj.insert("file".into(), serde_json::Value::String(path.to_string()));
    obj.insert("lines".into(), serde_json::Value::String(src[region.0..region.1].to_string()));
    obj.insert(
        "charCount".into(),
        serde_json::json!({"leading": leading, "trailing": trailing}),
    );
    obj.insert("language".into(), serde_json::Value::String(lang.name().to_string()));
    let _ = p;
    let _ = include_meta;
    let mut mv = serde_json::Map::new();
    mv.insert("single".into(), serde_json::Value::Object(single));
    mv.insert("multi".into(), serde_json::Value::Object(multi));
    mv.insert("transformed".into(), serde_json::json!({}));
    obj.insert("metaVariables".into(), serde_json::Value::Object(mv));
    if include_meta {
        if let Some(m) = meta {
            obj.insert("metaVariables".into(), serde_json::Value::Object(mv));
            obj.insert("ruleId".into(), m.clone());
        }
    }
    serde_json::Value::Object(obj)
}

pub fn context_lines(src: &str, lines: &Lines, hit: &Hit, before: usize, after: usize) -> (usize, usize) {
    let s = lines.line_of(hit.start);
    let e = lines.line_of(hit.end.saturating_sub(1));
    let lo = s.saturating_sub(before);
    let hi = (e + after).min(lines.line_count().saturating_sub(1));
    let start = lines.line_start(lo);
    let end = if hi + 1 >= lines.line_count() { lines.len } else { lines.line_start(hi + 1) };
    (start.min(end), end.max(start))
}

pub const NONE_: u32 = NONE;
RSEOF
echo ok"}

