fn dump_pattern(t: &Tree, id: u32, src: &str, depth: usize, out: &mut String) {
    let ind = "  ".repeat(depth);
    let n = t.node(id);
    if is_meta_ptr(t, id) {
        out.push_str(&format!("{}MetaVar {}\n", ind, t.text(src, id)));
