}

pub fn hit_json(
    path: &str,
    src: &str,
    lines: &Lines,
    tree: &Tree,
    lang: Lang,
    hit: &Hit,
    before: usize,
    after: usize,
) -> serde_json::Value {
    let (sl, sc) = lines.point(hit.start);
    let (el, ec) = lines.point(hit.end);
    let (rs, re) = context_region(src, lines, hit.start, hit.end, before, after);
    let region_text = &src[rs..re];
    let leading = hit.start - rs;
    let trailing = re - hit.end;
    let mut single = serde_json::Map::new();
    for (name, id) in &hit.vars.single {
        if name.starts_with('_') { continue }
        let n = tree.node(*id);
        single.insert(
            name.clone(),
            serde_json::json!({
                "text": tree.text(src, *id),
                "range": jrange(n.start, n.end, lines),
            }),
        );
    }
    let mut multi = serde_json::Map::new();
    for (name, ids) in &hit.vars.multi {
