            name.clone(),
            serde_json::json!({
                "text": tree.text(src, *id),
                "range": jrange(n.start, n.end, lines),
            }),
        );
    }
    let mut multi = serde_json::Map::new();
    for (name, ids) in &hit.vars.multi {
        if name.starts_with('_') { continue }
        let arr: Vec<serde_json::Value> = ids
            .iter()
            .map(|&id| {
                let n = tree.node(id);
                serde_json::json!({
                    "text": tree.text(src, id),
                    "range": jrange(n.start, n.end, lines),
                })
            })
            .collect();
        multi.insert(name.clone(), serde_json::Value::Array(arr));
    }
    let obj = serde_json::json!({
        "text": tree.text(src, hit.node),
        "range": jrange(hit.start, hit.end, lines),
        "file": path,
        "lines": region_text,
        "charCount": {"leading": leading as u64, "trailing": trailing as u64},
        "language": lang.name(),
        "metaVariables": {
            "single": serde_json::Value::Object(single),
            "multi": serde_json::Value::Object(multi),
            "transformed": {},
        },
    });
    let _ = (sl, sc, el, ec);
    obj
}

// ------------------------------------------------------------ search text

pub struct PrintOpts {
    pub color: bool,
    pub heading: bool,
}

pub fn print_text(
    path: &str,
    src: &str,
    lines: &Lines,
    hits: &[Hit],
    opts: &PrintOpts,
    before: usize,
    after: usize,
    out: &mut String,
) {
    if hits.is_empty() { return }
    let groups = group_hits(hits, lines, before, after);
    if opts.heading {
        if opts.color {
            out.push_str(&format!("{}{}{}\n", ANSI_ITALIC_CYAN, path, ANSI_RESET));
        } else {
            out.push_str(path);
            out.push('\n');
        }
    }
    let mut first = true;
    for (lo, hi) in groups {
        if opts.heading && !first {
            out.push('\n');
        }
        first = false;
        let mut last: Option<usize> = None;
        let mut line = lo;
        loop {
            if line > hi || line >= lines.line_count() { break }
            if let Some(prev) = last {
                if line > prev + 1 {
                    out.push_str("--\n");
                }
            }
            if opts.heading {
                if opts.color {
                    out.push_str(&format!("{}{}{}│", ANSI_DIM, line + 1, ANSI_RESET));
                } else {
                    out.push_str(&format!("{}│", line + 1));
                }
            } else {
                out.push_str(&format!("{}:{}:", path, line + 1));
            }
            let ls = lines.line_start(line);
            let le = lines.line_end(line);
            emit_line(src, ls, le, hits, opts.color, out);
            out.push('\n');
            last = Some(line);
            if le >= lines.len { break }
            line += 1;
        }
    }
    if opts.heading {
        out.push('\n');
    }
}

fn emit_line(src: &str, start: usize, end: usize, hits: &[Hit], color: bool, out: &mut String) {
    let stop = if end >= src.len() { src.len() } else { end + 1 };
    let text = &src[start..stop];
    let ranges: Vec<(usize, usize)> = hits.iter().map(|h| (h.start, h.end)).collect();
    let mut idx = start;
    while idx < stop && idx < src.len() {
        let mut hit_end = None;
        for &(rs, re) in &ranges {
            if idx >= rs && idx < re {
                hit_end = Some(re.min(stop));
                break;
            }
        }
        match hit_end {
            Some(re) => {
                if color {
                    out.push_str(ANSI_BOLD_RED);
                    out.push_str(&src[idx..re]);
                    out.push_str(ANSI_RESET);
                } else {
                    out.push_str(&src[idx..re]);
                }
                idx = re;
            }
            None => {
                let b = src.as_bytes()[idx];
                let l = utf8_len(b);
                let nxt = (idx + l).min(stop);
                out.push_str(&src[idx..nxt]);
                idx = nxt;
            }
        }
    }
    let _ = text;
}

fn utf8_len(b: u8) -> usize {
    if b < 0x80 { 1 }
    else if b >> 5 == 0b110 { 2 }
    else if b >> 4 == 0b1110 { 3 }
    else if b >> 3 == 0b11110 { 4 }
    else { 1 }
}

/// Group hits into (start_line, end_line) context blocks, matching ast-grep's
/// merge behaviour.
pub fn group_hits(hits: &[Hit], lines: &Lines, before: usize, after: usize) -> Vec<(usize, usize)> {
    let n = lines.line_count();
    let mut out: Vec<(usize, usize)> = Vec::new();
    if hits.is_empty() { return out }
    let blocks: Vec<(usize, usize)> = hits
        .iter()
        .map(|h| {
            let s = lines.line_of(h.start);
            let e = lines.line_of(h.end.saturating_sub(1));
            (s.saturating_sub(before), (e + after).min(n.saturating_sub(1)))
        })
        .collect();
    let mut cur_start = blocks[0].0;
    let mut cur_end = blocks[0].1;
    for &(bs, be) in blocks.iter().skip(1) {
        if be <= cur_end + before + after + 1 {
            cur_end = cur_end.max(be);
        } else {
            out.push((cur_start, cur_end));
            cur_start = bs;
            cur_end = be;
        }
    }
    out.push((cur_start, cur_end));
    out
}

// ------------------------------------------------------------------- diff

pub struct DiffLine {
    pub old: Option<usize>,
    pub new: Option<usize>,
    pub marker: char,
    pub text: String,
}

/// Produce the unified diff body for one hunk.
pub fn diff_hunk(
    old_lines: &[&str],
    new_lines: &[&str],
    start: usize,
    out: &mut String,
) {
    let max_line = (start + old_lines.len().max(new_lines.len())).max(1);
    let w = max_line.to_string().len();
    out.push_str(&format!("@@ -{},{} +{},{} @@\n", start, old_lines.len(), start, new_lines.len()));
    let n = old_lines.len().max(new_lines.len());
    for i in 0..n {
        let o = old_lines.get(i).copied();
        let nw = new_lines.get(i).copied();
        match (o, nw) {
            (Some(o), Some(nw)) if o == nw => {
                let os = (start + i + 1).to_string();
                let ns = (start + i + 1).to_string();
                out.push_str(&format!("{:<w$} {:<w$}│ {}\n", os, ns, o, w = w));
            }
            (Some(o), Some(nw)) => {
                let os = (start + i + 1).to_string();
                let ns = (start + i + 1).to_string();
                out.push_str(&format!("{:<w$} {:<w$}│-{}\n", os, "", o, w = w));
                out.push_str(&format!("{:<w$} {:<w$}│+{}\n", "", ns, nw, w = w));
            }
            (Some(o), None) => {
                let os = (start + i + 1).to_string();
                out.push_str(&format!("{:<w$} {:<w$}│-{}\n", os, "", o, w = w));
            }
            (None, Some(nw)) => {
                let ns = (start + i + 1).to_string();
                out.push_str(&format!("{:<w$} {:<w$}│+{}\n", "", ns, nw, w = w));
            }
            (None, None) => {}
        }
    }
}

/// Apply rewrites to the source, returning the new text.
pub fn apply_rewrites(src: &str, edits: &[(usize, usize, String)]) -> String {
    let mut sorted: Vec<&(usize, usize, String)> = edits.iter().collect();
    sorted.sort_by_key(|e| e.0);
    let mut out = String::new();
    let mut pos = 0usize;
    for (s, e, r) in sorted {
        if s < pos { continue }
        out.push_str(&src[pos..*s]);
        out.push_str(r);
        pos = *e;
    }
    out.push_str(&src[pos..]);
    out
}
