pub enum JsonStyle { Pretty, Stream, Compact }

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Inspect { Nothing, Summary, Entity }

impl Inspect {
    pub fn from_str(s: &str) -> Option<Inspect> {
        Some(match s {
            "nothing" => Inspect::Nothing,
