// ---------------------------------------------------------- debug queries

pub fn debug_pattern(p: &Pattern, src: &str, out: &mut String) {
    out.push_str("Debug Pattern:\n");
    dump_pattern(&p.tree, p.root, src, 0, p, out);
}

fn dump_pattern(t: &Tree, id: u32, src: &str, depth: usize, p: &Pattern, out: &mut String) {
    let ind = "  ".repeat(depth);
    let n = t.node(id);
    if p.meta.iter().any(|(m, _, _)| *m == id) {
        out.push_str(&format!("{}MetaVar {}\n", ind, t.text(src, id)));
        return;
    }
    if n.named {
        if n.children.is_empty() {
            out.push_str(&format!("{}{} {}\n", ind, n.kind, t.text(src, id)));
        } else {
            out.push_str(&format!("{}{}\n", ind, n.kind));
            for &c in &n.children {
                dump_pattern(t, c, src, depth + 1, p, out);
            }
        }
    } else {
        out.push_str(&format!("{}{}\n", ind, t.text(src, id)));
    }
}

pub fn debug_tree(t: &Tree, src: &str, lines: &Lines, cst: bool, out: &mut String) {
    dump_tree(t, t.root, src, lines, 0, cst, out);
}

fn dump_tree(t: &Tree, id: u32, src: &str, lines: &Lines, depth: usize, cst: bool, out: &mut String) {
    let ind = "  ".repeat(depth);
    let n = t.node(id);
    if !cst && !n.named {
        return;
    }
    let (sl, sc) = lines.point(n.start);
    let (el, ec) = lines.point(n.end);
    let field = match n.field {
        Some(f) => format!("{}: ", crate::tree::field_name(f)),
        None => String::new(),
    };
    out.push_str(&format!("{}{}{} ({},{})-({},{})\n", ind, field, n.kind, sl, sc, el, ec));
    for &c in &n.children {
        dump_tree(t, c, src, lines, depth + 1, cst, out);
    }
}

pub fn debug_sexp(t: &Tree, src: &str, out: &mut String) {
    out.push_str(&sexp_node(t, t.root, src));
    out.push('\n');
}

fn sexp_node(t: &Tree, id: u32, src: &str) -> String {
    let n = t.node(id);
    if !n.named {
        return String::new();
    }
    let field = match n.field {
        Some(f) => format!("{}: ", crate::tree::field_name(f)),
        None => String::new(),
    };
    let mut s = format!("{}({}", field, n.kind);
    for &c in &n.children {
        let cs = sexp_node(t, c, src);
        if !cs.is_empty() {
            s.push(' ');
            s.push_str(&cs);
        }
    }
    s.push(')');
    s
}

// ------------------------------------------------------------- JSON value

fn jstr(s: &str) -> serde_json::Value { serde_json::Value::String(s.to_string()) }
fn jnum(n: usize) -> serde_json::Value { serde_json::Value::Number((n as u64).into()) }
fn jrange(start: usize, end: usize, lines: &Lines) -> serde_json::Value {
    let (sl, sc) = lines.point(start);
    let (el, ec) = lines.point(end);
    serde_json::json!({
        "byteOffset": {"start": start as u64, "end": end as u64},
        "start": {"line": sl as u64, "column": sc as u64},
        "end": {"line": el as u64, "column": ec as u64},
    })
}

pub fn context_region(src: &str, lines: &Lines, start: usize, end: usize, before: usize, after: usize) -> (usize, usize) {
    let s = lines.line_of(start);
    let e = lines.line_of(end.saturating_sub(1));
    let lo = s.saturating_sub(before);
    let hi = (e + after).min(lines.line_count().saturating_sub(1));
    let st = lines.line_start(lo);
    let en = if hi + 1 >= lines.line_count() { lines.len } else { lines.line_start(hi + 1) };
    (st.min(en), en.max(st))
}

pub fn hit_json(
    path: &str,
    src: &str,
    lines: &Lines,
    tree: &Tree,
    lang: Lang,
    hit: &Hit,
    before: usize,
    after: usize,
) -> serde_json::Value {
    let (sl, sc) = lines.point(hit.start);
    let (el, ec) = lines.point(hit.end);
    let (rs, re) = context_region(src, lines, hit.start, hit.end, before, after);
    let region_text = &src[rs..re];
    let leading = hit.start - rs;
    let trailing = re - hit.end;
    let mut single = serde_json::Map::new();
    for (name, id) in &hit.vars.single {
        if name.starts_with('_') { continue }
        let n = tree.node(*id);
        single.insert(
            name.clone(),
            serde_json::json!({
                "text": tree.text(src, *id),
                "range": jrange(n.start, n.end, lines),
            }),
        );
    }
    let mut multi = serde_json::Map::new();
    for (name, ids) in &hit.vars.multi {
        if name.starts_with('_') { continue }
        let arr: Vec<serde_json::Value> = ids
            .iter()
            .map(|&id| {
                let n = tree.node(id);
                serde_json::json!({
                    "text": tree.text(src, id),
                    "range": jrange(n.start, n.end, lines),
                })
            })
            .collect();
        multi.insert(name.clone(), serde_json::Value::Array(arr));
    }
    let obj = serde_json::json!({
        "text": tree.text(src, hit.node),
        "range": jrange(hit.start, hit.end, lines),
        "file": path,
        "lines": region_text,
        "charCount": {"leading": leading as u64, "trailing": trailing as u64},
        "language": lang.name(),
        "metaVariables": {
            "single": serde_json::Value::Object(single),
            "multi": serde_json::Value::Object(multi),
            "transformed": {},
        },
    });
    let _ = (sl, sc, el, ec);
    obj
}

// ------------------------------------------------------------ search text

pub struct PrintOpts {
    pub color: bool,
    pub heading: bool,
}

pub fn print_text(
    path: &str,
    src: &str,
    lines: &Lines,
    hits: &[Hit],
    opts: &PrintOpts,
    before: usize,
    after: usize,
    out: &mut String,
) {
    if hits.is_empty() { return }
    let groups = group_hits(hits, lines, before, after);
    if opts.heading {
        if opts.color {
            out.push_str(&format!("{}{}{}\n", ANSI_ITALIC_CYAN, path, ANSI_RESET));
        } else {
            out.push_str(path);
            out.push('\n');
        }
    }
    let mut first = true;
    for (lo, hi) in groups {
        if opts.heading && !first {
            out.push('\n');
        }
        first = false;
        let mut last: Option<usize> = None;
        let mut line = lo;
        loop {
            if line > hi || line >= lines.line_count() { break }
            if let Some(prev) = last {
                if line > prev + 1 {
                    out.push_str("--\n");
                }
            }
            if opts.heading {
                if opts.color {
                    out.push_str(&format!("{}{}{}│", ANSI_DIM, line + 1, ANSI_RESET));
