    let opts = PatternOpts { selector, strictness: strict };
    let pat = match build_pattern(lang.unwrap_or(Lang::JavaScript), &args.pattern, &opts) {
        Ok(p) => p,
        Err(e) => {
            crate::main_error(&e);
            return 8;
        }
    };
    if let Some(fmt) = &args.debug_query {
        print_debug(&pat, &args.pattern, fmt, args.before, args.after);
    }
    if pat.root_is_error {
        eprintln!("Warning: Pattern contains an ERROR node and may cause unexpected results.");
    }

    let mut inspected = 0usize;
    let mut skipped = 0usize;
    let mut total_hits: Vec<(String, Vec<Hit>, Lang, Tree, String)> = Vec::new();

