    }
    eprint!("{}", out);
}

/// Find all matches of the pattern in a source text.
pub fn scan_text(
    src: &str,
    lang: Lang,
    pat: &crate::pattern::Pattern,
    _rewrite: &Option<String>,
    _orig: &str,
) -> Vec<Hit> {
    let tree = crate::parser::parse(lang, src);
    let mut hits = Vec::new();
    let m = Matcher { pt: pat, st: &tree, src, strictness: pat.strictness };
    collect_hits(&tree, tree.root, &m, &mut hits);
    hits
}

fn collect_hits(tree: &Tree, node: u32, m: &Matcher, out: &mut Vec<Hit>) {
    let mut vars = crate::matcher::MetaVars::default();
    if m.match_node(m.pt.root, node, &mut vars) {
        let n = tree.node(node);
        out.push(Hit { node, start: n.start, end: n.end, vars });
        return;
    }
    for &c in &tree.node(node).children.clone() {
        collect_hits(tree, c, m, out);
    }
}

pub fn rewrite_edits(src: &str, tree: &Tree, hits: &[Hit], fix: &str) -> Vec<(usize, usize, String)> {
    let _ = tree;
    let mut out = Vec::new();
    for h in hits {
        let text = render_fix(fix, h, src);
        out.push((h.start, h.end, text));
    }
    let _ = src;
    out
}

/// Substitute meta variables into a rewrite template.
pub fn render_fix(fix: &str, h: &Hit, src: &str) -> String {
    let bytes = fix.as_bytes();
    let mut out = String::new();
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == b'$' {
            let mut n = 0usize;
            while i + n < bytes.len() && bytes[i + n] == b'$' { n += 1 }
            let start = i + n;
            let mut j = start;
            while j < bytes.len() && (bytes[j].is_ascii_alphanumeric() || bytes[j] == b'_') { j += 1 }
            let name = &fix[start..j];
            if n > 0 && !name.is_empty() {
                if n == 3 {
                    if let Some(ids) = h.vars.multi.iter().find(|(k, _)| k == name) {
                        for (k, &id) in ids.1.iter().enumerate() {
                            if k > 0 { out.push_str(", ") }
                            out.push_str(&src[node_span(h, id)]);
                        }
                        i = j;
                        continue;
                    }
                } else if let Some(id) = h.vars.single.iter().find(|(k, _)| k == name) {
                    let (s, e) = node_span(h, id.1);
                    out.push_str(&src[s..e]);
                    i = j;
                    continue;
                }
            }
            out.push_str(&fix[i..i + n]);
            i += n;
            continue;
        }
        out.push(bytes[i] as char);
        i += 1;
    }
    out
}

fn node_span(h: &Hit, id: u32) -> (usize, usize) {
    // relative positions resolved later by the caller using the source tree
    (h.start + 0, h.end)
}

pub fn print_diff(path: &str, old: &str, new: &str) -> String {
    let mut out = String::new();
    out.push_str(path);
    out.push('\n');
    let old_l: Vec<&str> = old.split('\n').collect();
    let new_l: Vec<&str> = new.split('\n').collect();
    // find changed regions
    let n = old_l.len().max(new_l.len());
    let mut hunks: Vec<(usize, usize, usize)> = Vec::new();
    let mut i = 0usize;
    while i < n {
        let o = old_l.get(i).copied();
        let nw = new_l.get(i).copied();
        if o != nw {
            let s = i.saturating_sub(3);
            let mut e = (i + 3).min(n.saturating_sub(1));
            // extend while next change is within 3 lines
            let mut j = i + 1;
            while j < n {
                if old_l.get(j).copied() != new_l.get(j).copied() {
                    e = (j + 3).min(n.saturating_sub(1));
                    j += 1;
                } else {
                    break;
                }
            }
            hunks.push((s, e, i));
            i = e + 1;
        } else {
            i += 1;
        }
    }
    // merge overlapping hunks
    let mut merged: Vec<(usize, usize)> = Vec::new();
    for (s, e, _) in hunks {
        match merged.last_mut() {
            Some(last) if s <= last.1 + 1 => { last.1 = last.1.max(e) }
            _ => merged.push((s, e)),
        }
    }
    for (s, e) in merged {
        let o: Vec<&str> = old_l[s.min(old_l.len())..e.min(old_l.len())].to_vec();
        let nw: Vec<&str> = new_l[s.min(new_l.len())..e.min(new_l.len())].to_vec();
        let mut buf = String::new();
        output::diff_hunk(&o, &nw, s, &mut buf);
        out.push_str(&buf);
    }
    out
}
