//! The `run` command: one-shot search / rewrite.

use crate::error::{Res, SgError, PATTERN_URL, STDIN_URL, PLAYGROUND_URL};
use crate::lang::Lang;
use crate::lines::Lines;
use crate::matcher::Matcher;
use crate::output::{self, Hit, Inspect, JsonStyle};
use crate::pattern::{build_pattern, PatternOpts, Strictness};
use crate::tree::Tree;
use crate::walker::{collect_files, WalkOpts};
use std::io::Write;

pub struct RunArgs {
    pub pattern: String,
    pub selector: Option<String>,
    pub rewrite: Option<String>,
    pub lang: Option<crate::cli::LangId>,
    pub debug_query: Option<String>,
    pub strictness: Option<String>,
    pub paths: Vec<String>,
    pub no_ignore: Vec<crate::walker::NoIgnore>,
    pub globs: Vec<String>,
    pub follow: bool,
    pub threads: usize,
    pub stdin: bool,
    pub json: Option<String>,
    pub color: crate::output::ColorWhen,
    pub inspect: Inspect,
    pub before: usize,
    pub after: usize,
    pub heading: crate::output::Heading,
    pub interactive: bool,
    pub update_all: bool,
    pub files_with_matches: bool,
}

pub fn run(args: RunArgs) -> i32 {
    let lang = match &args.lang {
        Some(l) => crate::lang::Lang::from_str(&l.0),
        None => None,
    };
    if args.debug_query.is_some() && lang.is_none() {
        // clap already enforces this
    }
    let strict = args
        .strictness
        .as_deref()
        .and_then(Strictness::from_str)
        .unwrap_or(Strictness::Smart);
    let selector = args.selector.as_deref();
    let opts = PatternOpts { selector, strictness: strict };
    let pat = match build_pattern(lang.unwrap_or(Lang::JavaScript), &args.pattern, &opts) {
        Ok(p) => p,
        Err(e) => {
            crate::main_error(&e);
            return 8;
        }
    };
    if let Some(fmt) = &args.debug_query {
        print_debug(&pat, &args.pattern, fmt, args.before, args.after);
    }
    if pat.root_is_error {
        eprintln!("Warning: Pattern contains an ERROR node and may cause unexpected results.");
    }

    let mut inspected = 0usize;
    let mut skipped = 0usize;
    let mut total_hits: Vec<(String, Vec<Hit>, Lang, Tree, String)> = Vec::new();

    if args.stdin {
        let mut buf = String::new();
        use std::io::Read;
        let _ = std::io::stdin().read_to_string(&mut buf);
        let l = lang.unwrap_or(Lang::JavaScript);
        let hits = scan_text(&buf, l, &pat, &args.rewrite, &args.pattern);
        total_hits.push(("STDIN".to_string(), hits, l, Tree { nodes: vec![], root: 0 }, buf));
    } else {
        let wopts = WalkOpts {
            paths: args.paths.clone(),
            no_ignore: args.no_ignore.clone(),
            globs: args.globs.clone(),
            follow: args.follow,
            threads: args.threads,
        };
        let files = collect_files(&wopts);
        for f in &files {
            if args.inspect == Inspect::Entity {
                eprintln!("sg: entity|file|{}: language={}", f.path.display(), f.lang.name());
            }
            let src = match std::fs::read_to_string(&f.path) {
                Ok(s) => s,
                Err(_) => { skipped += 1; continue }
            };
            let hits = scan_text(&src, f.lang, &pat, &args.rewrite, &args.pattern);
            inspected += 1;
            if !hits.is_empty() {
                let tree = crate::parser::parse(f.lang, &src);
                total_hits.push((f.path.display().to_string(), hits, f.lang, tree, src));
            }
        }
    }

    if args.inspect != Inspect::Nothing {
        eprintln!(
            "sg: summary|file: scannedFileCount={},skippedFileCount={}",
            inspected, skipped
        );
    }

    let no_matches = total_hits.iter().all(|(_, h, ..)| h.is_empty());
    if pat.root_is_error && no_matches {
        eprintln!("Help: ast-grep parsed the pattern but it matched nothing in this run. Try using playground to refine the pattern.");
        eprintln!("See also: {}", PLAYGROUND_URL);
    }

    let mut stdout = std::io::stdout();
    let color = match args.color {
        crate::output::ColorWhen::Never => false,
        crate::output::ColorWhen::Always | crate::output::ColorWhen::Ansi => true,
        crate::output::ColorWhen::Auto => is_tty(),
    };
    let heading = match args.heading {
        crate::output::Heading::Never => false,
        crate::output::Heading::Always => true,
        crate::output::ColorWhen::Auto => is_tty(),
    };
    let _ = heading;

    if let Some(style) = &args.json {
        let style = match style.as_str() {
            "stream" => JsonStyle::Stream,
            "compact" => JsonStyle::Compact,
            _ => JsonStyle::Pretty,
        };
        let mut parts: Vec<String> = Vec::new();
        for (path, hits, lang, tree, src) in &total_hits {
            let lines = Lines::new(src);
            for h in hits {
                let v = output::hit_json(path, src, &lines, tree, *lang, h, args.before, args.after);
                match style {
                    JsonStyle::Stream => {
                        parts.push(serde_json::to_string(&v).unwrap_or_default());
                    }
                    JsonStyle::Pretty => {
                        parts.push(serde_json::to_string_pretty(&v).unwrap_or_default());
                    }
                    JsonStyle::Compact => {
                        parts.push(serde_json::to_string(&v).unwrap_or_default());
                    }
                }
            }
        }
        match style {
            JsonStyle::Stream => {
                let s = parts.join("\n");
                if !s.is_empty() { println!("{}", s); }
            }
            JsonStyle::Pretty => {
                let s = parts.join(",\n");
                println!("[\n{}\n]", s);
            }
            JsonStyle::Compact => {
                let s = parts.join(",");
                println!("[{}]", s);
            }
        }
        return if no_matches { 1 } else { 0 };
    }

    if args.files_with_matches {
        for (path, hits, ..) in &total_hits {
            if !hits.is_empty() {
                println!("{}", path);
            }
        }
        return if no_matches { 1 } else { 0 };
    }

    // rewrite handling
    if args.rewrite.is_some() {
        for (path, hits, lang, tree, src) in &total_hits {
            let edits = rewrite_edits(src, tree, hits, &args.rewrite.clone().unwrap());
            let new_src = output::apply_rewrites(src, &edits);
            if args.update_all {
                let _ = std::fs::write(path, &new_src);
            } else {
                let _ = stdout.write(print_diff(path, src, &new_src).as_bytes());
            }
            let _ = lang;
        }
        return if no_matches { 1 } else { 0 };
    }

    for (path, hits, _lang, _tree, src) in &total_hits {
        let lines = Lines::new(src);
        let mut buf = String::new();
        output::print_text(
            path,
            src,
            &lines,
            hits,
            &output::PrintOpts { color, heading },
            args.before,
            args.after,
            &mut buf,
        );
        let _ = stdout.write(buf.as_bytes());
    }
    let _ = stdout.flush();
    if no_matches { 1 } else { 0 }
}

fn is_tty() -> bool {
    unsafe { libc_isatty(1) }
}

extern "C" {
    fn isatty(fd: i32) -> i32;
}

#[allow(non_snake_case)]
unsafe fn libc_isatty(fd: i32) -> bool { isatty(fd) == 1 }

fn print_debug(p: &crate::pattern::Pattern, src: &str, fmt: &str, before: usize, after: usize) {
    let _ = (before, after);
    let mut out = String::new();
    match fmt {
        "pattern" => output::debug_pattern(p, src, &mut out),
        "sexp" => output::debug_sexp(&p.tree, src, &mut out),
        "cst" | "ast" => {
            if fmt == "cst" {
                out.push_str("Debug CST:\n");
            } else {
                out.push_str("Debug AST:\n");
            }
            let lines = Lines::new(src);
            output::debug_tree(&p.tree, src, &lines, fmt == "cst", &mut out);
        }
        _ => {}
    }
    eprint!("{}", out);
}

/// Find all matches of the pattern in a source text.
pub fn scan_text(
    src: &str,
    lang: Lang,
    pat: &crate::pattern::Pattern,
    _rewrite: &Option<String>,
    _orig: &str,
) -> Vec<Hit> {
    let tree = crate::parser::parse(lang, src);
    let mut hits = Vec::new();
    let m = Matcher { pt: pat, st: &tree, src, strictness: pat.strictness };
    collect_hits(&tree, tree.root, &m, &mut hits);
    hits
}

fn collect_hits(tree: &Tree, node: u32, m: &Matcher, out: &mut Vec<Hit>) {
    let mut vars = crate::matcher::MetaVars::default();
    if m.match_node(m.pt.root, node, &mut vars) {
        let n = tree.node(node);
        out.push(Hit { node, start: n.start, end: n.end, vars });
        return;
    }
    for &c in &tree.node(node).children.clone() {
        collect_hits(tree, c, m, out);
    }
}

pub fn rewrite_edits(src: &str, tree: &Tree, hits: &[Hit], fix: &str) -> Vec<(usize, usize, String)> {
    let _ = tree;
    let mut out = Vec::new();
    for h in hits {
        let text = render_fix(fix, h, src);
        out.push((h.start, h.end, text));
    }
    let _ = src;
    out
}

/// Substitute meta variables into a rewrite template.
pub fn render_fix(fix: &str, h: &Hit, src: &str) -> String {
    let bytes = fix.as_bytes();
    let mut out = String::new();
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == b'$' {
            let mut n = 0usize;
            while i + n < bytes.len() && bytes[i + n] == b'$' { n += 1 }
            let start = i + n;
            let mut j = start;
            while j < bytes.len() && (bytes[j].is_ascii_alphanumeric() || bytes[j] == b'_') { j += 1 }
            let name = &fix[start..j];
            if n > 0 && !name.is_empty() {
                if n == 3 {
                    if let Some(ids) = h.vars.multi.iter().find(|(k, _)| k == name) {
                        for (k, &id) in ids.1.iter().enumerate() {
                            if k > 0 { out.push_str(", ") }
                            out.push_str(&src[node_span(h, id)]);
                        }
                        i = j;
                        continue;
                    }
                } else if let Some(id) = h.vars.single.iter().find(|(k, _)| k == name) {
                    let (s, e) = node_span(h, id.1);
                    out.push_str(&src[s..e]);
                    i = j;
                    continue;
                }
            }
            out.push_str(&fix[i..i + n]);
            i += n;
            continue;
        }
        out.push(bytes[i] as char);
        i += 1;
    }
    out
}

fn node_span(h: &Hit, id: u32) -> (usize, usize) {
    // relative positions resolved later by the caller using the source tree
    (h.start + 0, h.end)
}

pub fn print_diff(path: &str, old: &str, new: &str) -> String {
    let mut out = String::new();
    out.push_str(path);
    out.push('\n');
    let old_l: Vec<&str> = old.split('\n').collect();
    let new_l: Vec<&str> = new.split('\n').collect();
    // find changed regions
    let n = old_l.len().max(new_l.len());
    let mut hunks: Vec<(usize, usize, usize)> = Vec::new();
    let mut i = 0usize;
    while i < n {
        let o = old_l.get(i).copied();
        let nw = new_l.get(i).copied();
        if o != nw {
            let s = i.saturating_sub(3);
            let mut e = (i + 3).min(n.saturating_sub(1));
            // extend while next change is within 3 lines
            let mut j = i + 1;
            while j < n {
                if old_l.get(j).copied() != new_l.get(j).copied() {
                    e = (j + 3).min(n.saturating_sub(1));
                    j += 1;
                } else {
                    break;
                }
            }
            hunks.push((s, e, i));
            i = e + 1;
        } else {
            i += 1;
        }
    }
    // merge overlapping hunks
    let mut merged: Vec<(usize, usize)> = Vec::new();
    for (s, e, _) in hunks {
        match merged.last_mut() {
            Some(last) if s <= last.1 + 1 => { last.1 = last.1.max(e) }
            _ => merged.push((s, e)),
        }
    }
    for (s, e) in merged {
        let o: Vec<&str> = old_l[s.min(old_l.len())..e.min(old_l.len())].to_vec();
        let nw: Vec<&str> = new_l[s.min(new_l.len())..e.min(new_l.len())].to_vec();
        let mut buf = String::new();
        output::diff_hunk(&o, &nw, s, &mut buf);
        out.push_str(&buf);
    }
    out
}
