{"command": "cd /workspace && cat > src/parser/js.rs <<'RSEOF'
//! JavaScript / TypeScript / TSX parser producing tree-sitter compatible node kinds.
//!
//! Convention: every function returning `Option<u32>` builds one node and
//! returns its id *without* attaching it; the caller decides where it goes.
//! Functions returning `bool` attach their nodes to the current node.

use crate::lang::Lang;
use crate::parser::P;

const L: Lang = Lang::JavaScript;

fn ws(p: &mut P) { p.ws(L); }
fn kw(p: &mut P, w: &'static str) -> bool { p.kw(w) }
fn lit(p: &mut P, l: &'static str) -> bool { p.lit(l) }
fn f(p: &mut P, id: u32, name: &'static str) { p.set_field(id, name); }
fn tok(p: &mut P, k: &'static str, named: bool, s: usize) -> u32 { p.push_make(k, named, s, Vec::new()) }
fn det(p: &mut P, k: &'static str, named: bool, s: usize, kids: Vec<u32>) -> u32 { p.make_node(k, named, s, kids) }
fn ns(p: &P, id: u32) -> usize { p.nodes[id as usize].start }
fn kind_of(p: &P, id: u32) -> &'static str { p.nodes[id as usize].kind }

fn box_op(op: &str) -> &'static str {
    match op {
        "===" => "===", "==" => "==", "!==" => "!==", "!=" => "!=", "<<" => "<<",
        "<=" => "<=", "<" => "<", ">>>" => ">>>", ">>" => ">>", ">=" => ">=", ">" => ">",
        "&&" => "&&", "&=" => "&=", "&" => "&", "||" => "||", "|=" => "|=", "|" => "|",
        "^=" => "^=", "^" => "^", "**" => "**", "*=" => "*=", "*" => "*", "/=" => "/=",
        "/" => "/", "%=" => "%=", "%" => "%", "+=" => "+=", "+" => "+", "-=" => "-=",
        "-" => "-", "??=" => "??=", "??" => "??", _ => op,
    }
}

fn is_ts(lang: Lang) -> bool { matches!(lang, Lang::TypeScript | Lang::Tsx) }
fn ident_char(c: u8) -> bool { c.is_ascii_alphanumeric() || c == b'_' || c == b'$' || c >= 0x80 }

// ------------------------------------------------------------------ lexemes

fn ident(p: &mut P) -> Option<u32> {
    let c = p.cur();
    if !(c.is_ascii_alphabetic() || c == b'_' || c == b'$' || c >= 0x80) { return None }
    let s = p.i;
    p.begin("identifier", true);
    while !p.eof() && ident_char(p.cur()) { p.i += 1 }
    Some(p.end_node())
}

fn prop_ident(p: &mut P) -> Option<u32> {
    let c = p.cur();
    if !(c.is_ascii_alphabetic() || c == b'_' || c == b'$' || c.is_ascii_digit() || c >= 0x80) {
        return None;
    }
    let s = p.i;
    p.begin("property_identifier", true);
    while !p.eof() && ident_char(p.cur()) { p.i += 1 }
    Some(p.end_node())
}

fn private_prop_ident(p: &mut P) -> Option<u32> {
    if p.cur() != b'#' { return None }
    let s = p.i;
    p.begin("private_property_identifier", true);
    p.i += 1;
    while !p.eof() && ident_char(p.cur()) { p.i += 1 }
    Some(p.end_node())
}

fn number(p: &mut P) -> Option<u32> {
    let start = p.i;
    let c = p.cur();
    if !(c.is_ascii_digit() || (c == b'.' && p.cur2().is_ascii_digit())) { return None }
    p.begin("number", true);
    if c == b'0' && (p.cur2() == b'b' || p.cur2() == b'o' || p.cur2() == b'x') {
        p.i += 2;
        while !p.eof() && (p.cur().is_ascii_alphanumeric() || p.cur() == b'_') { p.i += 1 }
        return Some(p.end_node());
    }
    let mut dot = false;
    let mut exp = false;
    while !p.eof() {
        let c = p.cur();
        if c.is_ascii_digit() || c == b'_' { p.i += 1 }
        else if c == b'.' && !dot && !exp { dot = true; p.i += 1 }
        else if (c == b'e' || c == b'E') && !exp && p.i > start {
            exp = true;
            p.i += 1;
            if p.cur() == b'+' || p.cur() == b'-' { p.i += 1 }
        } else if c == b'n' && p.i > start { p.i += 1; break }
        else { break }
    }
    Some(p.end_node())
}

fn escape_seq(p: &mut P) {
    let s = p.i;
    p.begin("escape_sequence", true);
    p.i += 1;
    if p.cur() == b'u' || p.cur() == b'x' {
        p.i += 1;
        if p.cur() == b'{' {
            while !p.eof() && p.cur() != b'}' { p.i += 1 }
            if p.cur() == b'}' { p.i += 1 }
        } else {
            for _ in 0..4 { if p.cur().is_ascii_hexdigit() { p.i += 1 } else { break } }
        }
    } else if !p.eof() { p.i += 1 }
    p.end_node();
    let id = p.nodes_last_id();
    p.push(id);
}

fn string(p: &mut P) -> Option<u32> {
    let start = p.i;
    let quote = p.cur();
    if quote != b'"' && quote != b'\'' { return None }
    p.begin("string", true);
    let q = if quote == b'"' { "\"" } else { "'" };
    p.i += 1;
    tok(p, q, false, start);
    let fs = p.i;
    let mut frag_pending = true;
    while !p.eof() && p.cur() != quote {
        if p.cur() == b'\\' {
            if frag_pending {
                if p.i > fs { p.push(det(p, "string_fragment", true, fs, Vec::new())) }
                frag_pending = false;
            }
            escape_seq(p);
            frag_pending = true;
            let fs2 = p.i;
            while !p.eof() && p.cur() != quote && p.cur() != b'\\' { p.i += 1 }
            if p.i > fs2 {
                p.push(det(p, "string_fragment", true, fs2, Vec::new()));
                frag_pending = false;
            }
            continue;
        }
        p.i += 1;
    }
    if frag_pending && p.i > fs {
        p.push(det(p, "string_fragment", true, fs, Vec::new()));
    }
    if p.cur() == quote {
        let qs = p.i;
        p.i += 1;
        tok(p, q, false, qs);
    }
    Some(p.end_node())
}

fn template_string(p: &mut P) -> Option<u32> {
    if p.cur() != b'`' { return None }
    let start = p.i;
    p.begin("template_string", true);
    p.i += 1;
    tok(p, "`", false, start);
    loop {
        if p.eof() { break }
        if p.cur() == b'`' {
            let s = p.i;
            p.i += 1;
            tok(p, "`", false, s);
            break;
        }
        if p.cur() == b'\\' { escape_seq(p); continue }
        if p.cur() == b'$' && p.cur2() == b'{' {
            let ss = p.i;
            p.i += 2;
            p.begin("template_substitution", true);
            tok(p, "${", false, ss);
            ws(p);
            if let Some(e) = expression(p, 0) { p.push(e) }
            ws(p);
            let _ = lit(p, "}");
            let id = p.end_node();
            p.push(id);
            continue;
        }
        let fs = p.i;
        while !p.eof() && p.cur() != b'`' && p.cur() != b'\\'
            && !(p.cur() == b'$' && p.cur2() == b'{') { p.i += 1 }
        if p.i > fs { p.push(det(p, "string_fragment", true, fs, Vec::new())) }
    }
    Some(p.end_node())
}

fn regex(p: &mut P) -> Option<u32> {
