// -------------------------------------------------------------- type syntax

fn type_ident(p: &mut P) -> Option<u32> {
    let start = p.i;
    p.begin("type_identifier", true);
    if ident(p).is_none() { p.reset_mark(); return None }
    let mut has_dot = false;
    loop {
        ws(p);
        if p.cur() == b'.' {
            let ds = p.i;
            p.i += 1;
            tok(p, ".", false, ds);
            if ident(p).is_none() { break }
            has_dot = true;
        } else { break }
    }
    let kids = p.frame_take();
    let s = p.frame_start();
    p.pop_frame();
    if has_dot {
        p.push(det(p, "nested_type_identifier", true, s, kids));
    } else {
        p.push(det(p, "type_identifier", true, s, kids));
    }
    Some(p.nodes_last_id())
}

fn type_args(p: &mut P) -> bool {
    let start = p.i;
    if p.cur() != b'<' { return false }
    p.begin("type_arguments", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'>' { break }
        if !type_(p) { break }
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, ">");
    p.end();
    let _ = start;
    true
}

fn type_params(p: &mut P) -> bool {
    let start = p.i;
    if p.cur() != b'<' { return false }
    p.begin("type_parameters", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'>' { break }
        p.begin("type_parameter", true);
        let _ = kw(p, "const");
        ws(p);
        if ident(p).is_none() { p.end(); break }
        ws(p);
        if kw(p, "extends") { ws(p); let _ = type_(p); }
        ws(p);
        if p.cur() == b'=' {
            let es = p.i; p.i += 1;
            tok(p, "=", false, es);
            ws(p);
            let _ = type_(p);
        }
        p.end();
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, ">");
    p.end();
    let _ = start;
    true
}

fn type_(p: &mut P) -> bool {
    let start = p.i;
    p.begin("union_type", true);
    if !type_inner(p) { p.reset_mark(); return false }
    loop {
        ws(p);
        let save = p.i;
        let u = p.cur() == b'|' && p.cur2() != b'|';
        let i = p.cur() == b'&' && p.cur2() != b'&';
        if !(u || i) { p.i = save; break }
        let os = p.i;
        p.i += 1;
        tok(p, "|", false, os);
        ws(p);
        if !type_inner(p) { p.i = save; break }
    }
