                            tok(p, "=", false, es);
                            ws(p);
                            let _ = expression(p, 0);
                            let id = p.end_node();
                            p.push(id);
                        } else {
                            p.push(el);
                        }
                    } else { break }
                } else {
                    let key = if p.cur() == b'"' || p.cur() == b'\'' { string(p) }
                              else if p.cur() == b'#' { private_prop_ident(p) }
                              else { prop_ident(p) };
                    let key = match key { Some(k) => k, None => break };
                    ws(p);
                    if p.cur() == b'=' {
                        p.begin("object_assignment_pattern", true);
                        p.push(key);
                        let es = p.i; p.i += 1;
                        tok(p, "=", false, es);
                        ws(p);
                        let _ = expression(p, 0);
                        let id = p.end_node();
                        p.push(id);
                    } else if p.cur() == b':' {
                        p.begin("pair_pattern", true);
                        p.push(key);
                        let cls = p.i; p.i += 1;
                        tok(p, ":", false, cls);
                        ws(p);
                        let _ = pattern(p).map(|x| p.push(x));
                        let id = p.end_node();
                        p.push(id);
                    } else {
                        p.push(det(p, "shorthand_property_identifier_pattern", true, start, vec![key]));
                    }
                }
                ws(p);
                if !lit(p, ",") { break }
            }
            ws(p);
            let _ = lit(p, "}");
            Some(p.end_node())
        }
        b'[' => {
            p.begin("array_pattern", true);
            p.i += 1;
            loop {
                ws(p);
                if p.cur() == b']' || p.eof() { break }
                if p.text_at("...") {
                    p.begin("rest_pattern", true);
                    let rs = p.i;
                    p.i += 3;
                    tok(p, "...", false, rs);
                    ws(p);
                    let _ = pattern(p).map(|x| p.push(x));
                    let id = p.end_node();
                    p.push(id);
                } else {
                    match pattern(p) {
                        Some(el) => {
                            ws(p);
                            if p.cur() == b'=' {
                                p.begin("object_assignment_pattern", true);
                                p.push(el);
                                let es = p.i; p.i += 1;
                                tok(p, "=", false, es);
                                ws(p);
                                let _ = expression(p, 0);
                                let id = p.end_node();
                                p.push(id);
                            } else {
                                p.push(el);
                            }
                        }
                        None => break,
                    }
                }
                ws(p);
                if !lit(p, ",") { break }
            }
            ws(p);
            let _ = lit(p, "]");
            Some(p.end_node())
        }
        _ => {
            if kw(p, "this") {
                return Some(det(p, "this", true, start, Vec::new()));
            }
            ident(p)
        }
    }
}

// -------------------------------------------------------------- expressions

fn binary_prec(op: &str) -> i32 {
    match op {
        "??" => 1, "||" => 2, "&&" => 3, "|" => 4, "^" => 5, "&" => 6,
        "==" | "!=" | "===" | "!==" => 7,
        "<" | ">" | "<=" | ">=" | "in" | "instanceof" => 8,
        "<<" | ">>" | ">>>" => 9, "+" | "-" => 10, "*" | "/" | "%" => 11, "**" => 12,
        _ => -1,
    }
}

fn peek_binary_op(p: &P) -> Option<&'static str> {
    let c = p.cur();
    let c2 = p.cur2();
    let c3 = p.cur3();
    match (c, c2, c3) {
        (b'=', b'=', b'=') => Some("==="),
        (b'=', b'=', _) => Some("=="),
        (b'!', b'=', b'=') => Some("!=="),
        (b'!', b'=', _) => Some("!="),
        (b'<', b'<', b'<') => Some("<<<"),
        (b'<', b'<', _) => Some("<<"),
        (b'<', b'=', _) => Some("<="),
        (b'<', _, _) => Some("<"),
        (b'>', b'>', b'>') => Some(">>>"),
        (b'>', b'>', _) => Some(">>"),
        (b'>', b'=', _) => Some(">="),
        (b'>', _, _) => Some(">"),
        (b'&', b'&', _) => Some("&&"),
        (b'&', b'=', _) => Some("&="),
        (b'&', _, _) => Some("&"),
        (b'|', b'|', _) => Some("||"),
        (b'|', b'=', _) => Some("|="),
        (b'|', _, _) => Some("|"),
        (b'^', b'=', _) => Some("^="),
        (b'^', _, _) => Some("^"),
        (b'*', b'*', _) => Some("**"),
        (b'*', b'=', _) => Some("*="),
        (b'*', _, _) => Some("*"),
        (b'/', b'=', _) => Some("/="),
        (b'/', _, _) => Some("/"),
        (b'%', b'=', _) => Some("%="),
        (b'%', _, _) => Some("%"),
        (b'+', b'=', _) => Some("+="),
        (b'+', _, _) => Some("+"),
        (b'-', b'=', _) => Some("-="),
        (b'-', _, _) => Some("-"),
        (b'?', b'?', b'=') => Some("??="),
        (b'?', b'?', _) => Some("??"),
        _ => None,
    }
}

pub fn expression(p: &mut P, min_prec: i32) -> Option<u32> {
    ws(p);
    let start = p.i;
    let mut base = match unary_chain(p) { Some(x) => x, None => return None };
    loop {
        ws(p);
        let save = p.i;
        if p.cur() == b',' && min_prec <= 0 {
            let cs = p.i;
            p.i += 1;
            let mut kids = Vec::new();
            kids.push(base);
            tok(p, ",", false, cs);
            let rest = expression(p, 0);
            match rest {
                Some(r) => kids.push(r),
                None => { p.i = save; break }
            }
            return Some(det(p, "sequence_expression", true, start, kids));
        }
        if p.cur() == b'?' && p.cur2() != b'?' {
            let qs = p.i;
            p.i += 1;
            let mut kids = Vec::new();
            kids.push(base);
            tok(p, "?", false, qs);
            ws(p);
            match expression(p, 0) {
                Some(c) => kids.push(c),
                None => { p.i = save; break }
            }
            ws(p);
            if !lit(p, ":") { p.i = save; break }
            ws(p);
            match assignment_expr(p) {
                Some(a) => kids.push(a),
                None => { p.i = save; break }
            }
            return Some(det(p, "ternary_expression", true, start, kids));
        }
        if p.cur() == b'=' && p.cur2() != b'=' {
            let es = p.i;
            p.i += 1;
            let mut kids = Vec::new();
            kids.push(base);
            tok(p, "=", false, es);
            ws(p);
            match assignment_expr(p) {
                Some(r) => kids.push(r),
                None => { p.i = save; break }
            }
            return Some(det(p, "assignment_expression", true, start, kids));
        }
        if let Some(op) = peek_binary_op(p) {
            if op.ends_with('=') && op != "==" && op != "!=" && op != "<=" && op != ">=" {
                let os = p.i;
                p.i += op.len();
                let mut kids = Vec::new();
                kids.push(base);
                tok(p, box_op(op), false, os);
                ws(p);
                match assignment_expr(p) {
                    Some(r) => kids.push(r),
                    None => { p.i = save; break }
                }
                return Some(det(p, "augmented_assignment_expression", true, start, kids));
            }
            let prec = binary_prec(op);
            if prec >= min_prec && !op.ends_with('=') {
                let os = p.i;
                p.i += op.len();
                let mut kids = Vec::new();
                kids.push(base);
                tok(p, box_op(op), false, os);
                ws(p);
                let right_assoc = op == "**";
                let next = if right_assoc { prec } else { prec + 1 };
                match expression(p, next) {
                    Some(r) => kids.push(r),
                    None => { p.i = save; break }
                }
                return Some(det(p, "binary_expression", true, start, kids));
            }
        }
        if kw(p, "in") || kw(p, "instanceof") {
            let prec = 8;
            if prec >= min_prec {
                ws(p);
                let mut kids = Vec::new();
                kids.push(base);
                let opid = p.nodes_last_id();
                f(p, opid, "operator");
                match expression(p, prec + 1) {
                    Some(r) => kids.push(r),
                    None => { p.i = save; break }
                }
                return Some(det(p, "binary_expression", true, start, kids));
            }
        }
        break;
    }
    Some(base)
}

fn assignment_expr(p: &mut P) -> Option<u32> { expression(p, 1) }

fn unary_chain(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    let c = p.cur();
    if c == b'!' || c == b'~' || c == b'+' || c == b'-' {
        let two = (c == b'+' && p.cur2() == b'+') || (c == b'-' && p.cur2() == b'-');
        if !two {
            let os = p.i;
            let op = match c { b'!' => "!", b'~' => "~", b'+' => "+", _ => "-" };
            p.i += 1;
            tok(p, box_op(op), false, os);
            ws(p);
            let inner = unary_chain(p)?;
            return Some(det(p, "unary_expression", true, start, vec![inner]));
        }
    }
    if kw(p, "typeof") || kw(p, "void") || kw(p, "delete") {
        ws(p);
        let inner = unary_chain(p)?;
        let op = p.nodes[kids_last(&vec![0]) as usize].kind;
        let _ = op;
        return Some(det(p, "unary_expression", true, start, vec![inner]));
    }
    if kw(p, "await") {
        ws(p);
        let inner = unary_chain(p);
        let kids = match inner { Some(x) => vec![x], None => vec![] };
        return Some(det(p, "await_expression", true, start, kids));
    }
    if kw(p, "yield") {
        ws(p);
        let mut kids = Vec::new();
        if p.cur() == b'*' {
            let ss = p.i;
            p.i += 1;
            tok(p, "*", false, ss);
            kids.push(p.nodes_last_id());
        }
        ws(p);
        if let Some(inner) = unary_chain(p) { kids.push(inner) }
        return Some(det(p, "yield_expression", true, start, kids));
    }
    if (c == b'+' && p.cur2() == b'+') || (c == b'-' && p.cur2() == b'-') {
        let os = p.i;
        let op = if c == b'+' { "++" } else { "--" };
        p.i += 2;
        let inner = postfix(p)?;
        tok(p, box_op(op), false, os);
        let opid = p.nodes_last_id();
        return Some(det(p, "update_expression", true, start, vec![inner, opid]));
    }
    postfix(p)
}

fn kids_last(v: &[u32]) -> u32 { v[v.len() - 1] }

fn postfix(p: &mut P) -> Option<u32> {
    let mut base = match primary(p) { Some(x) => x, None => return None };
    loop {
        ws(p);
        let save = p.i;
        if p.cur() == b'(' {
            let args = match arguments(p) { Some(a) => a, None => { p.i = save; break } };
            let s = ns(p, base);
            p.push(det(p, "call_expression", true, s, vec![base, args]));
            f(p, base, "function");
            f(p, args, "arguments");
            base = p.nodes_last_id();
            continue;
        }
        if p.cur() == b'.' || p.text_at("?.") {
            let ms = p.i;
            let is_opt = p.text_at("?.");
            p.i += if is_opt { 2 } else { 1 };
            let mut kids = vec![base];
            if is_opt {
                let oc = det(p, "optional_chain", true, ms, Vec::new());
                p.push(oc);
                kids.push(oc);
                f(p, oc, "optional_chain");
            } else {
                tok(p, ".", false, ms);
                kids.push(p.nodes_last_id());
            }
            ws(p);
            let prop = if p.cur() == b'#' { private_prop_ident(p) } else { prop_ident(p) };
            let prop = match prop { Some(x) => x, None => { p.i = save; break } };
            kids.push(prop);
            f(p, prop, "property");
            let s = ns(p, base);
            p.push(det(p, "member_expression", true, s, kids));
            base = p.nodes_last_id();
            continue;
        }
        if p.cur() == b'[' {
            let ms = p.i;
            p.i += 1;
            let bk = det(p, "[", false, ms, Vec::new());
            p.push(bk);
            ws(p);
            let idx = match expression(p, 0) { Some(x) => x, None => { p.i = save; break } };
            ws(p);
            if !lit(p, "]") { p.i = save; break }
            let end_idx = p.nodes_last_id();
            let s = ns(p, base);
            p.push(det(p, "subscript_expression", true, s, vec![base, bk, idx, end_idx]));
            f(p, base, "object");
            f(p, idx, "index");
            base = p.nodes_last_id();
            continue;
        }
        if (p.cur() == b'+' && p.cur2() == b'+') || (p.cur() == b'-' && p.cur2() == b'-') {
            let os = p.i;
            let op = if p.s[os] == b'+' { "++" } else { "--" };
            p.i += 2;
            let opid = det(p, box_op(op), false, os, Vec::new());
            p.push(opid);
            let s = ns(p, base);
            p.push(det(p, "update_expression", true, s, vec![base, opid]));
            f(p, base, "argument");
            base = p.nodes_last_id();
            continue;
        }
        break;
    }
    Some(base)
}
RSEOF
echo ok"}

