// --------------------------------------------------------------- parameters

fn formal_parameters(p: &mut P) -> bool {
    let start = p.i;
    if p.cur() != b'(' { return false }
    p.begin("formal_parameters", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b')' || p.eof() { break }
        let ps = p.i;
        p.begin("required_parameter", true);
        decorators(p);
        ws(p);
        loop {
            let save = p.i;
            ws(p);
            if kw(p, "public") || kw(p, "private") || kw(p, "protected")
                || kw(p, "readonly") || kw(p, "override")
            { continue }
            p.i = save;
            break
        }
        ws(p);
        if pattern(p).is_none() { p.reset_mark(); break }
        ws(p);
        let mut opt = false;
        if p.cur() == b'?' {
            let qs = p.i; p.i += 1;
            tok(p, "?", false, qs);
            ws(p);
            opt = true;
        }
        if p.cur() == b':' { let _ = type_annotation(p); ws(p); }
        if p.cur() == b'=' {
            let es = p.i; p.i += 1;
            tok(p, "=", false, es);
            ws(p);
            let _ = expression(p, 0);
            opt = true;
        }
        if opt { let kids = p.frame_swap("optional_parameter"); let _ = kids; }
        p.end();
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, ")");
    p.end();
    let _ = start;
    true
}

fn decorators(p: &mut P) {
    loop {
        let save = p.i;
        ws(p);
        if p.cur() != b'@' { p.i = save; break }
        p.begin("decorator", true);
        p.i += 1;
        ws(p);
        match primary(p) {
            Some(x) => { p.push(x); p.end(); }
            None => { p.reset_mark(); p.i = save; break }
        }
    }
}

fn arguments(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'(' { return None }
    p.begin("arguments", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b')' || p.eof() { break }
        let as_ = p.i;
        if p.text_at("...") {
            p.begin("spread_element", true);
            let rs = p.i;
            p.i += 3;
            tok(p, "...", false, rs);
            ws(p);
            let _ = expression(p, 0);
            p.end();
            let id = p.nodes_last_id();
            p.push(id);
        } else {
            match expression(p, 0) {
                Some(x) => p.push(x),
                None => break,
            }
        }
        let _ = as_;
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, ")");
    Some(p.end_node())
}

