            ws(p);
            if kw(p, "public") || kw(p, "private") || kw(p, "protected")
                || kw(p, "readonly") || kw(p, "override")
            { continue }
            p.i = save;
            break
        }
        ws(p);
        if pattern(p).is_none() { p.reset_mark(); break }
        ws(p);
        let mut opt = false;
        if p.cur() == b'?' {
            let qs = p.i; p.i += 1;
            tok(p, "?", false, qs);
            ws(p);
            opt = true;
        }
