fn primary(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    let c = p.cur();
    match c {
        b'(' => arrow_function(p).or_else(|| parenthesized(p)),
        b'{' => object(p),
        b'[' => array(p),
        b'"' | b'\'' => string(p),
        b'`' => template_string(p),
        b'/' => regex(p),
        b'<' => jsx_element(p),
        b'0'..=b'9' => number(p),
        _ => {
            if kw(p, "new") {
                ws(p);
                let callee = match postfix_no_call(p) { Some(x) => x, None => return None };
                f(p, callee, "constructor");
                ws(p);
                if p.cur() == b'<' { let _ = type_args(p); ws(p); }
                let mut kids = vec![callee];
                if p.cur() == b'(' {
                    let args = match arguments(p) { Some(a) => a, None => return None };
                    f(p, args, "arguments");
                    kids.push(args);
                }
                Some(det(p, "new_expression", true, start, kids))
            } else if kw(p, "this") {
                Some(det(p, "this", true, start, Vec::new()))
            } else if kw(p, "super") {
