            } else if kw(p, "true") {
                Some(det(p, "true", true, start, Vec::new()))
            } else if kw(p, "false") {
                Some(det(p, "false", true, start, Vec::new()))
            } else if kw(p, "null") {
                Some(det(p, "null", true, start, Vec::new()))
            } else if kw(p, "undefined") {
                Some(det(p, "undefined", true, start, Vec::new()))
            } else if kw(p, "function") {
                ws(p);
                let mut kids = Vec::new();
                if p.cur() == b'*' {
                    let ss = p.i;
                    p.i += 1;
                    kids.push(det(p, "*", false, ss, Vec::new()));
                    ws(p);
                }
                if let Some(n) = ident(p) { kids.push(n) }
                ws(p);
                if !formal_parameters(p) { return None }
                kids.push(p.nodes_last_id());
                ws(p);
                if let Some(b) = statement_block(p) { kids.push(b) } else { return None }
                Some(det(p, "function_expression", true, start, kids))
            } else if kw(p, "class") {
                class_decl(p, false)
            } else if kw(p, "import") {
                ws(p);
                if p.cur() == b'(' {
                    let args = arguments(p)?;
                    let id = det(p, "import", true, start, vec![args]);
                    f(p, args, "source");
                    Some(id)
                } else {
                    None
                }
            } else if let Some(x) = ident(p) {
                Some(x)
            } else {
                None
            }
        }
    }
