        match ident(p) { Some(x) => kids.push(x), None => { p.reset(m); return None } }
    }
    ws(p);
    if p.cur() == b':' {
        let _ = type_annotation(p);
        kids.push(p.nodes_last_id());
        ws(p);
    }
