// ------------------------------------------------------------- statements

pub fn statement_block(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'{' { return None }
    p.begin("statement_block", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        match statement(p) {
            Some(id) => p.push(id),
            None => error_recovery(p),
        }
    }
    ws(p);
    let _ = lit(p, "}");
    Some(p.end_node())
}

fn error_recovery(p: &mut P) {
    let start = p.i;
    if p.eof() { return }
    while !p.eof() {
        let c = p.cur();
        if c == b';' { p.i += 1; break }
        if c == b'\n' { p.i += 1; break }
        if c == b'}' { break }
        p.i += 1;
    }
    p.push(det(p, "ERROR", true, start, Vec::new()));
}

fn opt_semicolon(p: &mut P) {
    let save = p.i;
    ws(p);
    if p.cur() == b';' { lit(p, ";"); } else { p.i = save; }
}

pub fn statement(p: &mut P) -> Option<u32> {
    ws(p);
