            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            None
        }
        b'@' => {
            decorators(p);
            statement(p)
        }
        _ => {
            let m = p.mark();
            if kw(p, "const") || kw(p, "let") {
                let kind_id = p.nodes_last_id();
                if let Some(d) = lexical_declaration(p, start, kind_id) { return Some(d) }
                p.reset(m);
            } else if kw(p, "var") {
                let kind_id = p.nodes_last_id();
                if let Some(d) = variable_declaration(p, start, kind_id) { return Some(d) }
                p.reset(m);
            } else if kw(p, "function") {
                ws(p);
