        b'{' => statement_block(p),
        b'#' if p.text_at("#!") => {
            while !p.eof() && p.cur() != b'\\' && p.cur() != b'\\' && p.cur() != b'\\' && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
            while !p.eof() && p.cur() != b'\\' { }
