        }
        b'@' => {
            decorators(p);
            statement(p)
        }
        _ => {
            let m = p.mark();
            if kw(p, "const") || kw(p, "let") {
                let kind_id = p.nodes_last_id();
                if let Some(d) = lexical_declaration(p, start, kind_id) { return Some(d) }
                p.reset(m);
            } else if kw(p, "var") {
                let kind_id = p.nodes_last_id();
                if let Some(d) = variable_declaration(p, start, kind_id) { return Some(d) }
                p.reset(m);
            } else if kw(p, "function") {
                ws(p);
                let mut is_gen = false;
                if p.cur() == b'*' { p.i += 1; ws(p); is_gen = true }
                let mut kids = Vec::new();
                if let Some(n) = ident(p) { kids.push(n); f(p, n, "name") }
                ws(p);
                if !formal_parameters(p) { p.reset(m); }
                else {
                    kids.push(p.nodes_last_id());
                    f(p, p.nodes_last_id(), "parameters");
                    ws(p);
                    match statement_block(p) {
                        Some(b) => {
                            kids.push(b);
                            f(p, b, "body");
                            let kind = if is_gen { "generator_function_declaration" } else { "function_declaration" };
                            return Some(det(p, kind, true, start, kids));
                        }
                        None => { p.reset(m); }
                    }
                }
            } else if kw(p, "class") {
                if let Some(id) = class_decl(p, true) { return Some(id) }
                p.reset(m);
            } else if kw(p, "if") {
                if let Some(id) = if_statement(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "for") {
                if let Some(id) = for_statement(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "while") {
                ws(p);
                if p.cur() == b'(' {
                    if let Some(cond) = parenthesized(p) {
                        let body = statement(p);
                        if let Some(b) = body {
                            f(p, cond, "condition");
                            f(p, b, "body");
                            opt_semicolon(p);
                            return Some(det(p, "while_statement", true, start, vec![cond, b]));
                        }
                    }
                }
                p.reset(m);
            } else if kw(p, "do") {
                ws(p);
                let body = statement(p);
                let body = match body { Some(b) => b, None => { p.reset(m); return None } };
                ws(p);
                let mut kids = vec![body];
                if kw(p, "while") {
                    ws(p);
                    if let Some(cond) = parenthesized(p) {
                        kids.push(cond);
                        f(p, cond, "condition");
                    }
                }
                opt_semicolon(p);
                return Some(det(p, "do_statement", true, start, kids));
            } else if kw(p, "try") {
                if let Some(id) = try_statement(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "switch") {
                if let Some(id) = switch_statement(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "return") {
                ws(p);
                let mut kids = Vec::new();
                if p.cur() != b';' && p.cur() != b'}' && !p.eof() {
                    if let Some(e) = expression(p, 0) { kids.push(e) }
                }
                opt_semicolon(p);
                return Some(det(p, "return_statement", true, start, kids));
            } else if kw(p, "throw") {
                ws(p);
                let e = expression(p, 0);
                opt_semicolon(p);
                let kids = match e { Some(e) => vec![e], None => vec![] };
                return Some(det(p, "throw_statement", true, start, kids));
            } else if kw(p, "break") || kw(p, "continue") {
                let is_break = kind_of(p, p.nodes_last_id()) == "break";
                let kind = if is_break { "break_statement" } else { "continue_statement" };
                ws(p);
                let mut kids = Vec::new();
                if p.cur() != b';' && p.cur() != b'}' {
                    if let Some(l) = ident(p) { kids.push(l); f(p, l, "label") }
                }
                opt_semicolon(p);
                return Some(det(p, kind, true, start, kids));
            } else if kw(p, "debugger") {
                opt_semicolon(p);
                return Some(det(p, "debugger_statement", true, start, Vec::new()));
            } else if kw(p, "import") {
                if let Some(id) = import_statement(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "export") {
                if let Some(id) = export_statement(p) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && kw(p, "interface") {
                if let Some(id) = interface_declaration(p) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && kw(p, "type") {
                if let Some(id) = type_alias(p) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && kw(p, "enum") {
                if let Some(id) = enum_declaration(p) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && (kw(p, "declare") || kw(p, "namespace") || kw(p, "module")) {
                if let Some(id) = ambient_or_namespace(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "async") {
                let after = p.i;
                if !(after < p.s.len() && p.is_word(p.s[after])) {
                    p.i = after;
                    ws(p);
                    if p.text_at("function") {
                        kw(p, "function");
                        let fid = p.nodes_last_id();
                        let _ = fid;
                        ws(p);
                        let mut is_gen = false;
                        if p.cur() == b'*' { p.i += 1; ws(p); is_gen = true }
                        let mut kids = vec![p.nodes_last_id()];
                        if let Some(n) = ident(p) { kids.push(n); f(p, n, "name") }
                        ws(p);
                        if formal_parameters(p) {
                            kids.push(p.nodes_last_id());
                            f(p, p.nodes_last_id(), "parameters");
                            ws(p);
                            if let Some(b) = statement_block(p) {
                                kids.push(b);
                                f(p, b, "body");
                                let kind = if is_gen { "generator_function_declaration" } else { "function_declaration" };
                                return Some(det(p, kind, true, start, kids));
                            }
                        }
                    }
                }
                p.reset(m);
            }
            // labeled statement
            {
                let save = p.i;
                if let Some(l) = ident(p) {
                    ws(p);
                    if p.cur() == b':' {
                        let cs = p.i;
                        p.i += 1;
                        ws(p);
                        let body = statement(p);
                        if let Some(b) = body {
                            f(p, l, "label");
                            f(p, b, "body");
                            return Some(det(p, "labeled_statement", true, start,
                                vec![l, det(p, ":", false, cs, Vec::new()), b]));
                        }
                    }
                }
                p.i = save;
            }
            let e = expression(p, 0)?;
            opt_semicolon(p);
            Some(det(p, "expression_statement", true, start, vec![e]))
        }
    }
}

fn if_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    if p.cur() != b'(' { return None }
    let cond = parenthesized(p)?;
    let body = statement(p)?;
    let mut kids = vec![cond, body];
    f(p, cond, "condition");
    f(p, body, "consequence");
    ws(p);
    if p.text_at("else") {
        p.begin("else_clause", true);
        kw(p, "else");
        ws(p);
        let _ = statement(p).map(|x| p.push(x));
        let alt = p.end_node();
        p.push(alt);
        f(p, alt, "alternative");
        kids.push(alt);
    }
    opt_semicolon(p);
    Some(det(p, "if_statement", true, start, kids))
}

fn try_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    let body = statement_block(p)?;
    let mut kids = vec![body];
    f(p, body, "body");
    ws(p);
    if p.text_at("catch") {
        p.begin("catch_clause", true);
        kw(p, "catch");
        ws(p);
        if p.cur() == b'(' {
            p.begin("catch_parameters", true);
            p.i += 1;
            ws(p);
            let _ = pattern(p).map(|x| p.push(x));
            ws(p);
            let _ = lit(p, ")");
            p.end();
            let cp = p.nodes_last_id();
            p.push(cp);
            f(p, cp, "pattern");
        }
        ws(p);
        if let Some(b) = statement_block(p) {
            p.push(b);
            f(p, b, "body");
        }
        let h = p.end_node();
        p.push(h);
        f(p, h, "handler");
        kids.push(h);
        ws(p);
    }
    if p.text_at("finally") {
        p.begin("finally_clause", true);
        kw(p, "finally");
        ws(p);
        if let Some(b) = statement_block(p) {
            p.push(b);
            f(p, b, "body");
        }
        let fin = p.end_node();
        p.push(fin);
        f(p, fin, "finalizer");
        kids.push(fin);
        ws(p);
    }
    opt_semicolon(p);
    Some(det(p, "try_statement", true, start, kids))
}

fn switch_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    let val = parenthesized(p)?;
    let mut kids = vec![val];
    f(p, val, "value");
    ws(p);
    if p.cur() != b'{' { return None }
    p.begin("switch_body", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        if p.text_at("case") {
            let cs = p.i;
            p.begin("switch_case", true);
            kw(p, "case");
            ws(p);
            let mut ck = Vec::new();
            if let Some(v) = expression(p, 0) {
                ck.push(v);
                f(p, v, "value");
            }
            ws(p);
            let _ = lit(p, ":");
            loop {
                ws(p);
                if p.cur() == b'}' || p.eof() || p.text_at("case") || p.text_at("default") { break }
                match statement(p) { Some(s) => ck.push(s), None => break }
            }
            let id = p.end_node();
            p.push(id);
            let _ = cs;
        } else if p.text_at("default") {
            p.begin("switch_default", true);
            kw(p, "default");
            ws(p);
            let _ = lit(p, ":");
            loop {
                ws(p);
                if p.cur() == b'}' || p.eof() || p.text_at("case") || p.text_at("default") { break }
                match statement(p) { Some(s) => p.push(s), None => break }
            }
            let id = p.end_node();
            p.push(id);
        } else {
            break;
        }
    }
    ws(p);
    let _ = lit(p, "}");
    let body = p.end_node();
    p.push(body);
    f(p, body, "body");
    kids.push(body);
    opt_semicolon(p);
    Some(det(p, "switch_statement", true, start, kids))
}
