        }
    }
    expression(p, 0)
}

fn for_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    if p.cur() != b'(' { return None }
    p.begin("for_statement", true);
    let mut kids = Vec::new();
    if kw(p, "await") { kids.push(p.nodes_last_id()); ws(p) }
    let paren = ns(p, p.nodes_last_id());
    p.i += 1; // (
    let _ = paren;
    ws(p);
    let mut is_for_in = false;
    if p.cur() == b';' {
        let ss = p.i;
        p.i += 1;
        kids.push(det(p, ";", false, ss, Vec::new()));
    } else {
