            return None;
        }
        let kids = p.frame_take();
        let s = p.frame_start();
        p.pop_frame();
        let _ = mods;
        return Some(det(p, "method_definition", true, s, kids));
    }
    // field definition
    let mut kids = p.frame_take();
    let s = p.frame_start();
    p.pop_frame();
    if p.cur() == b'!' && is_ts(L) { p.i += 1; ws(p) }
    if p.cur() == b':' {
        let before = p.nodes.len();
        if type_annotation(p) { kids.push(p.nodes_last_id()) }
        let _ = before;
        ws(p);
    }
    if p.cur() == b'=' {
        let es = p.i; p.i += 1;
        kids.push(det(p, "=", false, es, Vec::new()));
        ws(p);
        match expression(p, 0) {
            Some(v) => { kids.push(v); f(p, v, "value") }
            None => return None,
        }
    }
    opt_semicolon(p);
    Some(det(p, "field_definition", true, s, kids))
}
