// ---------------------------------------------------------------- classes

fn class_decl(p: &mut P, top_level: bool) -> Option<u32> {
    let start = p.i;
    let _ = top_level;
    ws(p);
    let is_abstract = kw(p, "abstract");
    ws(p);
    let mut kids = Vec::new();
    if is_abstract { kids.push(p.nodes_last_id()) }
    if let Some(n) = ident(p) { kids.push(n); f(p, n, "name") }
    ws(p);
    if kw(p, "extends") {
        ws(p);
        p.begin("class_heritage", true);
        let _ = expression(p, 0);
        let h = p.end_node();
        p.push(h);
        kids.push(h);
    } else if is_ts(L) && kw(p, "implements") {
        p.begin("class_heritage", true);
        ws(p);
        loop {
            ws(p);
            if !type_(p) { break }
            ws(p);
            if !lit(p, ",") { break }
        }
        let h = p.end_node();
        p.push(h);
        kids.push(h);
    }
    ws(p);
    if p.cur() != b'{' { return None }
    let body = class_body(p)?;
    f(p, body, "body");
    kids.push(body);
    let kind = if is_abstract { "abstract_class_declaration" } else { "class_declaration" };
    Some(det(p, kind, true, start, kids))
}

fn class_body(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'{' { return None }
    p.begin("class_body", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        let m = p.mark();
        match class_member(p) {
            Some(id) => p.push(id),
            None => { p.reset(m); error_recovery(p); }
        }
    }
    ws(p);
    let _ = lit(p, "}");
    Some(p.end_node())
}

fn class_member(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    if p.text_at("static") {
        let after = p.i + 6;
        if after < p.s.len() && p.s[after] == b'{' {
            let ss = p.i;
            p.i += 6;
            ws(p);
            if let Some(b) = statement_block(p) {
                let kind = det(p, "class_static_block", true, ss, vec![b]);
                opt_semicolon(p);
                return Some(kind);
            }
        }
    }
    p.begin("method_definition", true);
    let mut mods = Vec::new();
    loop {
        ws(p);
        if kw(p, "public") || kw(p, "private") || kw(p, "protected")
            || kw(p, "static") || kw(p, "abstract") || kw(p, "override") || kw(p, "declare")
            || kw(p, "readonly")
        { mods.push(p.nodes_last_id()); continue }
        break
    }
    ws(p);
    let mut kind_tok = None;
    if p.text_at("get") || p.text_at("set") {
        let after = p.i + 3;
        if after < p.s.len() && (p.s[after] == b' ' || p.s[after] == b'\\n') {
            kind_tok = Some(p.i);
            p.i += 3;
            ws(p);
        }
    }
    let _ = kind_tok;
    ws(p);
    let mut stars = 0;
    if p.cur() == b'*' { p.i += 1; stars = 1; ws(p) }
    if p.text_at("async") {
        let after = p.i + 5;
        if !(after < p.s.len() && p.is_word(p.s[after])) { p.i += 5; ws(p); mods.push(p.nodes_last_id()); }
    }
    ws(p);
    let name = if p.cur() == b'[' {
        p.begin("computed_property_name", true);
        let cs = p.i;
        p.i += 1;
        tok(p, "[", false, cs);
        ws(p);
        let _ = expression(p, 0);
        ws(p);
        let _ = lit(p, "]");
        let id = p.end_node();
        p.push(id);
        Some(id)
    } else if p.cur() == b'#' {
        private_prop_ident(p)
    } else if p.cur() == b'"' || p.cur() == b'\\'' {
        string(p)
    } else {
        prop_ident(p)
    };
    let name = match name { Some(n) => n, None => { p.reset_mark(); return None } };
    f(p, name, "name");
    let _ = stars;
    ws(p);
    if p.cur() == b'<' && is_ts(L) { let _ = type_params(p); ws(p); }
    if p.cur() == b'(' {
        if !formal_parameters(p) { p.reset_mark(); return None }
        f(p, p.nodes_last_id(), "parameters");
        ws(p);
        if p.cur() == b':' {
            let _ = type_annotation(p);
            ws(p);
        }
        if p.cur() == b'{' {
            match statement_block(p) {
                Some(b) => { p.push(b); f(p, b, "body") }
                None => { p.reset_mark(); return None }
            }
        } else if is_ts(L) {
            let kids = p.frame_take();
            let s = p.frame_start();
            p.pop_frame();
            return Some(det(p, "function_signature", true, s, kids));
        } else {
            p.reset_mark();
            return None;
        }
        let kids = p.frame_take();
        let s = p.frame_start();
        p.pop_frame();
        let _ = mods;
        return Some(det(p, "method_definition", true, s, kids));
    }
    // field definition
    let mut kids = p.frame_take();
    let s = p.frame_start();
    p.pop_frame();
    if p.cur() == b'!' && is_ts(L) { p.i += 1; ws(p) }
    if p.cur() == b':' {
        let before = p.nodes.len();
        if type_annotation(p) { kids.push(p.nodes_last_id()) }
        let _ = before;
        ws(p);
    }
    if p.cur() == b'=' {
        let es = p.i; p.i += 1;
        kids.push(det(p, "=", false, es, Vec::new()));
        ws(p);
        match expression(p, 0) {
            Some(v) => { kids.push(v); f(p, v, "value") }
            None => return None,
        }
    }
    opt_semicolon(p);
    Some(det(p, "field_definition", true, s, kids))
}
