{"command": "cd /workspace && cat >> src/parser/js.rs <<'RSEOF'

// -------------------------------------------------------- import / export

fn import_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    p.begin("import_statement", true);
    if p.cur() == b'(' { p.reset_mark(); return None }
    if is_ts(L) && p.text_at("type") {
        let after = p.i + 4;
        if after < p.s.len() && (p.s[after] == b' ' || p.s[after] == b'{') {
            let save = p.i;
            kw(p, "type");
            if p.i == save + 4 { }
            else { p.i = save }
            ws(p);
        }
    }
    ws(p);
    if p.cur() == b'*' {
        p.begin("import_clause", true);
        p.begin("namespace_import", true);
        p.i += 1;
        ws(p);
        if kw(p, "as") { ws(p); let _ = ident(p).map(|x| p.push(x)); }
        p.end();
        let ni = p.nodes_last_id();
        p.push(ni);
        p.end();
        let ic = p.nodes_last_id();
        p.push(ic);
    } else if p.cur() == b'{' {
        p.begin("import_clause", true);
        if let Some(n) = named_imports(p) { p.push(n) }
        p.end();
        let ic = p.nodes_last_id();
        p.push(ic);
    } else if p.cur() == b'"' || p.cur() == b'\\'' {
        // side-effect import
    } else {
        match ident(p) {
            Some(id) => {
                p.begin("import_clause", true);
                p.push(id);
                ws(p);
                if p.cur() == b',' {
                    p.i += 1;
                    ws(p);
                    if p.cur() == b'*' {
                        p.begin("namespace_import", true);
                        p.i += 1;
                        ws(p);
                        if kw(p, "as") { ws(p); let _ = ident(p).map(|x| p.push(x)); }
                        p.end();
                        let ni = p.nodes_last_id();
                        p.push(ni);
                    } else if p.cur() == b'{' {
                        if let Some(n) = named_imports(p) { p.push(n) }
                    }
                }
                p.end();
                let ic = p.nodes_last_id();
                p.push(ic);
            }
            None => {}
        }
    }
    ws(p);
    if p.cur() == b',' { p.i += 1; ws(p); }
    let had_from = kw(p, "from");
    if had_from { ws(p); }
    if p.cur() == b'"' || p.cur() == b'\\'' {
        match string(p) {
            Some(s) => { p.push(s); f(p, s, "source") }
            None => {}
        }
    } else if !had_from {
        p.reset_mark();
        return None;
    }
    ws(p);
    if p.text_at("with") || p.text_at("assert") {
        let save = p.i;
        let _ = save;
        let _ = kw(p, "with") || kw(p, "assert");
        ws(p);
        if p.cur() == b'{' {
            p.begin("import_attribute", true);
            p.i += 1;
            loop {
                ws(p);
                if p.cur() == b'}' || p.eof() { break }
                pair_like(p);
                ws(p);
                if !lit(p, ",") { break }
            }
            ws(p);
            let _ = lit(p, "}");
            p.end();
            let ia = p.nodes_last_id();
            p.push(ia);
        }
    }
    opt_semicolon(p);
    Some(p.end_node())
}

fn pair_like(p: &mut P) {
    p.begin("pair", true);
    let key = if p.cur() == b'"' || p.cur() == b'\\'' { string(p) } else { prop_ident(p) };
    if let Some(k) = key { p.push(k); f(p, k, "key") }
    ws(p);
    if p.cur() == b':' {
        let cs = p.i; p.i += 1;
        tok(p, ":", false, cs);
        ws(p);
        let _ = expression(p, 0);
    }
    let id = p.end_node();
    p.push(id);
}

fn named_imports(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'{' { return None }
    p.begin("named_imports", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        p.begin("import_specifier", true);
        let _ = kw(p, "type");
        ws(p);
        let name = match ident(p) { Some(x) => x, None => { p.reset_mark(); break } };
        p.push(name);
        f(p, name, "name");
        ws(p);
        if kw(p, "as") {
            ws(p);
            if let Some(a) = ident(p) { p.push(a); f(p, a, "alias") }
        }
        p.end();
        let id = p.nodes_last_id();
        p.push(id);
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, "}");
    Some(p.end_node())
}

fn export_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    p.begin("export_statement", true);
    if is_ts(L) && p.text_at("type") {
        let after = p.i + 4;
        if after < p.s.len() && (p.s[after] == b' ' || p.s[after] == b'{') {
            kw(p, "type");
            ws(p);
        }
    }
    ws(p);
    if p.cur() == b'*' {
        p.i += 1;
        ws(p);
        if kw(p, "as") { ws(p); let _ = ident(p).map(|x| p.push(x)); ws(p); }
        if kw(p, "from") {
            ws(p);
            if let Some(s) = string(p) { p.push(s); f(p, s, "source") }
        }
        opt_semicolon(p);
        return Some(p.end_node());
    }
    if p.text_at("default") {
        kw(p, "default");
        ws(p);
        let mut kids = vec![p.nodes_last_id()];
        if let Some(e) = expression(p, 0) { kids.push(e); f(p, e, "value") }
        opt_semicolon(p);
        return Some(det(p, "export_statement", true, start, kids));
    }
    if p.cur() == b'{' {
        p.begin("export_clause", true);
        p.i += 1;
        loop {
            ws(p);
            if p.cur() == b'}' || p.eof() { break }
            p.begin("export_specifier", true);
            let _ = kw(p, "type");
            ws(p);
            let name = match ident(p) { Some(x) => x, None => { p.reset_mark(); break } };
            p.push(name);
            f(p, name, "name");
            ws(p);
            if kw(p, "as") {
                ws(p);
                if let Some(a) = ident(p) { p.push(a); f(p, a, "alias") }
            }
            p.end();
            let id = p.nodes_last_id();
            p.push(id);
            ws(p);
            if !lit(p, ",") { break }
        }
        ws(p);
        let _ = lit(p, "}");
        let cl = p.end_node();
        p.push(cl);
        ws(p);
        if kw(p, "from") {
            ws(p);
            if let Some(s) = string(p) { p.push(s); f(p, s, "source") }
        }
        opt_semicolon(p);
        return Some(p.end_node());
    }
    match declaration(p) {
        Some(d) => {
            p.push(d);
            f(p, d, "declaration");
            opt_semicolon(p);
            Some(p.end_node())
        }
        None => { p.reset_mark(); None }
    }
}

fn declaration(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    let m = p.mark();
    if kw(p, "const") || kw(p, "let") {
        let k = p.nodes_last_id();
        let d = lexical_declaration(p, start, k);
        if let Some(d) = d { return Some(d) }
        p.reset(m);
    } else if kw(p, "var") {
        let k = p.nodes_last_id();
        let d = variable_declaration(p, start, k);
        if let Some(d) = d { return Some(d) }
        p.reset(m);
    } else if kw(p, "function") {
        ws(p);
        let mut is_gen = false;
        if p.cur() == b'*' { p.i += 1; ws(p); is_gen = true }
        let mut kids = Vec::new();
        if let Some(n) = ident(p) { kids.push(n); f(p, n, "name") }
        ws(p);
        if formal_parameters(p) {
            kids.push(p.nodes_last_id());
            f(p, p.nodes_last_id(), "parameters");
            ws(p);
            if let Some(b) = statement_block(p) {
                kids.push(b);
                f(p, b, "body");
                let kind = if is_gen { "generator_function_declaration" } else { "function_declaration" };
                return Some(det(p, kind, true, start, kids));
            }
        }
        p.reset(m);
    } else if kw(p, "class") {
        return class_decl(p, true);
    } else if is_ts(L) && kw(p, "interface") {
        return interface_declaration(p);
    } else if is_ts(L) && kw(p, "type") {
        return type_alias(p);
    } else if is_ts(L) && kw(p, "enum") {
        return enum_declaration(p);
    }
    None
}
