// --------------------------------------------------- TS type declarations

fn interface_declaration(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    p.begin("interface_declaration", true);
    let mut kids = Vec::new();
    match ident(p) { Some(x) => { kids.push(x); f(p, x, "name") }, None => { p.reset_mark(); return None } }
    ws(p);
    if p.cur() == b'<' { let _ = type_params(p); kids.push(p.nodes_last_id()); ws(p) }
    if p.cur() == b':' {
        let _ = type_annotation(p);
        kids.push(p.nodes_last_id());
        ws(p);
    }
    if p.cur() != b'{' { p.reset_mark(); return None }
    p.begin("object_type", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        let ms = p.i;
        if p.cur() == b'[' {
            p.begin("index_signature", true);
            let _ = type_(p);
            ws(p);
            let _ = lit(p, "]");
            ws(p);
            let _ = lit(p, ":");
            ws(p);
            let _ = type_(p);
            p.end();
            let id = p.nodes_last_id();
            p.push(id);
        } else {
            let is_method = p.cur() == b'(' || p.cur() == b'*';
            p.begin(if is_method { "method_signature" } else { "property_signature" }, true);
            loop {
                ws(p);
                if kw(p, "readonly") || kw(p, "public") || kw(p, "private")
                    || kw(p, "protected") || kw(p, "static") { continue }
                break
            }
            ws(p);
            if is_method {
                if p.cur() == b'*' { p.i += 1 }
                ws(p);
                if p.cur() != b'(' { let _ = prop_ident(p).map(|x| p.push(x)); }
                ws(p);
                let _ = formal_parameters(p);
                ws(p);
                if p.cur() == b':' { let _ = type_annotation(p); }
            } else {
                let _ = prop_ident(p).map(|x| p.push(x));
                ws(p);
                let _ = lit(p, "?");
                ws(p);
                if p.cur() == b':' { let _ = type_annotation(p); }
            }
            let id = p.end_node();
            p.push(id);
            let _ = ms;
        }
        ws(p);
        if !lit(p, ";") { let _ = lit(p, ","); }
        if p.cur() == b'}' { break }
    }
    ws(p);
    let _ = lit(p, "}");
    let body = p.end_node();
    p.push(body);
    kids.push(body);
    Some(det(p, "interface_declaration", true, start, kids))
}

fn type_alias(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    p.begin("type_alias_declaration", true);
    let mut kids = Vec::new();
    match ident(p) { Some(x) => { kids.push(x); f(p, x, "name") }, None => { p.reset_mark(); return None } }
    ws(p);
    if p.cur() == b'<' { let _ = type_params(p); kids.push(p.nodes_last_id()); ws(p) }
    if !lit(p, "=") { p.reset_mark(); return None }
    kids.push(p.nodes_last_id());
    ws(p);
    if !type_(p) { p.reset_mark(); return None }
    kids.push(p.nodes_last_id());
    opt_semicolon(p);
    Some(det(p, "type_alias_declaration", true, start, kids))
}

fn enum_declaration(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    p.begin("enum_declaration", true);
    let mut kids = Vec::new();
    match ident(p) { Some(x) => { kids.push(x); f(p, x, "name") }, None => { p.reset_mark(); return None } }
    ws(p);
    if p.cur() != b'{' { p.reset_mark(); return None }
    p.begin("enum_body", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        p.begin("enum_member", true);
        match prop_ident(p) {
            Some(x) => p.push(x),
            None => { p.reset_mark(); break }
        }
        ws(p);
        if p.cur() == b'=' {
            let es = p.i; p.i += 1;
            tok(p, "=", false, es);
            ws(p);
            let _ = expression(p, 0);
        }
        p.end();
        let id = p.nodes_last_id();
        p.push(id);
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, "}");
    let body = p.end_node();
    p.push(body);
    kids.push(body);
    Some(det(p, "enum_declaration", true, start, kids))
}

fn ambient_or_namespace(p: &mut P) -> Option<u32> {
    let start = p.i;
    let kwid = p.nodes_last_id();
    let is_declare = kind_of(p, kwid) == "declare";
    ws(p);
    if p.text_at("namespace") || p.text_at("module") {
        let _ = kw(p, "namespace") || kw(p, "module");
        ws(p);
        p.begin("ambient_declaration", true);
        let mut kids = Vec::new();
        let _ = ident(p).map(|x| p.push(x));
        ws(p);
        if p.cur() == b'{' {
            if let Some(b) = statement_block(p) { kids.push(b) }
        }
        let id = p.end_node();
        p.push(id);
        let _ = is_declare;
        return Some(id);
    }
    match declaration(p) {
        Some(d) => {
            p.begin("ambient_declaration", true);
            p.push(d);
            let id = p.end_node();
            p.push(id);
            Some(id)
        }
        None => { p.reset_mark(); None }
    }
}

// ------------------------------------------------------------------- JSX

fn jsx_element(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'<' { return None }
    p.begin("jsx_element", true);
    if !jsx_opening_tag(p) { p.reset_mark(); return None }
    loop {
        ws(p);
        if p.eof() { break }
        if p.text_at("</") {
            if !jsx_closing_tag(p) { break }
            break;
        }
        if p.cur() == b'<' {
            let m = p.mark();
            match jsx_element(p) {
                Some(e) => p.push(e),
                None => { p.reset(m); jsx_text(p); }
            }
            continue;
        }
        if p.cur() == b'{' {
            p.begin("jsx_expression", true);
            p.i += 1;
            ws(p);
            if p.cur() == b'}' {
                let es = p.i; p.i += 1;
                tok(p, "}", false, es);
            } else {
                let _ = expression(p, 0);
                ws(p);
                let _ = lit(p, "}");
            }
            let id = p.end_node();
            p.push(id);
            continue;
        }
        jsx_text(p);
    }
    Some(p.end_node())
}

fn jsx_text(p: &mut P) {
    let start = p.i;
    while !p.eof() && p.cur() != b'<' && p.cur() != b'{' { p.i += 1 }
    if p.i > start { p.push(det(p, "jsx_text", true, start, Vec::new())); }
}

fn jsx_opening_tag(p: &mut P) -> bool {
    let start = p.i;
    p.i += 1;
    ws(p);
    if ident(p).is_none() { p.reset_to_pos(start); return false }
    loop {
        if p.cur() == b'.' || p.cur() == b':' {
            p.i += 1;
            if ident(p).is_none() { break }
        } else { break }
    }
    ws(p);
    loop {
        ws(p);
        if p.cur() == b'>' || p.cur() == b'/' || p.eof() { break }
        let as_ = p.i;
        if p.cur() == b'{' {
            p.begin("jsx_expression", true);
            p.i += 1;
            ws(p);
            let _ = expression(p, 0);
            ws(p);
            let _ = lit(p, "}");
            let id = p.end_node();
            p.push(id);
            continue;
        }
        p.begin("jsx_attribute", true);
        if jsx_attribute_name(p).is_none() { p.reset_mark(); p.reset_to_pos(as_); break }
        ws(p);
        if p.cur() == b'=' {
            let es = p.i; p.i += 1;
            tok(p, "=", false, es);
            ws(p);
            if p.cur() == b'"' || p.cur() == b'\\'' {
                p.begin("jsx_attribute_value", true);
                let qs = p.i;
                let q = p.cur();
                p.i += 1;
                tok(p, if q == b'"' { "\\"" } else { "'" }, false, qs);
                let ts = p.i;
                while !p.eof() && p.cur() != q { p.i += 1 }
                if p.i > ts { p.push(det(p, "jsx_text", true, ts, Vec::new())) }
                if p.cur() == q {
                    let qe = p.i; p.i += 1;
                    tok(p, if q == b'"' { "\\"" } else { "'" }, false, qe);
                }
                let id = p.end_node();
                p.push(id);
            } else if p.cur() == b'{' {
                p.begin("jsx_expression", true);
                p.i += 1;
                ws(p);
                let _ = expression(p, 0);
                ws(p);
                let _ = lit(p, "}");
                let id = p.end_node();
                p.push(id);
            } else {
                let _ = expression(p, 0);
            }
        }
        let id = p.end_node();
        p.push(id);
    }
    ws(p);
    if p.text_at("/>") {
        let kids = p.frame_take();
        let s = p.frame_start();
        p.pop_frame();
        p.i += 2;
        let id = det(p, "jsx_self_closing_element", true, s, kids);
        p.push(id);
        return true;
    }
    if !lit(p, ">") { p.reset_to_pos(start); return false }
    true
}

fn jsx_closing_tag(p: &mut P) -> bool {
    let start = p.i;
    p.i += 2;
    ws(p);
    if ident(p).is_none() { p.reset_to_pos(start); return false }
    loop {
        if p.cur() == b'.' || p.cur() == b':' { p.i += 1; if ident(p).is_none() { break } } else { break }
    }
    ws(p);
    if !lit(p, ">") { p.reset_to_pos(start); return false }
    true
}

fn jsx_attribute_name(p: &mut P) -> Option<u32> {
    if ident(p).is_none() { return None }
    loop {
        if p.cur() == b'-' {
            p.i += 1;
            if ident(p).is_none() { break }
        } else { break }
    }
    Some(p.nodes_last_id())
}

// ------------------------------------------------------------------ program

pub fn parse_program(p: &mut P) {
    p.begin("program", true);
    loop {
        ws(p);
        if p.eof() { break }
        if p.text_at("#!") {
            let start = p.i;
            while !p.eof() && p.cur() != b'\\n' { p.i += 1 }
            p.push(det(p, "hash_bang_line", true, start, Vec::new()));
            continue;
        }
        match statement(p) {
            Some(id) => p.push(id),
            None => error_recovery(p),
        }
    }
    p.end_node();
    let id = p.nodes_last_id();
    p.push(id);
