# Frame-less functions: expression / unary_chain / postfix / primary / postfix_no_call
def to_det(src, name):
    m = re.search(r'^(?:pub )?fn %s\(' % re.escape(name), src, re.M)
    if not m: return src
    start = m.start()
    rest = src[start:]
    lines = rest.split('\n')
    out = []
    depth = 0
    for i, l in enumerate(lines):
        if i == 0:
            depth = l.count('{') - l.count('}')
            out.append(l); continue
        depth += l.count('{') - l.count('}')
        l = l.replace('tok(p, ', 'toks(p, ')
        l = re.sub(r'\blit\(p, ', 'litd(p, ', l)
        l = re.sub(r'\bkw\(p, ', 'kwd(p, ', l)
        out.append(l)
        if depth <= 0:
            break
    new = '\n'.join(out)
    return src[:start] + new + src[start+len(rest):]
for fn in ['expression','unary_chain','postfix','primary','postfix_no_call']:
    s = to_det(s, fn)
open(p,'w').write(s)
