                ws(p);
                if !formal_parameters(p) { return None }
                kids.push(p.nodes_last_id());
                ws(p);
                if let Some(b) = statement_block(p) { kids.push(b) } else { return None }
                Some(det(p, "function_expression", true, start, kids))
