fn postfix_no_call(p: &mut P) -> Option<u32> {
    let mut base = match primary(p) { Some(x) => x, None => return None };
    loop {
        ws(p);
        let save = p.i;
        if p.cur() == b'.' || p.text_at("?.") {
            let ms = p.i;
            let is_opt = p.text_at("?.");
            p.i += if is_opt { 2 } else { 1 };
            let mut kids = vec![base];
            if is_opt {
                let oc = det(p, "optional_chain", true, ms, Vec::new());
                kids.push(oc);
                f(p, oc, "optional_chain");
            } else {
                kids.push(toks(p, ".", false, ms));
            }
            ws(p);
            let prop = if p.cur() == b'#' { private_prop_ident(p) } else { prop_ident(p) };
            let prop = match prop { Some(x) => x, None => { p.i = save; break } };
            kids.push(prop);
            f(p, prop, "property");
            let s = ns(p, base);
            base = det(p, "member_expression", true, s, kids);
            continue;
        }
        if p.cur() == b'[' {
            let ms = p.i;
            p.i += 1;
            let bk = toks(p, "[", false, ms);
            ws(p);
            let idx = match expression(p, 0) { Some(x) => x, None => { p.i = save; break } };
            ws(p);
            if litd(p, "]").is_none() { p.i = save; break }
            let s = ns(p, base);
            base = det(p, "subscript_expression", true, s, vec![base, bk, idx]);
            f(p, base, "object");
            f(p, idx, "index");
            continue;
        }
        break;
    }
    Some(base)
}

fn arrow_function(p: &mut P) -> Option<u32> {
    let start = p.i;
    let m = p.mark();
    let mut kids = Vec::new();
    if p.text_at("async") {
        let after = p.i + 5;
        if !(after < p.s.len() && p.is_word(p.s[after])) {
            kwd(p, "async");
            kids.push(p.nodes_last_id());
            ws(p);
        }
    }
    if p.cur() == b'(' {
        if !formal_parameters(p) { p.reset(m); return None }
        kids.push(p.nodes_last_id());
    } else {
        match ident(p) { Some(x) => kids.push(x), None => { p.reset(m); return None } }
    }
    ws(p);
    if p.cur() == b':' {
        let _ = type_annotation(p);
        kids.push(p.nodes_last_id());
        ws(p);
    }
    if !(p.cur() == b'=' && p.cur2() == b'>') { p.reset(m); return None }
    let as_ = p.i;
    p.i += 2;
    kids.push(toks(p, "=>", false, as_));
    ws(p);
    if p.cur() == b'{' {
        match statement_block(p) {
            Some(b) => kids.push(b),
            None => { p.reset(m); return None }
        }
    } else {
        match assignment_expr(p) {
            Some(e) => kids.push(e),
            None => { p.reset(m); return None }
        }
    }
    Some(det(p, "arrow_function", true, start, kids))
}

fn object(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'{' { return None }
    p.begin("object", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        let m = p.mark();
        match class_member(p) {
            Some(id) => p.push(id),
            None => { p.reset(m); break }
        }
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, "}");
    Some(p.end_node())
}

fn array(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'[' { return None }
    p.begin("array", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b']' || p.eof() { break }
        if p.text_at("...") {
            p.begin("spread_element", true);
            let rs = p.i;
            p.i += 3;
            tok(p, "...", false, rs);
            ws(p);
            let _ = expression(p, 0);
            let id = p.end_node();
            p.push(id);
        } else {
            match expression(p, 0) {
                Some(e) => p.push(e),
                None => { if p.cur() != b',' { break } }
            }
        }
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, "]");
    Some(p.end_node())
}
