// ------------------------------------------------------------- statements

pub fn statement_block(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'{' { return None }
    p.begin("statement_block", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        match statement(p) {
            Some(id) => p.push(id),
            None => error_recovery(p),
        }
    }
    ws(p);
    let _ = lit(p, "}");
    Some(p.end_node())
}

fn error_recovery(p: &mut P) {
    let start = p.i;
    if p.eof() { return }
    while !p.eof() {
        let c = p.cur();
        if c == b';' { p.i += 1; break }
        if c == b'\n' { p.i += 1; break }
        if c == b'}' { break }
        p.i += 1;
    }
    let n = det(p, "ERROR", true, start, Vec::new());
    p.push(n);
}

fn opt_semicolon(p: &mut P) {
    let save = p.i;
    let nn = p.nodes_len();
    let nk = p.frame_kids_len();
    p.ws_nonl(L);
    if p.cur() == b';' {
        lit(p, ";");
    } else {
        p.reset_partial(save, nn, nk);
    }
}

pub fn statement(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    let c = p.cur();
    match c {
        b';' => {
            p.i += 1;
            Some(det(p, "empty_statement", true, start, Vec::new()))
        }
        b'{' => statement_block(p),
        b'#' if p.text_at("#!") => {
