                if p.cur() == b'}' || p.eof() || p.text_at("case") || p.text_at("default") { break }
                match statement(p) { Some(s) => p.push(s), None => break }
            }
            let id = p.end_node();
            p.push(id);
        } else {
            break;
        }
    }
    ws(p);
    let _ = lit(p, "}");
    let body = p.end_node();
    p.push(body);
    f(p, body, "body");
    kids.push(body);
    opt_semicolon(p);
    Some(det(p, "switch_statement", true, start, kids))
}
