{"command": "cd /workspace && cat > /tmp/part3.rs <<'RSEOF'

// ------------------------------------------------------------- statements

pub fn statement_block(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'{' { return None }
    p.begin("statement_block", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        match statement(p) {
            Some(id) => p.push(id),
            None => error_recovery(p),
        }
    }
    ws(p);
    let _ = lit(p, "}");
    Some(p.end_node())
}

fn error_recovery(p: &mut P) {
    let start = p.i;
    if p.eof() { return }
    while !p.eof() {
        let c = p.cur();
        if c == b';' { p.i += 1; break }
        if c == b'\n' { p.i += 1; break }
        if c == b'}' { break }
        p.i += 1;
    }
    let n = det(p, "ERROR", true, start, Vec::new());
    p.push(n);
}

fn opt_semicolon(p: &mut P) {
    let save = p.i;
    let nn = p.nodes_len();
    let nk = p.frame_kids_len();
    p.ws_nonl(L);
    if p.cur() == b';' {
        lit(p, ";");
    } else {
        p.reset_partial(save, nn, nk);
    }
}

pub fn statement(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    let c = p.cur();
    match c {
        b';' => {
            p.i += 1;
            Some(det(p, "empty_statement", true, start, Vec::new()))
        }
        b'{' => statement_block(p),
        b'#' if p.text_at("#!") => {
            while !p.eof() && p.cur() != b'\n' { p.i += 1 }
            Some(det(p, "hash_bang_line", true, start, Vec::new()))
        }
        b'@' => {
            decorators(p);
            statement(p)
        }
        _ => {
            let m = p.mark();
            if kw(p, "const") || kw(p, "let") {
                let kind_id = p.nodes_last_id();
                if let Some(d) = lexical_declaration(p, start, kind_id) { return Some(d) }
                p.reset(m);
            } else if kw(p, "var") {
                let kind_id = p.nodes_last_id();
                if let Some(d) = variable_declaration(p, start, kind_id) { return Some(d) }
                p.reset(m);
            } else if kw(p, "function") {
                if let Some(id) = function_declaration(p, start, false) { return Some(id) }
                p.reset(m);
            } else if kw(p, "class") {
                if let Some(id) = class_decl(p, true) { return Some(id) }
                p.reset(m);
            } else if kw(p, "if") {
                if let Some(id) = if_statement(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "for") {
                if let Some(id) = for_statement(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "while") {
                ws(p);
                if p.cur() == b'(' {
                    if let Some(cond) = parenthesized(p) {
                        if let Some(b) = statement(p) {
                            f(p, cond, "condition");
                            f(p, b, "body");
                            opt_semicolon(p);
                            return Some(det(p, "while_statement", true, start, vec![cond, b]));
                        }
                    }
                }
                p.reset(m);
            } else if kw(p, "do") {
                ws(p);
                let body = match statement(p) { Some(b) => b, None => { p.reset(m); return None } };
                ws(p);
                let mut kids = vec![body];
                if kw(p, "while") {
                    ws(p);
                    if let Some(cond) = parenthesized(p) {
                        kids.push(cond);
                        f(p, cond, "condition");
                    }
                }
                opt_semicolon(p);
                return Some(det(p, "do_statement", true, start, kids));
            } else if kw(p, "try") {
                if let Some(id) = try_statement(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "switch") {
                if let Some(id) = switch_statement(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "return") {
                ws(p);
                let mut kids = Vec::new();
                if p.cur() != b';' && p.cur() != b'}' && !p.eof() {
                    if let Some(e) = expression(p, 0) { kids.push(e) }
                }
                opt_semicolon(p);
                return Some(det(p, "return_statement", true, start, kids));
            } else if kw(p, "throw") {
                ws(p);
                let e = expression(p, 0);
                opt_semicolon(p);
                let kids = match e { Some(e) => vec![e], None => vec![] };
                return Some(det(p, "throw_statement", true, start, kids));
            } else if kw(p, "break") || kw(p, "continue") {
                let is_break = kind_of(p, p.nodes_last_id()) == "break";
                let kind = if is_break { "break_statement" } else { "continue_statement" };
                ws(p);
                let mut kids = Vec::new();
                if p.cur() != b';' && p.cur() != b'}' {
                    if let Some(l) = ident(p) { kids.push(l); f(p, l, "label") }
                }
                opt_semicolon(p);
                return Some(det(p, kind, true, start, kids));
            } else if kw(p, "debugger") {
                opt_semicolon(p);
                return Some(det(p, "debugger_statement", true, start, Vec::new()));
            } else if kw(p, "import") {
                if let Some(id) = import_statement(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "export") {
                if let Some(id) = export_statement(p) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && kw(p, "interface") {
                if let Some(id) = interface_declaration(p) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && kw(p, "type") {
                if let Some(id) = type_alias(p) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && kw(p, "enum") {
                if let Some(id) = enum_declaration(p) { return Some(id) }
                p.reset(m);
            } else if is_ts(L) && (kw(p, "declare") || kw(p, "namespace") || kw(p, "module")) {
                if let Some(id) = ambient_or_namespace(p) { return Some(id) }
                p.reset(m);
            } else if kw(p, "async") {
                let after = p.i;
                if !(after < p.s.len() && p.is_word(p.s[after])) {
                    p.i = after;
                    ws(p);
                    if p.text_at("function") {
                        if let Some(id) = function_declaration(p, start, true) { return Some(id) }
                    }
                }
                p.reset(m);
            }
            // labeled statement
            {
                let save = p.i;
                if let Some(l) = ident(p) {
                    ws(p);
                    if p.cur() == b':' {
                        let cs = p.i;
                        p.i += 1;
                        ws(p);
                        if let Some(b) = statement(p) {
                            f(p, l, "label");
                            f(p, b, "body");
                            let colon = toks(p, ":", false, cs);
                            return Some(det(p, "labeled_statement", true, start, vec![l, colon, b]));
                        }
                    }
                }
                p.i = save;
            }
            p.begin("expression_statement", true);
            let e = expression(p, 0)?;
            p.push(e);
            opt_semicolon(p);
            let id = p.end_node();
            p.push(id);
            Some(id)
        }
    }
}

fn function_declaration(p: &mut P, start: usize, after_async: bool) -> Option<u32> {
    let mut kids = Vec::new();
    if after_async {
        let a = kwd(p, "async");
        if let Some(a) = a { kids.push(a) }
        ws(p);
    }
    if !kw(p, "function") { return None }
    kids.push(p.nodes_last_id());
    ws(p);
    let mut is_gen = false;
    if p.cur() == b'*' {
        p.i += 1;
        ws(p);
        is_gen = true;
        kids.push(p.nodes_last_id());
    }
    if let Some(n) = ident(p) { kids.push(n); f(p, n, "name") }
    ws(p);
    if !formal_parameters(p) { return None }
    kids.push(p.nodes_last_id());
    f(p, p.nodes_last_id(), "parameters");
    ws(p);
    match statement_block(p) {
        Some(b) => {
            kids.push(b);
            f(p, b, "body");
            let kind = if is_gen { "generator_function_declaration" } else { "function_declaration" };
            Some(det(p, kind, true, start, kids))
        }
        None => None,
    }
}

fn if_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    if p.cur() != b'(' { return None }
    let cond = parenthesized(p)?;
    let body = statement(p)?;
    let mut kids = vec![cond, body];
    f(p, cond, "condition");
    f(p, body, "consequence");
    ws(p);
    if p.text_at("else") {
        p.begin("else_clause", true);
        kw(p, "else");
        ws(p);
        if let Some(s) = statement(p) { p.push(s) }
        let alt = p.end_node();
        p.push(alt);
        f(p, alt, "alternative");
        kids.push(alt);
    }
    opt_semicolon(p);
    Some(det(p, "if_statement", true, start, kids))
}

fn try_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    let body = statement_block(p)?;
    let mut kids = vec![body];
    f(p, body, "body");
    ws(p);
    if p.text_at("catch") {
        p.begin("catch_clause", true);
        kw(p, "catch");
        ws(p);
        if p.cur() == b'(' {
            p.begin("catch_parameters", true);
            p.i += 1;
            ws(p);
            if let Some(x) = pattern(p) { p.push(x) }
            ws(p);
            let _ = lit(p, ")");
            let cp = p.end_node();
            p.push(cp);
            f(p, cp, "pattern");
        }
        ws(p);
        if let Some(b) = statement_block(p) {
            p.push(b);
            f(p, b, "body");
        }
        let h = p.end_node();
        p.push(h);
        f(p, h, "handler");
        kids.push(h);
        ws(p);
    }
    if p.text_at("finally") {
        p.begin("finally_clause", true);
        kw(p, "finally");
        ws(p);
        if let Some(b) = statement_block(p) {
            p.push(b);
            f(p, b, "body");
        }
        let fin = p.end_node();
        p.push(fin);
        f(p, fin, "finalizer");
        kids.push(fin);
        ws(p);
    }
    opt_semicolon(p);
    Some(det(p, "try_statement", true, start, kids))
}

fn switch_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    let val = parenthesized(p)?;
    let mut kids = vec![val];
    f(p, val, "value");
    ws(p);
    if p.cur() != b'{' { return None }
    p.begin("switch_body", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        if p.text_at("case") {
            p.begin("switch_case", true);
            kw(p, "case");
            ws(p);
            if let Some(v) = expression(p, 0) {
                p.push(v);
                f(p, v, "value");
            }
            ws(p);
            let _ = lit(p, ":");
            loop {
                ws(p);
                if p.cur() == b'}' || p.eof() || p.text_at("case") || p.text_at("default") { break }
                match statement(p) { Some(s) => p.push(s), None => break }
            }
            let id = p.end_node();
            p.push(id);
        } else if p.text_at("default") {
            p.begin("switch_default", true);
            kw(p, "default");
            ws(p);
            let _ = lit(p, ":");
            loop {
                ws(p);
                if p.cur() == b'}' || p.eof() || p.text_at("case") || p.text_at("default") { break }
                match statement(p) { Some(s) => p.push(s), None => break }
            }
            let id = p.end_node();
            p.push(id);
        } else {
            break;
        }
    }
    ws(p);
    let _ = lit(p, "}");
    let body = p.end_node();
    p.push(body);
    f(p, body, "body");
    kids.push(body);
    opt_semicolon(p);
    Some(det(p, "switch_statement", true, start, kids))
}
