{"command": "cd /workspace && cat > /tmp/part4.rs <<'RSEOF'

// ------------------------------------------------------------- declarations

fn lexical_declaration(p: &mut P, start: usize, kind_id: u32) -> Option<u32> {
    p.begin("lexical_declaration", true);
    p.push(kind_id);
    f(p, kind_id, "kind");
    loop {
        ws(p);
        match declarator(p) {
            Some(d) => p.push(d),
            None => break,
        }
        ws(p);
        if !lit(p, ",") { break }
    }
    opt_semicolon(p);
    Some(p.end_node())
}

fn variable_declaration(p: &mut P, start: usize, kind_id: u32) -> Option<u32> {
    p.begin("variable_declaration", true);
    p.push(kind_id);
    loop {
        ws(p);
        match declarator(p) {
            Some(d) => p.push(d),
            None => break,
        }
        ws(p);
        if !lit(p, ",") { break }
    }
    opt_semicolon(p);
    let _ = start;
    Some(p.end_node())
}

fn declarator(p: &mut P) -> Option<u32> {
    let start = p.i;
    p.begin("variable_declarator", true);
    let name = match pattern(p) { Some(x) => x, None => { p.reset_mark(); return None } };
    p.push(name);
    f(p, name, "name");
    ws(p);
    if p.cur() == b'!' && is_ts(L) {
        let es = p.i; p.i += 1;
        tok(p, "!", false, es);
        ws(p);
    }
    if p.cur() == b':' {
        let _ = type_annotation(p);
        ws(p);
    }
    if p.cur() == b'=' {
        let es = p.i; p.i += 1;
        tok(p, "=", false, es);
        ws(p);
        match expression(p, 0) {
            Some(v) => { p.push(v); f(p, v, "value") }
            None => { p.reset_mark(); return None }
        }
    }
    Some(p.end_node())
}

fn for_left(p: &mut P) -> Option<u32> {
    ws(p);
    let m = p.mark();
    let is_decl = kw(p, "const") || kw(p, "let") || kw(p, "var");
    if is_decl {
        let kind_id = p.nodes_last_id();
        let is_var = kind_of(p, kind_id) == "var";
        let save = p.i;
        ws(p);
        match pattern(p) {
            Some(pat) => {
                ws(p);
                let inof = p.text_at("of") || p.text_at("in");
                p.begin(if is_var { "variable_declaration" } else { "lexical_declaration" }, true);
                p.push(kind_id);
                if !is_var { f(p, kind_id, "kind") }
                p.push(pat);
                f(p, pat, "name");
                if inof {
                    return Some(p.end_node());
                }
                ws(p);
                if p.cur() == b':' {
                    let _ = type_annotation(p);
                    ws(p);
                }
                if p.cur() == b'=' {
                    let es = p.i; p.i += 1;
                    tok(p, "=", false, es);
                    ws(p);
                    if let Some(v) = expression(p, 0) { p.push(v); f(p, v, "value") }
                }
                loop {
                    ws(p);
                    match declarator(p) {
                        Some(d) => p.push(d),
                        None => break,
                    }
                    ws(p);
                    if !lit(p, ",") { break }
                }
                return Some(p.end_node());
            }
            None => { p.reset(m); return None }
        }
    }
    expression(p, 0)
}

fn for_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    if p.cur() != b'(' { return None }
    p.begin("for_statement", true);
    let mut kids = Vec::new();
    if kw(p, "await") { kids.push(p.nodes_last_id()); ws(p) }
    p.i += 1; // (
    tok(p, "(", false, start);
    ws(p);
    if p.cur() == b';' {
        let ss = p.i;
        p.i += 1;
        kids.push(toks(p, ";", false, ss));
    } else {
        match for_left(p) {
            Some(left) => {
                ws(p);
                if p.text_at("in") || p.text_at("of") {
                    let op = p.i;
                    let w = if p.s[op] == b'i' { "in" } else { "of" };
                    p.i += 2;
                    kids.push(toks(p, w, false, op));
                    ws(p);
                    if let Some(r) = expression(p, 0) { kids.push(r) }
                    ws(p);
                    if !lit(p, ")") { p.reset_mark(); return None }
                    ws(p);
                    match statement(p) {
                        Some(b) => kids.push(b),
                        None => { p.reset_mark(); return None }
                    }
                    opt_semicolon(p);
                    let id = det(p, "for_in_statement", true, start, kids);
                    p.push(id);
                    return Some(id);
                }
                kids.push(left);
                f(p, left, "initializer");
                ws(p);
                let _ = lit(p, ";");
            }
            None => {}
        }
    }
    ws(p);
    if p.cur() != b';' {
        if let Some(c) = expression(p, 0) { kids.push(c); f(p, c, "condition") }
    }
    ws(p);
    let _ = lit(p, ";");
    ws(p);
    if p.cur() != b')' {
        if let Some(u) = expression(p, 0) { kids.push(u); f(p, u, "increment") }
    }
    ws(p);
    if !lit(p, ")") { p.reset_mark(); return None }
    ws(p);
    match statement(p) {
        Some(b) => { kids.push(b); f(p, b, "body") }
        None => { p.reset_mark(); return None }
    }
    opt_semicolon(p);
    Some(det(p, "for_statement", true, start, kids))
}

// ---------------------------------------------------------------- classes

fn class_decl(p: &mut P, top_level: bool) -> Option<u32> {
    let start = p.i;
    let _ = top_level;
    ws(p);
    let is_abstract = kw(p, "abstract");
    ws(p);
    let mut kids = Vec::new();
    if is_abstract { kids.push(p.nodes_last_id()) }
    if let Some(n) = ident(p) { kids.push(n); f(p, n, "name") }
    ws(p);
    if kw(p, "extends") {
        ws(p);
        p.begin("class_heritage", true);
        let _ = expression(p, 0);
        let h = p.end_node();
        p.push(h);
        kids.push(h);
    } else if is_ts(L) && kw(p, "implements") {
        p.begin("class_heritage", true);
        ws(p);
        loop {
            ws(p);
            if !type_(p) { break }
            ws(p);
            if !lit(p, ",") { break }
        }
        let h = p.end_node();
        p.push(h);
        kids.push(h);
    }
    ws(p);
    if p.cur() != b'{' { return None }
    let body = class_body(p)?;
    f(p, body, "body");
    kids.push(body);
    let kind = if is_abstract { "abstract_class_declaration" } else { "class_declaration" };
    Some(det(p, kind, true, start, kids))
}

fn class_body(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'{' { return None }
    p.begin("class_body", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        let m = p.mark();
        match class_member(p) {
            Some(id) => p.push(id),
            None => { p.reset(m); error_recovery(p); }
        }
    }
    ws(p);
    let _ = lit(p, "}");
    Some(p.end_node())
}

fn class_member(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    if p.text_at("static") {
        let after = p.i + 6;
        if after < p.s.len() && p.s[after] == b'{' {
            let ss = p.i;
            p.i += 6;
            ws(p);
            if let Some(b) = statement_block(p) {
                opt_semicolon(p);
                return Some(det(p, "class_static_block", true, ss, vec![b]));
            }
        }
    }
    p.begin("method_definition", true);
    loop {
        ws(p);
        if kw(p, "public") || kw(p, "private") || kw(p, "protected")
            || kw(p, "static") || kw(p, "abstract") || kw(p, "override") || kw(p, "declare")
            || kw(p, "readonly")
        { continue }
        break
    }
    ws(p);
    if p.text_at("get") || p.text_at("set") {
        let after = p.i + 3;
        if after < p.s.len() && (p.s[after] == b' ' || p.s[after] == b'\n') {
            p.i += 3;
            ws(p);
        }
    }
    ws(p);
    if p.cur() == b'*' { p.i += 1; ws(p) }
    if p.text_at("async") {
        let after = p.i + 5;
        if !(after < p.s.len() && p.is_word(p.s[after])) { p.i += 5; ws(p); }
    }
    ws(p);
    let name = if p.cur() == b'[' {
        p.begin("computed_property_name", true);
        let cs = p.i;
        p.i += 1;
        tok(p, "[", false, cs);
        ws(p);
        let _ = expression(p, 0);
        ws(p);
        let _ = lit(p, "]");
        let id = p.end_node();
        p.push(id);
        Some(id)
    } else if p.cur() == b'#' {
        private_prop_ident(p)
    } else if p.cur() == b'"' || p.cur() == b'\'' {
        string(p)
    } else {
        prop_ident(p)
    };
    let name = match name { Some(n) => n, None => { p.reset_mark(); return None } };
