    let name = match name { Some(n) => n, None => { p.reset_mark(); return None } };
    f(p, name, "name");
    ws(p);
    if p.cur() == b'<' && is_ts(L) { let _ = type_params(p); ws(p); }
    if p.cur() == b'(' {
        if !formal_parameters(p) { p.reset_mark(); return None }
        f(p, p.nodes_last_id(), "parameters");
        ws(p);
        if p.cur() == b':' {
            let _ = type_annotation(p);
            ws(p);
        }
        if p.cur() == b'{' {
            match statement_block(p) {
                Some(b) => { p.push(b); f(p, b, "body") }
                None => { p.reset_mark(); return None }
            }
        } else if is_ts(L) {
            let kids = p.frame_take();
            let s = p.frame_start();
            p.pop_frame();
            return Some(det(p, "function_signature", true, s, kids));
        } else {
            p.reset_mark();
            return None;
        }
        let kids = p.frame_take();
        let s = p.frame_start();
        p.pop_frame();
        return Some(det(p, "method_definition", true, s, kids));
    }
    // field definition
    let mut kids = p.frame_take();
    let s = p.frame_start();
    p.pop_frame();
    if p.cur() == b'!' && is_ts(L) { p.i += 1; ws(p) }
    if p.cur() == b':' {
        if type_annotation(p) { kids.push(p.nodes_last_id()) }
        ws(p);
    }
    if p.cur() == b'=' {
        let es = p.i; p.i += 1;
        kids.push(det(p, "=", false, es, Vec::new()));
        ws(p);
        match expression(p, 0) {
            Some(v) => { kids.push(v); f(p, v, "value") }
            None => return None,
        }
    }
    opt_semicolon(p);
    Some(det(p, "field_definition", true, s, kids))
}
