fn pair_like(p: &mut P) {
    p.begin("pair", true);
    let key = if p.cur() == b'"' || p.cur() == b'\'' { string(p) } else { prop_ident(p) };
    if let Some(k) = key { p.push(k); f(p, k, "key") }
    ws(p);
    if p.cur() == b':' {
        let cs = p.i; p.i += 1;
        tok(p, ":", false, cs);
        ws(p);
        let _ = expression(p, 0);
    }
    let id = p.end_node();
    p.push(id);
}

fn named_imports(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'{' { return None }
    p.begin("named_imports", true);
    p.i += 1;
    loop {
        ws(p);
        if p.cur() == b'}' || p.eof() { break }
        p.begin("import_specifier", true);
        let _ = kw(p, "type");
        ws(p);
        let name = match ident(p) { Some(x) => x, None => { p.reset_mark(); break } };
        p.push(name);
        f(p, name, "name");
        ws(p);
        if kw(p, "as") {
            ws(p);
            if let Some(a) = ident(p) { p.push(a); f(p, a, "alias") }
        }
        p.end();
        p.push(p.nodes_last_id());
        ws(p);
        if !lit(p, ",") { break }
    }
    ws(p);
    let _ = lit(p, "}");
    Some(p.end_node())
}

fn export_statement(p: &mut P) -> Option<u32> {
    let start = p.i;
    ws(p);
    p.begin("export_statement", true);
    if is_ts(L) && p.text_at("type") {
        let after = p.i + 4;
        if after < p.s.len() && (p.s[after] == b' ' || p.s[after] == b'{') {
            kw(p, "type");
            ws(p);
        }
    }
    ws(p);
    if p.cur() == b'*' {
        p.i += 1;
        ws(p);
        if kw(p, "as") { ws(p); if let Some(x) = ident(p) { p.push(x) } ws(p); }
        if kw(p, "from") {
            ws(p);
            if let Some(s) = string(p) { p.push(s); f(p, s, "source") }
        }
        opt_semicolon(p);
        return Some(p.end_node());
    }
    if p.text_at("default") {
        kw(p, "default");
        ws(p);
        let mut kids = vec![p.nodes_last_id()];
        if let Some(e) = expression(p, 0) { kids.push(e); f(p, e, "value") }
        opt_semicolon(p);
        return Some(det(p, "export_statement", true, start, kids));
    }
    if p.cur() == b'{' {
        p.begin("export_clause", true);
        p.i += 1;
        loop {
            ws(p);
            if p.cur() == b'}' || p.eof() { break }
            p.begin("export_specifier", true);
            let _ = kw(p, "type");
            ws(p);
            let name = match ident(p) { Some(x) => x, None => { p.reset_mark(); break } };
