fn declaration(p: &mut P) -> Option<u32> {
    ws(p);
    let start = p.i;
    let m = p.mark();
    if kw(p, "const") || kw(p, "let") {
        let k = p.nodes_last_id();
        if let Some(d) = lexical_declaration(p, start, k) { return Some(d) }
        p.reset(m);
    } else if kw(p, "var") {
        let k = p.nodes_last_id();
        if let Some(d) = variable_declaration(p, start, k) { return Some(d) }
        p.reset(m);
    } else if kw(p, "function") {
        if let Some(d) = function_declaration(p, start, false) { return Some(d) }
        p.reset(m);
    } else if kw(p, "class") {
        return class_decl(p, true);
    } else if is_ts(L) && kw(p, "interface") {
        return interface_declaration(p);
    } else if is_ts(L) && kw(p, "type") {
        return type_alias(p);
    } else if is_ts(L) && kw(p, "enum") {
        return enum_declaration(p);
