                ws(p);
                let _ = lit(p, "?");
                ws(p);
                if p.cur() == b':' { let _ = type_annotation(p); }
            }
            let id = p.end_node();
            p.push(id);
            let _ = ms;
        }
        ws(p);
        if !lit(p, ";") { let _ = lit(p, ","); }
        if p.cur() == b'}' { break }
    }
    ws(p);
    let _ = lit(p, "}");
