fn jsx_element(p: &mut P) -> Option<u32> {
    let start = p.i;
    if p.cur() != b'<' { return None }
    p.begin("jsx_element", true);
    if !jsx_opening_tag(p) { p.reset_mark(); return None }
    loop {
        ws(p);
        if p.eof() { break }
        if p.text_at("</") {
            if !jsx_closing_tag(p) { break }
            break;
        }
        if p.cur() == b'<' {
            let m = p.mark();
            match jsx_element(p) {
                Some(e) => p.push(e),
                None => { p.reset(m); jsx_text(p); }
            }
            continue;
        }
        if p.cur() == b'{' {
            p.begin("jsx_expression", true);
            p.i += 1;
            ws(p);
            if p.cur() == b'}' {
                let es = p.i; p.i += 1;
                tok(p, "}", false, es);
            } else {
                let _ = expression(p, 0);
                ws(p);
                let _ = lit(p, "}");
            }
            let id = p.end_node();
            p.push(id);
            continue;
        }
        jsx_text(p);
    }
    Some(p.end_node())
}

fn jsx_text(p: &mut P) {
    let start = p.i;
    while !p.eof() && p.cur() != b'<' && p.cur() != b'{' { p.i += 1 }
    if p.i > start { p.push(det(p, "jsx_text", true, start, Vec::new())); }
}

fn jsx_opening_tag(p: &mut P) -> bool {
    let start = p.i;
